impl MessagesManager {
    pub fn new() -> MessagesManager {
        // `= static_cast<int64>(MIN_PINNED_DIALOG_DATE) << 32`
        // (MessagesManager.h:3392).
        MessagesManager {
            current_pinned_dialog_order: i64::from(MIN_PINNED_DIALOG_DATE) << 32,
            ..MessagesManager::default()
        }
    }

    /// `MessagesManager::get_dialog` (the map lookup form).
    pub fn get_dialog(&self, dialog_id: DialogId) -> Option<&Dialog> {
        self.dialogs.get(&dialog_id).map(|d| d.as_ref())
    }

    pub fn get_dialog_mut(&mut self, dialog_id: DialogId) -> Option<&mut Dialog> {
        self.dialogs.get_mut(&dialog_id).map(|d| d.as_mut())
    }

    /// `MessagesManager::load_calls_db_state` (MessagesManager.cpp:3782-3796)
    /// — the `calls_db_state` pmc row, -1 counts until loaded.
    pub fn load_calls_db_state(&mut self, td_db_is_message_database: bool) {
        // the sqlite sync pmc read lands with the Td wiring slice; the
        // in-memory -1 seeding is the loadable part
        if !td_db_is_message_database {
            return;
        }
        self.calls_db_state.message_count_by_index = [-1, -1];
    }

    /// `MessagesManager::add_dialog_for_new_message` + `add_dialog`
    /// (MessagesManager.cpp:33044-33076) — the fresh-dialog core: the map
    /// insert with the C++ in-class defaults. The message-database
    /// synchronous load of `add_dialog` and the per-kind init of
    /// `add_new_dialog` (has_bots/forum flags/`updateNewChat` emission)
    /// ride the DialogDb/chat-manager receive slices.
    pub fn add_dialog_for_new_message(&mut self, dialog_id: DialogId) -> &mut Dialog {
        let dialog = self.dialogs.entry(dialog_id).or_insert_with(|| {
            let mut dialog = Box::new(Dialog::default());
            dialog.dialog_id = dialog_id;
            dialog
        });
        dialog.as_mut()
    }

    /// `MessagesManager::on_get_message(DialogId, telegram_api::Message,
    /// bool, bool, const char *)` + the `MessageInfo` overload
    /// (MessagesManager.cpp:11910-12179) — the receive-path head. The
    /// created `Message` is returned to the caller until the per-dialog
    /// message containers land (M.10.9): the C++ continues into
    /// `add_message_to_dialog` → `send_update_new_message`, whose
    /// ordering/notification/update fan-out is the recorded seam
    /// (the media-fetch scheduling call of the plan, `load_message_content`,
    /// is M.10.18's scheduler).
    pub fn on_get_message(
        &mut self,
        ctx: &mut dyn MessageObjectContext,
        message_ptr: telegram_api::Message,
        from_update: bool,
        is_scheduled: bool,
        source: &str,
    ) -> Option<(DialogId, Box<Message>)> {
        let message_info =
            parse_telegram_api_message(ctx, message_ptr, is_scheduled, false, source);
        self.on_get_message_info(ctx, message_info, from_update, source)
    }

    /// `MessagesManager::on_get_message(MessageInfo &&, bool, const char *)`
    /// (MessagesManager.cpp:11944-12179) — the head through the new-message
    /// branch; the sent-message re-add branch and the post-add update
    /// fan-out are the recorded seams of the slice split.
    pub fn on_get_message_info(
        &mut self,
        ctx: &mut dyn MessageObjectContext,
        message_info: MessageInfo,
        from_update: bool,
        source: &str,
    ) -> Option<(DialogId, Box<Message>)> {
        let report_delivery_until_date = message_info.report_delivery_until_date;
        let (dialog_id, new_message) = create_message(ctx, self, message_info, false, source);
        let mut new_message = new_message?;
        let message_id = new_message.message_id;
        if report_delivery_until_date != 0 && message_id.is_server() {
            // `message_query_manager_->report_message_delivery`
            // (MessagesManager.cpp:11952-11954) — the delivery-report
            // query plane is the net slice's owner; the date rides the
            // message until then.
        }

        let is_ephemeral = new_message.ephemeral_message_id.is_valid();
        let old_message_id = if is_ephemeral {
            *self
                .update_ephemeral_message_ids
                .get(&EphemeralMessageFullId::new(
                    dialog_id,
                    new_message.ephemeral_message_id,
                ))
                .unwrap_or(&MessageId::default())
        } else {
            *self
                .update_message_ids
                .get(&(dialog_id, message_id))
                .unwrap_or(&MessageId::default())
        };
        if old_message_id.is_valid() || old_message_id.is_valid_scheduled() {
            // The sent-message re-add branch (MessagesManager.cpp:12008+):
            // `update_reply_to_message_id` → `delete_message` →
            // `update_message` → `send_update_message_send_succeeded` all
            // belong to the delete/edit/send slices that own the containers;
            // a duplicate intake cannot be re-added here.
            log_error!(
                "Receive a duplicate {} in {:?} from {}",
                DisplayMessageId(message_id),
                dialog_id,
                source
            );
            return None;
        }
        let _ = from_update;

        self.add_dialog_for_new_message(dialog_id);

        // The reactions context views the same object — the banned-chat
        // read is the ChatManager status cache, answered by the same
        // surface until the receive slices unify the two traits.
        let reactions_ctx = MessageObjectReactionsContext { ctx: &*ctx };
        fix_new_message(
            self,
            &reactions_ctx,
            &*ctx,
            dialog_id,
            &mut new_message,
            false,
        );

        // The media-fetch scheduling call of the plan:
        // `load_message_content` (MessagesManager.cpp:12300+) fires inside
        // `add_message_to_dialog` per received message; the load scheduler
        // is M.10.18's and the call stays the recorded seam until then.
        //
        // `add_message_to_dialog` (MessagesManager.cpp:12263+) continues:
        // the ordered-messages insert, last-message/counter maintenance,
        // `send_update_new_message`, the awaited promises, live locations,
        // reply counts, the inaccessible-chat deletion and the reply-markup
        // dialog update are the M.10.9+ receive-path fan-out.

        Some((dialog_id, new_message))
    }
}

/// The `DialogReactionsContext` view of a `MessageObjectContext` —
/// `is_chat_banned` is the ChatManager status cache read; the standalone
/// banned-chat queries land with the ChatManager receive slice.
pub struct MessageObjectReactionsContext<'a> {
    pub(crate) ctx: &'a dyn MessageObjectContext,
}

impl<'a> MessageObjectReactionsContext<'a> {
    /// The 5-view send adapter builds the reactions view over the same Td
    /// the ctx/state pair aliases (the sequential discipline of
    /// `split_context_alias`).
    pub(crate) fn new(ctx: &'a dyn MessageObjectContext) -> Self {
        MessageObjectReactionsContext { ctx }
    }
}

impl DialogReactionsContext for MessageObjectReactionsContext<'_> {
    fn is_chat_banned(&self, _dialog_id: DialogId) -> bool {
        false
    }

    fn is_bot(&self) -> bool {
        self.ctx.is_bot()
    }
}

/// `MessagesManager::get_message_sender` (MessagesManager.cpp:6200-6204).
pub fn get_message_sender(m: &Message) -> DialogId {
    if m.sender_dialog_id.is_valid() {
        m.sender_dialog_id
    } else {
        DialogId::from_user_id(m.sender_user_id)
    }
}

/// `MessagesManager::get_dialog_reply_markup(DialogId,
/// td_api::ReplyMarkup &&)` (MessagesManager.cpp:24319-24328) — the
/// td_api intake body lives in [`crate::reply_markup::get_reply_markup`]
/// (the M.22 unification); the manager keeps the context-driven wrapper.
pub fn get_dialog_reply_markup(
    ctx: &dyn SendMessageContext,
    dialog_id: DialogId,
    reply_markup: Option<td_api::ReplyMarkup>,
) -> Result<Option<ReplyMarkup>, (i32, String)> {
    let is_anonymous = ctx.is_anonymous_administrator(dialog_id).is_some();
    get_reply_markup(
        reply_markup,
        dialog_id.get_type(),
        ctx.is_admined_monoforum_channel(dialog_id),
        ctx.is_bot(),
        is_anonymous,
        ctx.is_test_dc(),
    )
    .map_err(|status| (status.code(), status.message().to_owned()))
}

/// `MessagesManager::get_message_search_text` (MessagesManager.cpp:8138-8143)
/// — [blocked: M.9.17] `get_message_content_search_text` lands with the
/// lifecycle tail; the empty string is the recorded stand-in.
pub fn get_message_search_text(m: &Message) -> String {
    if m.is_content_secret {
        return String::new();
    }
    String::new()
}

/// `MessagesManager::is_discussion_message` (MessagesManager.cpp:23913-23934)
/// — the linked-dialog lookups ride the manager maps.
pub fn is_discussion_message(
    manager: &MessagesManager,
    ctx: &dyn DialogReactionsContext,
    dialog_id: DialogId,
    m: &Message,
) -> bool {
    let Some(forward_info) = &m.forward_info else {
        return false;
    };
    if m.sender_user_id.is_valid() {
        // only the service notifications bot posts discussion messages as a
        // user
        if !ctx.is_bot()
            || m.sender_user_id.get()
                != crate::user_manager::UserManager::get_service_notifications_user_id().get()
        {
            return false;
        }
    }
    let linked_dialog_id = forward_info.get_last_dialog_id();
    if !linked_dialog_id.is_valid() || linked_dialog_id == dialog_id {
        return false;
    }
    match dialog_id.get_type() {
        DialogType::User => {
            linked_dialog_id.get_type() == DialogType::Channel
                && manager
                    .get_dialog(linked_dialog_id)
                    .is_some_and(|d| d.is_forum)
        }
        DialogType::Channel => {
            // is_megagroup_channel of the dialog — the channel kind rides
            // the chat status; false until that slice ([blocked: M.5 seam])
            false
        }
        _ => false,
    }
}

/// `MessagesManager::get_active_reactions` (MessagesManager.cpp:6416-6421).
pub fn get_active_reactions(
    manager: &MessagesManager,
    ctx: &dyn DialogReactionsContext,
    available_reactions: &ChatReactions,
) -> ChatReactions {
    if ctx.is_bot() {
        return available_reactions.clone();
    }
    // `ChatReactions::get_active_reactions` (ChatReactions.cpp) — filters
    // the reaction set to the active ones; with the empty Wave-2 cache the
    // paid flag survives and the regular set empties
    let mut result = available_reactions.clone();
    result
        .reaction_types
        .retain(|reaction_type| manager.active_reaction_pos.contains_key(reaction_type));
    result.allow_all_regular = false;
    result.allow_all_custom = false;
    result
}

/// `MessagesManager::need_hide_dialog_reactions`
/// (MessagesManager.cpp:27558-27571).
pub fn need_hide_dialog_reactions(ctx: &dyn DialogReactionsContext, dialog_id: DialogId) -> bool {
    match dialog_id.get_type() {
        DialogType::User | DialogType::SecretChat => false,
        DialogType::Chat | DialogType::Channel => ctx.is_chat_banned(dialog_id),
        DialogType::None => false,
    }
}

/// `MessagesManager::get_dialog_active_reactions`
/// (MessagesManager.cpp:6423-6440).
pub fn get_dialog_active_reactions(
    manager: &MessagesManager,
    ctx: &dyn DialogReactionsContext,
    d: &Dialog,
) -> ChatReactions {
    if need_hide_dialog_reactions(ctx, d.dialog_id) {
        return ChatReactions::default();
    }
    match d.dialog_id.get_type() {
        DialogType::User => ChatReactions::from_all_flags(true, true),
        DialogType::Chat | DialogType::Channel => {
            get_active_reactions(manager, ctx, &d.available_reactions)
        }
        _ => ChatReactions::default(),
    }
}

/// `MessagesManager::get_message_active_reactions`
/// (MessagesManager.cpp:6391-6414).
pub fn get_message_active_reactions(
    manager: &MessagesManager,
    ctx: &dyn DialogReactionsContext,
    d: &Dialog,
    m: &Message,
) -> ChatReactions {
    if !m.message_id.is_server() {
        return ChatReactions::default();
    }
    if !m.reactions_are_possible
        && crate::message_content::is_service_message_content(
            m.content.as_ref().unwrap().get_type(),
        )
    {
        return ChatReactions::default();
    }
    if is_discussion_message(manager, ctx, d.dialog_id, m) {
        let linked_dialog_id = m.forward_info.as_ref().unwrap().last_message_info.dialog_id;
        return match manager.get_dialog(linked_dialog_id) {
            Some(linked_d) => get_dialog_active_reactions(manager, ctx, linked_d),
            None => ChatReactions::default(),
        };
    }
    get_dialog_active_reactions(manager, ctx, d)
}

/// `MessagesManager::has_unread_message_reactions`
/// (MessagesManager.cpp:5005-5012).
pub fn has_unread_message_reactions(
    manager: &MessagesManager,
    ctx: &dyn DialogReactionsContext,
    dialog_id: DialogId,
    m: &Message,
) -> bool {
    if ctx.is_bot() {
        return false;
    }
    let Some(reactions) = &m.reactions else {
        return false;
    };
    if reactions.unread_reactions.is_empty() {
        return false;
    }
    // `is_visible_message_reactions` (MessagesManager.cpp:6370-6390)
    let Some(d) = manager.get_dialog(dialog_id) else {
        return false;
    };
    if get_message_active_reactions(manager, ctx, d, m).empty() {
        return false;
    }
    m.available_reactions_generation == d.available_reactions_generation
}

/// `MessagesManager::has_unread_poll_votes` (MessagesManager.cpp:5014-5023).
pub fn has_unread_poll_votes(ctx: &dyn DialogReactionsContext, m: &Message) -> bool {
    if ctx.is_bot() {
        return false;
    }
    if m.forward_info.is_some()
        || m.content.as_ref().unwrap().get_type() != MessageContentType::Poll
    {
        return false;
    }
    false // [blocked: M.9.17] get_message_content_poll_has_unread_votes over the poll manager seam
}

// ---- the available-reactions request plane (the M.react slice;
// Requests.cpp:6082-6087, MessagesManager.cpp:30373-30424) ----

/// The `Td *td` slice of `set_dialog_available_reactions`. The access
/// checks answer the collapsed-world bands (the M.6 dialog integration
/// owns the full rights/restrictions family), the update emitters are
/// the M.7/M.10 emission plane, and the server query is the net seam.
pub trait DialogAvailableReactionsEnv: crate::chat_reactions::ChatReactionsEnv {
    /// `td_->auth_manager_->is_bot()`.
    fn is_bot(&self) -> bool;

    /// `td_->dialog_manager_->is_broadcast_channel(dialog_id)` — the
    /// `allow_all_custom` input of the td_api conversion.
    fn is_broadcast_channel(&mut self, dialog_id: DialogId) -> bool;

    /// `td_->dialog_manager_->check_dialog_access(dialog_id, false,
    /// AccessRights::Read, source)`.
    fn check_dialog_access(
        &mut self,
        dialog_id: DialogId,
        allow_secret_chats: bool,
        access_rights: AccessRights,
        source: &str,
    ) -> Result<(), Status>;

    /// `td_->chat_manager_->get_chat_permissions(chat_id)`.
    fn get_chat_permissions(&mut self, chat_id: ChatId) -> DialogParticipantStatus;

    /// `td_->chat_manager_->is_appointed_chat_administrator(chat_id)` —
    /// the bot leg of the basic-group rights check.
    fn is_appointed_chat_administrator(&mut self, chat_id: ChatId) -> bool;

    /// `td_->chat_manager_->get_channel_permissions(channel_id)`.
    fn get_channel_permissions(&mut self, channel_id: ChannelId) -> DialogParticipantStatus;

    /// `need_hide_dialog_reactions(d)` — the ban gate of the
    /// client-update emission; the collapsed line answers false (the M.6
    /// ban plane).
    fn is_chat_banned(&mut self, dialog_id: DialogId) -> bool {
        let _ = dialog_id;
        false
    }

    // -- the update plane ([blocked: M.7/M.10 emission])
    /// `send_closure(G()->td(), &Td::send_update, ...)`.
    fn send_update(&mut self, _update: td_api::Update) {}
    /// `send_update_message_unread_reactions(dialog_id, m,
    /// d->unread_reaction_count)` — the message-object build is the
    /// emission plane.
    fn send_update_message_unread_reactions(
        &mut self,
        _dialog_id: DialogId,
        _message_id: MessageId,
        _unread_reaction_count: i32,
    ) {
    }
    /// `send_update_message_interaction_info(dialog_id, m)`.
    fn send_update_message_interaction_info(
        &mut self,
        _dialog_id: DialogId,
        _message_id: MessageId,
    ) {
    }

    // -- the net query seam ([blocked: net])
    /// `td_->dialog_manager_->set_dialog_available_reactions_on_server`
    /// — the changed-reactions server ack; dropping the promise keeps
    /// the C++ request unanswered offline.
    fn set_dialog_available_reactions_on_server(
        &mut self,
        dialog_id: DialogId,
        available_reactions: &ChatReactions,
        promise: tdutils::promise::Promise<()>,
    ) {
        let _ = (dialog_id, available_reactions, promise);
    }
}

/// `operator==(ChatReactions, ChatReactions)` (ChatReactions.cpp:138-142)
/// over the dialog-store form — `allow_all_custom` is deliberately not
/// compared, unlike the derived `PartialEq` of this module's struct.
fn chat_reactions_eq(lhs: &ChatReactions, rhs: &ChatReactions) -> bool {
    lhs.reaction_types == rhs.reaction_types
        && lhs.allow_all_regular == rhs.allow_all_regular
        && lhs.reactions_limit == rhs.reactions_limit
        && lhs.paid_reactions_available == rhs.paid_reactions_available
}

/// `ChatReactions::get_active_reactions` (ChatReactions.cpp:76-87) over
/// the dialog-store form — the M.16 container method's semantics; the
/// older [`get_active_reactions`] above records the Wave-2
/// simplification used by the chat-object plane.
fn get_active_reactions_exact(
    pos: &HashMap<ReactionType, usize>,
    available_reactions: &ChatReactions,
) -> ChatReactions {
    let mut result = available_reactions.clone();
    if !result.reaction_types.is_empty() {
        debug_assert!(!result.allow_all_regular);
        debug_assert!(!result.allow_all_custom);
        result
            .reaction_types
            .retain(|reaction_type| pos.contains_key(reaction_type));
    }
    result
}

/// `MessagesManager::get_active_reactions` (MessagesManager.cpp:6416-6421).
fn get_active_reactions_member(
    is_bot: bool,
    pos: &HashMap<ReactionType, usize>,
    available_reactions: &ChatReactions,
) -> ChatReactions {
    if is_bot {
        return available_reactions.clone();
    }
    get_active_reactions_exact(pos, available_reactions)
}

/// The dialog-store `ChatReactions` rebuilt as the M.16 behavior
/// container — the two Rust structs split the same C++ class (and the
/// two `ReactionType`s share the string encoding); the converters
/// collapse at the M.16/M.10 dialog integration.
fn chat_reactions_to_container(reactions: &ChatReactions) -> crate::chat_reactions::ChatReactions {
    crate::chat_reactions::ChatReactions {
        reaction_types: reactions
            .reaction_types
            .iter()
            .map(|reaction_type| {
                crate::reaction_type::ReactionType::new(reaction_type.get_string().to_owned())
            })
            .collect(),
        allow_all_regular: reactions.allow_all_regular,
        allow_all_custom: reactions.allow_all_custom,
        reactions_limit: reactions.reactions_limit,
        paid_reactions_available: reactions.paid_reactions_available,
    }
}

/// `get_chat_id_object(dialog_id, source)` for the chat/channel ids this
/// plane emits — both wire kinds carry a `chat_id`.
fn get_chat_id_object(dialog_id: DialogId) -> i64 {
    match dialog_id.get_type() {
        DialogType::Chat => dialog_id.get_chat_id().get(),
        DialogType::Channel => dialog_id.get_channel_id().get(),
        _ => 0,
    }
}

/// `MessagesManager::set_dialog_available_reactions`
/// (MessagesManager.cpp:30373-30424).
pub fn set_dialog_available_reactions(
    manager: &mut MessagesManager,
    env: &mut impl DialogAvailableReactionsEnv,
    dialog_id: DialogId,
    available_reactions: Option<td_api::ChatAvailableReactions>,
    mut promise: tdutils::promise::Promise<()>,
) {
    if let Err(status) = env.check_dialog_access(
        dialog_id,
        false,
        AccessRights::Read,
        "set_dialog_available_reactions",
    ) {
        return promise.set_error(status);
    }

    let allow_all_custom = !env.is_broadcast_channel(dialog_id);
    // `ChatReactions(td_api::object_ptr<ChatAvailableReactions>, bool)`
    // (ChatReactions.cpp:51-74) over the M.16 container, then the
    // dialog-store copy.
    let converted =
        crate::chat_reactions::ChatReactions::from_td_api(available_reactions, allow_all_custom);
    let mut available_reactions = ChatReactions {
        reaction_types: converted
            .reaction_types()
            .iter()
            .map(|reaction_type| ReactionType::new(reaction_type.get_string()))
            .collect(),
        allow_all_regular: converted.allow_all_regular(),
        allow_all_custom: converted.allow_all_custom(),
        reactions_limit: converted.reactions_limit(),
        paid_reactions_available: converted.paid_reactions_available(),
    };

    let active_reactions = get_active_reactions_member(
        env.is_bot(),
        &manager.active_reaction_pos,
        &available_reactions,
    );
    if active_reactions.reaction_types.len() != available_reactions.reaction_types.len() {
        return promise.set_error(Status::error(400, "Invalid reactions specified"));
    }
    available_reactions = active_reactions;

    match dialog_id.get_type() {
        DialogType::User => {
            return promise.set_error(Status::error(
                400,
                "Can't change private chat available reactions",
            ));
        }
        DialogType::Chat => {
            let chat_id = dialog_id.get_chat_id();
            let status = env.get_chat_permissions(chat_id);
            if !status.can_change_info_and_settings()
                || (env.is_bot() && !env.is_appointed_chat_administrator(chat_id))
            {
                return promise.set_error(Status::error(
                    400,
                    "Not enough rights to change chat available reactions",
                ));
            }
        }
        DialogType::Channel => {
            let status = env.get_channel_permissions(dialog_id.get_channel_id());
            if !status.can_change_info_and_settings() {
                return promise.set_error(Status::error(
                    400,
                    "Not enough rights to change chat available reactions",
                ));
            }
        }
        DialogType::SecretChat | DialogType::None => {
            unreachable!("check_dialog_access only passes users, basic groups and channels")
        }
    }

    // the pos snapshot feeds both the dialog tail and the update build;
    // clone it before the dialog borrow aliases the manager
    let pos = manager.active_reaction_pos.clone();
    let Some(d) = manager.get_dialog_mut(dialog_id) else {
        // C++ receives `d` from the same access check; the collapsed
        // access check consults the chat/user managers, so the dialog
        // can still be missing in memory.
        return promise.set_error(Status::error(400, "Chat not found"));
    };

    let is_changed = !chat_reactions_eq(&d.available_reactions, &available_reactions);
    let is_bot = env.is_bot();
    // the C++ passes a copy into the private setter, keeping the
    // active-filtered value alive for the server query below; the
    // db-save tail returns to the caller because the dialog borrow
    // aliases the manager
    let need_db_save =
        set_dialog_available_reactions_in_dialog(env, &pos, d, available_reactions.clone(), is_bot);
    if need_db_save {
        on_dialog_updated(manager, dialog_id, "set_dialog_available_reactions");
    }

    if !is_changed {
        return promise.set_value(());
    }

    env.set_dialog_available_reactions_on_server(dialog_id, &available_reactions, promise);
}

/// `MessagesManager::set_dialog_available_reactions(Dialog *, ChatReactions)`
/// (MessagesManager.cpp:6265-6303) — returns whether `on_dialog_updated`
/// must fire.
fn set_dialog_available_reactions_in_dialog(
    env: &mut impl DialogAvailableReactionsEnv,
    pos: &HashMap<ReactionType, usize>,
    d: &mut Dialog,
    mut available_reactions: ChatReactions,
    is_bot: bool,
) -> bool {
    match d.dialog_id.get_type() {
        DialogType::Chat | DialogType::Channel => {}
        _ => unreachable!("set_dialog_available_reactions expects a basic group or a channel"),
    }
    if env.is_broadcast_channel(d.dialog_id) {
        // `fix_broadcast_reactions(active_reaction_types_)` — the pos map
        // keys in their position order
        let mut active_reaction_types: Vec<ReactionType> = pos.keys().cloned().collect();
        active_reaction_types.sort_by_key(|reaction_type| pos[reaction_type]);
        available_reactions.fix_broadcast_reactions(&active_reaction_types);
    }
    if chat_reactions_eq(&d.available_reactions, &available_reactions) {
        if !d.is_available_reactions_inited {
            d.is_available_reactions_inited = true;
            return true;
        }
        return false;
    }

    let old_active_reactions = get_active_reactions_member(is_bot, pos, &d.available_reactions);
    let new_active_reactions = get_active_reactions_member(is_bot, pos, &available_reactions);
    let need_update = !chat_reactions_eq(&old_active_reactions, &new_active_reactions);
    let need_update_message_reactions_visibility =
        old_active_reactions.empty() != new_active_reactions.empty() && !is_bot;

    d.available_reactions = available_reactions;
    d.is_available_reactions_inited = true;
    if need_update_message_reactions_visibility {
        if !old_active_reactions.empty() {
            hide_dialog_message_reactions(env, d);
        }
        set_dialog_next_available_reactions_generation(env, pos, d);
    }

    if need_update {
        send_update_chat_available_reactions(env, pos, d);
    }
    true
}

/// `MessagesManager::hide_dialog_message_reactions`
/// (MessagesManager.cpp:6340-6362) — the local half; the message-object
/// builds and the db resave ride the emission plane.
fn hide_dialog_message_reactions(env: &mut impl DialogAvailableReactionsEnv, d: &mut Dialog) {
    debug_assert!(!env.is_bot());
    match d.dialog_id.get_type() {
        DialogType::Chat | DialogType::Channel => {}
        _ => unreachable!("hide_dialog_message_reactions expects a basic group or a channel"),
    }
    let message_ids = find_dialog_messages(d, |m| {
        m.reactions
            .as_ref()
            .is_some_and(|reactions| !reactions.are_empty())
    });
    for message_id in message_ids {
        let Some(m) = d.messages.get_mut(&message_id) else {
            unreachable!("find_dialog_messages returned a message the dialog does not hold");
        };
        let need_update_unread_reactions = m
            .reactions
            .as_ref()
            .is_some_and(|reactions| !reactions.unread_reactions.is_empty());
        m.reactions = None;
        // don't resave all messages to the database
        if need_update_unread_reactions {
            env.send_update_message_unread_reactions(
                d.dialog_id,
                message_id,
                d.unread_reaction_count,
            );
        }
        env.send_update_message_interaction_info(d.dialog_id, message_id);
    }
    if d.unread_reaction_count != 0 {
        // `set_dialog_unread_reaction_count(d, 0)` — the local field; the
        // repair/update tail is the M.10.7 counters plane
        d.unread_reaction_count = 0;
    }
}

/// `MessagesManager::set_dialog_next_available_reactions_generation`
/// (MessagesManager.cpp:6306-6333).
fn set_dialog_next_available_reactions_generation(
    env: &impl DialogAvailableReactionsEnv,
    pos: &HashMap<ReactionType, usize>,
    d: &mut Dialog,
) {
    match d.dialog_id.get_type() {
        DialogType::Chat | DialogType::Channel => {}
        _ => unreachable!("the generation plane expects a basic group or a channel"),
    }
    let generation =
        if get_active_reactions_member(env.is_bot(), pos, &d.available_reactions).empty() {
            // 0 -> 1
            // 1 -> 3
            d.available_reactions_generation + (d.available_reactions_generation & 1) + 1
        } else {
            // 0 -> 2
            // 1 -> 2
            d.available_reactions_generation - (d.available_reactions_generation & 1) + 2
        };
    d.available_reactions_generation = generation;
}

/// `MessagesManager::send_update_chat_available_reactions`
/// (MessagesManager.cpp:27574-27585).
fn send_update_chat_available_reactions(
    env: &mut impl DialogAvailableReactionsEnv,
    pos: &HashMap<ReactionType, usize>,
    d: &mut Dialog,
) {
    // LOG_CHECK(d->is_update_new_chat_sent) — the in-memory setter plane
    // keeps the flag set by the time this runs
    debug_assert!(d.is_update_new_chat_sent);
    // `need_hide_dialog_reactions(d)` (MessagesManager.cpp:27558-27571)
    let need_hide = match d.dialog_id.get_type() {
        DialogType::Chat | DialogType::Channel => env.is_chat_banned(d.dialog_id),
        _ => false,
    };
    if !need_hide || !d.last_need_hide_reactions {
        d.last_need_hide_reactions = need_hide;
        // `get_dialog_active_reactions(d)` (MessagesManager.cpp:6423-6440)
        let available_reactions = match d.dialog_id.get_type() {
            DialogType::User => ChatReactions::from_all_flags(true, true),
            DialogType::Chat | DialogType::Channel => {
                get_active_reactions_member(env.is_bot(), pos, &d.available_reactions)
            }
            _ => ChatReactions::default(),
        };
        let available_reactions = Some(
            chat_reactions_to_container(&available_reactions)
                .get_chat_available_reactions_object(env),
        );
        env.send_update(td_api::Update::updateChatAvailableReactions(
            td_api::updateChatAvailableReactions {
                chat_id: get_chat_id_object(d.dialog_id),
                available_reactions,
            },
        ));
    }
}

/// `MessagesManager::get_message_index_mask` (MessagesManager.cpp:4161-4197).
pub fn get_message_index_mask(
    manager: &MessagesManager,
    ctx: &dyn DialogReactionsContext,
    content_ctx: &dyn crate::message_content::MessageContentContext,
    dialog_id: DialogId,
    m: &Message,
) -> i32 {
    if ctx.is_bot() || m.message_id.is_scheduled() || m.message_id.is_yet_unsent() {
        return 0;
    }
    if m.is_failed_to_send {
        return message_search_filter_index_mask(MessageSearchFilter::FailedToSend);
    }
    let is_secret = dialog_id.get_type() == DialogType::SecretChat;
    if !m.message_id.is_server() && !is_secret {
        return 0;
    }

    let mut index_mask = 0;
    if m.is_pinned {
        index_mask |= message_search_filter_index_mask(MessageSearchFilter::Pinned);
    }
    // retain second condition just in case
    if m.is_content_secret || (!m.ttl.is_empty() && !is_secret) {
        return index_mask;
    }
    index_mask |= crate::message_content::get_message_content_index_mask(
        content_ctx,
        m.content.as_ref().unwrap(),
        m.is_outgoing,
    );
    if m.contains_mention {
        index_mask |= message_search_filter_index_mask(MessageSearchFilter::Mention);
        if m.contains_unread_mention {
            index_mask |= message_search_filter_index_mask(MessageSearchFilter::UnreadMention);
        }
    }
    if has_unread_message_reactions(manager, ctx, dialog_id, m) {
        index_mask |= message_search_filter_index_mask(MessageSearchFilter::UnreadReaction);
    }
    if has_unread_poll_votes(ctx, m) {
        index_mask |= message_search_filter_index_mask(MessageSearchFilter::UnreadPollVote);
    }
    index_mask
}

/// `MessagesManager::add_message_to_database` (MessagesManager.cpp:31866-31929)
/// — over the M.6 async engine. The `time` bundle feeds the
/// `ttl_expires_at` relative conversion.
#[allow(clippy::too_many_arguments)]
pub fn add_message_to_database(
    global: &crate::global::Global,
    manager: &mut MessagesManager,
    reactions_ctx: &dyn DialogReactionsContext,
    content_ctx: &dyn crate::message_content::MessageContentContext,
    time: &crate::user_manager::TimeCtx,
    dialog_id: DialogId,
    m: &Message,
    source: &str,
) {
    if !global.use_message_database() {
        return;
    }

    let message_id = m.message_id;

    if message_id.is_scheduled() {
        tracing::info!(
            "Add message {}:{} to database from {}",
            dialog_id.get(),
            message_id.get(),
            source
        );
        // `set_dialog_has_scheduled_database_messages` rides the dialog
        // state slice (M.10.3); the engine write is the loadable half
        let mut data = Vec::new();
        store_message_log_event(m, &MessageDbStorageBridge, time, &mut data);
        global.message_db_async().add_scheduled_message(
            MessageFullId::new(dialog_id, message_id),
            data,
            tdutils::promise::PromiseCreator::lambda(|()| ()),
        );
        return;
    }
    debug_assert!(message_id.is_server() || message_id.is_local());

    tracing::info!(
        "Add message {}:{} to database from {}",
        dialog_id.get(),
        message_id.get(),
        source
    );

    let mut unique_message_id = ServerMessageId::new(0);
    let mut random_id = 0i64;
    let mut search_id = 0i64;
    let mut text = String::new();
    match dialog_id.get_type() {
        DialogType::User | DialogType::Chat => {
            if message_id.is_server() {
                unique_message_id = message_id.get_server_message_id();
            }
        }
        DialogType::Channel => {}
        DialogType::SecretChat => {
            random_id = m.random_id;
            text = get_message_search_text(m);
            if !text.is_empty() {
                search_id = ((m.date as i64) << 32) | (m.random_id as u32 as i64);
            }
        }
        DialogType::None => {
            unreachable!()
        }
    }

    let mut ttl_expires_at = 0i32;
    if m.ttl_expires_at != 0.0 {
        ttl_expires_at = (m.ttl_expires_at - time.now + time.server_time) as i32 + 1;
    }
    if m.ttl_period != 0 && (ttl_expires_at == 0 || m.date + m.ttl_period < ttl_expires_at) {
        ttl_expires_at = m.date + m.ttl_period;
    }
    let d = manager
        .dialogs
        .get(&dialog_id)
        .expect("dialog must exist when adding a message to the database");
    let index_mask = get_message_index_mask(manager, reactions_ctx, content_ctx, dialog_id, m);
    let _ = d;
    let mut data = Vec::new();
    store_message_log_event(m, &MessageDbStorageBridge, time, &mut data);
    global.message_db_async().add_message(
        MessageFullId::new(dialog_id, message_id),
        unique_message_id,
        get_message_sender(m),
        random_id,
        ttl_expires_at,
        index_mask,
        search_id,
        text,
        m.notification_id,
        m.top_thread_message_id,
        data,
        tdutils::promise::PromiseCreator::lambda(|()| ()),
    );
}

