/// `MessagesManager::set_dialog_is_marked_as_unread` (MessagesManager.cpp:
/// 28738-28771) — the flag flip + the `updateChatIsMarkedAsUnread`
/// emission + the marked/unread counter walk (gated on the unread sum
/// being zero) + the dialog-filter update.
pub fn set_dialog_is_marked_as_unread(
    manager: &mut MessagesManager,
    ctx: &dyn MessageObjectContext,
    state: &mut dyn ReadStateContext,
    dialog_id: DialogId,
    is_marked_as_unread: bool,
) {
    // just in case
    if ctx.is_bot() {
        return;
    }

    let old_is_marked_as_unread = manager
        .get_dialog(dialog_id)
        .map(|d| d.is_marked_as_unread)
        .unwrap_or(false);
    assert!(
        old_is_marked_as_unread != is_marked_as_unread,
        "set_dialog_is_marked_as_unread without a change in {dialog_id:?}"
    );
    manager
        .get_dialog_mut(dialog_id)
        .unwrap()
        .is_marked_as_unread = is_marked_as_unread;
    on_dialog_updated(manager, dialog_id, "set_dialog_is_marked_as_unread");

    let (unread_sum, order, is_update_new_chat_sent) = {
        let d = manager.get_dialog(dialog_id).unwrap();
        (
            d.server_unread_count + d.local_unread_count,
            d.order,
            d.is_update_new_chat_sent,
        )
    };
    if !is_update_new_chat_sent {
        // `LOG_CHECK(d->is_update_new_chat_sent)` (MessagesManager.cpp:28749)
        // — FATAL in a debug C++ build, a silent no-op in release
        tracing::warn!(
            "Wrong {dialog_id:?} in set_dialog_is_marked_as_unread (updateNewChat not sent yet)"
        );
    }
    state.send_update(td_api::Object::updateChatIsMarkedAsUnread(
        td_api::updateChatIsMarkedAsUnread {
            chat_id: ctx
                .content_context()
                .get_chat_id_object(dialog_id, "updateChatIsMarkedAsUnread"),
            is_marked_as_unread,
        },
    ));

    if unread_sum == 0 && need_unread_counter(order) {
        let delta = if is_marked_as_unread { 1 } else { -1 };
        state.on_is_marked_as_unread_change(dialog_id, delta, "set_dialog_is_marked_as_unread");

        if state.have_dialog_filters() {
            state.update_dialog_lists(dialog_id, "set_dialog_is_marked_as_unread");
        }
    }
}

/// `MessagesManager::can_use_forum_topic_id` (MessagesManager.cpp:21870-21882).
pub fn can_use_forum_topic_id(
    manager: &MessagesManager,
    dialog_id: DialogId,
    forum_topic_id: ForumTopicId,
) -> Result<(), Status> {
    if forum_topic_id == ForumTopicId::default() {
        return Result::Ok(());
    }
    if !forum_topic_id.is_valid() {
        return Result::Err(Status::error(
            400,
            "Invalid forum topic identifier specified",
        ));
    }
    if !manager.get_dialog(dialog_id).is_some_and(|d| d.is_forum) {
        return Result::Err(Status::error(400, "Chat doesn't have topics"));
    }
    Result::Ok(())
}

/// `MessagesManager::read_all_dialog_mentions` (MessagesManager.cpp:9134-9188).
/// The `check_dialog_access` opener is inlined per the M.10.6 convention:
/// the in-memory registration here, the db-load leg and the
/// `have_input_peer` rights half the [`ReadStateContext`] seam carries.
pub fn read_all_dialog_mentions(
    global: &crate::global::Global,
    manager: &mut MessagesManager,
    ctx: &dyn MessageObjectContext,
    state: &mut dyn ReadStateContext,
    time: &crate::user_manager::TimeCtx,
    dialog_id: DialogId,
    forum_topic_id: ForumTopicId,
) -> Result<(), Status> {
    // `check_dialog_access(dialog_id, true, AccessRights::Read,
    // "read_all_dialog_mentions")` (DialogManager.cpp:1350-1375)
    if manager.get_dialog(dialog_id).is_none() {
        // the `get_dialog_force` db load leg is the dialog-db receive seam
        if !dialog_id.is_valid() {
            return Result::Err(Status::error(400, "Invalid chat identifier specified"));
        }
        return Result::Err(Status::error(400, "Chat not found"));
    }
    if !state.have_input_peer(dialog_id, true) {
        // the Read-rights failure arm of `check_dialog_access_in_memory`
        return Result::Err(Status::error(400, "Can't access the chat"));
    }
    can_use_forum_topic_id(manager, dialog_id, forum_topic_id)?;

    if forum_topic_id.is_valid() {
        // `ForumTopicManager::on_topic_mention_count_changed(dialog_id,
        // forum_topic_id, 0, false)` + `MessageQueryManager::
        // read_all_topic_mentions_on_server` — [blocked: net], the
        // MessageQueryManager owner
        tracing::info!(
            "read_all_topic_mentions_on_server seam: dialog {dialog_id:?} topic {}",
            forum_topic_id.get()
        );
        return Result::Ok(());
    }

    let unread_mention_count = manager
        .get_dialog(dialog_id)
        .map(|d| d.unread_mention_count)
        .unwrap_or(0);
    // (the dropped `LOG(INFO)` reported the count above)

    if dialog_id.get_type() == DialogType::SecretChat {
        assert!(
            unread_mention_count == 0,
            "a secret chat cannot have unread mentions"
        );
        return Result::Ok(());
    }

    let (last_new_message_id, last_read_all_mentions_message_id) = {
        let d = manager.get_dialog(dialog_id).unwrap();
        (d.last_new_message_id, d.last_read_all_mentions_message_id)
    };
    if last_new_message_id > last_read_all_mentions_message_id {
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        d.last_read_all_mentions_message_id = d.last_new_message_id;
        on_dialog_updated(manager, dialog_id, "read_all_dialog_mentions");
    }

    let message_ids = {
        let d = manager.get_dialog(dialog_id).unwrap();
        find_dialog_messages(d, |m| m.contains_unread_mention)
    };
    let mut is_update_sent = false;
    for message_id in message_ids {
        {
            let m = manager
                .get_dialog(dialog_id)
                .and_then(|d| d.messages.get(&message_id))
                .unwrap_or_else(|| {
                    panic!(
                        "get_message CHECK failed for {} in read_all_dialog_mentions",
                        DisplayMessageId(message_id)
                    )
                });
            assert!(m.contains_unread_mention);
            assert_eq!(m.message_id, message_id);
            assert!(m.message_id.is_valid());
        }
        // hold the message node for the iteration — the C++ `Message *m`
        // walks all four calls; the map round-trip is the port's ownership
        // shape
        let mut m = manager
            .get_dialog_mut(dialog_id)
            .and_then(|d| d.messages.remove(&message_id))
            .expect("message vanished mid-iteration");
        // must be called before contains_unread_mention is updated
        remove_message_notification_id(
            manager,
            state,
            dialog_id,
            &mut m,
            true,
            false,
            false,
            "read_all_dialog_mentions",
        );
        m.contains_unread_mention = false;
        send_update_message_mention_read(manager, ctx, state, dialog_id, &m, 0);
        is_update_sent = true;
        on_message_changed(
            global,
            manager,
            ctx,
            time,
            dialog_id,
            &m,
            true,
            "read_all_dialog_mentions",
        );
        let prev = manager
            .get_dialog_mut(dialog_id)
            .unwrap()
            .messages
            .insert(message_id, m);
        assert!(prev.is_none(), "message reappeared mid-iteration");
    }

    let unread_mention_count = manager
        .get_dialog(dialog_id)
        .map(|d| d.unread_mention_count)
        .unwrap_or(0);
    if unread_mention_count != 0 {
        set_dialog_unread_mention_count(manager, dialog_id, 0);
        if !is_update_sent {
            send_update_chat_unread_mention_count(manager, ctx, state, dialog_id);
        } else {
            // (the dropped `LOG(INFO)` reported the count above)
            on_dialog_updated(manager, dialog_id, "read_all_dialog_mentions");
        }
    }
    remove_message_dialog_notifications(
        manager,
        ctx,
        state,
        dialog_id,
        MessageId::max(),
        true,
        "read_all_dialog_mentions",
    );

    // `MessageQueryManager::read_all_dialog_mentions_on_server(dialog_id, 0,
    // promise)` — [blocked: net]
    tracing::info!("read_all_dialog_mentions_on_server seam: dialog {dialog_id:?}");
    Result::Ok(())
}

/// `MessagesManager::is_from_mention_notification_group`
/// (MessagesManager.cpp:26013-26017).
fn is_from_mention_notification_group(m: &Message) -> bool {
    m.contains_mention && !m.is_mention_notification_disabled
}

/// `MessagesManager::is_message_notification_active` (MessagesManager.cpp:
/// 26018-26038).
pub fn is_message_notification_active(d: &Dialog, m: &Message) -> bool {
    assert!(!m.message_id.is_scheduled());
    let Some(notification_info) = d.notification_info.as_ref() else {
        if is_from_mention_notification_group(m) {
            return m.contains_unread_mention;
        }
        return m.message_id > d.last_read_inbox_message_id;
    };
    if is_from_mention_notification_group(m) {
        !notification_info
            .mention_notification_group
            .is_removed_notification(
                m.notification_id,
                NotificationObjectId::from_message_id(m.message_id),
            )
            && (m.contains_unread_mention
                || m.message_id == notification_info.pinned_message_notification_message_id)
    } else {
        !notification_info
            .message_notification_group
            .is_removed_notification(
                m.notification_id,
                NotificationObjectId::from_message_id(m.message_id),
            )
            && m.message_id > d.last_read_inbox_message_id
    }
}

/// `MessagesManager::remove_message_notification_id` (MessagesManager.cpp:
/// 13353-13401) — the dialog-local correspondence move; the group-id
/// materialization (`add_dialog_notification_info`), the
/// `fix_dialog_last_notification_id` re-walk (ordered container) and the
/// `remove_notification` send ride the M.13 notification plane /
/// M.10.9 container slice. Until the M.13 plane lands,
/// `m.notification_id` is never valid and the function early-returns like
/// the C++ does for notification-less messages.
#[allow(clippy::too_many_arguments)] // the C++ signature
fn remove_message_notification_id(
    manager: &mut MessagesManager,
    state: &mut dyn ReadStateContext,
    dialog_id: DialogId,
    m: &mut Message,
    is_permanent: bool,
    force_update: bool,
    ignore_pinned_message_notification_removal: bool,
    _source: &str,
) {
    assert!(m.message_id.is_valid());
    let notification_id = m.notification_id;
    if !notification_id.is_valid() {
        return;
    }

    let from_mentions = is_from_mention_notification_group(m);
    let Some(d) = manager.get_dialog_mut(dialog_id) else {
        return;
    };
    // hoisted above the group borrow (a pure read of the same state — the
    // C++ computes it after the group-valid check, with no observable
    // difference)
    let had_active_notification = is_message_notification_active(d, m);
    // `get_notification_group_info(d, m)` — the `add_dialog_notification_info`
    // creation leg is the M.13/notification slice; an unmaterialized
    // notification_info answers like the C++ invalid-group arm
    let Some(notification_info) = d.notification_info.as_mut() else {
        tracing::info!(
            "remove_message_notification_id seam: dialog {dialog_id:?} has no notification_info to materialize"
        );
        return;
    };
    let group_info = if from_mentions {
        &mut notification_info.mention_notification_group
    } else {
        &mut notification_info.message_notification_group
    };
    if !group_info.is_valid() {
        return;
    }

    let group_id = group_info.get_group_id();
    // `delete_notification_id_to_message_id_correspondence`
    // (MessagesManager.cpp:13322-13334) — the erase happens only while the
    // mapping still points at this message; a stale entry is kept and logged
    let mapped_message_id = notification_info
        .notification_id_to_message_id
        .get(&notification_id)
        .copied();
    if mapped_message_id == Some(m.message_id) {
        notification_info
            .notification_id_to_message_id
            .remove(&notification_id);
    } else {
        log_error!(
            "Can't find {:?} from {}",
            notification_id,
            DisplayMessageId(m.message_id)
        );
    }
    m.removed_notification_id = m.notification_id;
    m.notification_id = NotificationId::default();
    let pinned_matches = notification_info.pinned_message_notification_message_id == m.message_id;
    if pinned_matches && is_permanent && !ignore_pinned_message_notification_removal {
        // must be called after notification_id is removed
        state
            .remove_dialog_pinned_message_notification(dialog_id, "remove_message_notification_id");
    }
    if group_info.get_last_notification_id() == notification_id {
        // last notification is deleted, need to find new last notification —
        // `fix_dialog_last_notification_id` walks the ordered container
        // ([blocked: M.10.9]) and repairs the group state ([blocked: M.13])
        tracing::info!(
            "fix_dialog_last_notification_id seam: group {group_id:?} in {dialog_id:?} after removing {notification_id:?}"
        );
    }

    if is_permanent {
        if had_active_notification {
            state.remove_notification(group_id, notification_id, is_permanent, force_update);
        }
        // on_message_changed will be called by the caller
        // don't need to call there to not save twice/or to save just deleted message
    } else {
        // the C++ non-permanent arm is `on_message_changed(d, m, false,
        // source)` (MessagesManager.cpp:13399); its callers
        // (do_remove_message_notification, MessagesManager.cpp:26478/26544)
        // are the M.13 notification slice — the persistence tail rides
        // on_message_changed there ([blocked: M.13])
    }
}

/// `MessagesManager::get_dialog_pending_notification_count`
/// (MessagesManager.cpp:26574-26594).
fn get_dialog_pending_notification_count(
    ctx: &dyn MessageObjectContext,
    manager: &MessagesManager,
    state: &dyn ReadStateContext,
    dialog_id: DialogId,
    from_mentions: bool,
) -> i32 {
    assert!(
        !ctx.is_bot(),
        "get_dialog_pending_notification_count for a bot"
    );
    let d = manager.get_dialog(dialog_id).unwrap_or_else(|| {
        panic!("get_dialog_pending_notification_count without the dialog {dialog_id:?}")
    });
    let notification_info = d.notification_info.as_ref().unwrap_or_else(|| {
        panic!("get_dialog_pending_notification_count without notification_info")
    });
    if from_mentions {
        let has_pinned_message = notification_info
            .pinned_message_notification_message_id
            .is_valid()
            && notification_info.pinned_message_notification_message_id <= d.last_new_message_id;
        d.unread_mention_count + i32::from(has_pinned_message)
    } else if notification_info.new_secret_chat_notification_id.is_valid() {
        1
    } else if state.is_dialog_muted(dialog_id) {
        // usually 0
        i32::try_from(notification_info.pending_new_message_notifications.len()).unwrap_or(i32::MAX)
    } else {
        d.server_unread_count + d.local_unread_count
    }
}

/// `MessagesManager::remove_message_dialog_notifications`
/// (MessagesManager.cpp:26937-26988) — the pending-new-message zeroing and
/// the `set_dialog_last_notification` halves are local: the gate and the
/// zeroing always use the message pending list regardless of
/// `from_mentions` (MessagesManager.cpp:26952-26962), `from_mentions` only
/// selects the flushed list inside the flush; the flush and the group
/// removal sends ride the [`ReadStateContext`] seams.
fn remove_message_dialog_notifications(
    manager: &mut MessagesManager,
    ctx: &dyn MessageObjectContext,
    state: &mut dyn ReadStateContext,
    dialog_id: DialogId,
    max_message_id: MessageId,
    from_mentions: bool,
    source: &str,
) {
    // removes up to max_message_id
    assert!(
        !ctx.is_bot(),
        "remove_message_dialog_notifications for a bot"
    );
    assert!(!max_message_id.is_scheduled());

    let last_message_id = manager
        .get_dialog(dialog_id)
        .map(|d| d.last_message_id)
        .unwrap_or_default();

    let (group_id, mut max_notification_message_id, needs_next_local_id) = {
        let Some(d) = manager.get_dialog_mut(dialog_id) else {
            return;
        };
        let Some(notification_info) = d.notification_info.as_mut() else {
            return;
        };
        let NotificationInfo {
            message_notification_group,
            mention_notification_group,
            pending_new_message_notifications,
            ..
        } = notification_info;
        let group_info = if from_mentions {
            mention_notification_group
        } else {
            message_notification_group
        };
        if !group_info.is_valid() {
            return;
        }
        let group_id = group_info.get_group_id();

        // the message pending list gate + zeroing run for both planes
        // (MessagesManager.cpp:26952-26962)
        if !pending_new_message_notifications.is_empty() {
            for it in pending_new_message_notifications.iter_mut() {
                if it.1 <= max_message_id {
                    it.0 = DialogId::default();
                }
            }
            state.flush_pending_new_message_notifications(
                dialog_id,
                from_mentions,
                DialogId::from_user_id(UserId::new(3)),
            );
        }

        let mut max_notification_message_id = max_message_id;
        let needs_next_local_id;
        if last_message_id.is_valid() && max_notification_message_id >= last_message_id {
            max_notification_message_id = last_message_id;
            group_info.set_last_notification(0, NotificationId::default()); // "remove_message_dialog_notifications 1"
            needs_next_local_id = false;
        } else if max_notification_message_id == MessageId::max() {
            group_info.set_last_notification(0, NotificationId::default()); // "remove_message_dialog_notifications 2"
            needs_next_local_id = true;
        } else {
            panic!(
                "TODO support notification deletion up to {} if it would be ever needed from {}",
                DisplayMessageId(max_message_id),
                source
            );
        }
        (group_id, max_notification_message_id, needs_next_local_id)
    };

    if needs_next_local_id {
        // the `get_next_local_message_id(d)` allocation of the max() arm
        // (MessagesManager.cpp:26971) — it fires only on this arm like the
        // C++; the arm's `set_dialog_last_notification` half runs above it
        // here, and the two touches are independent in the C++ too
        max_notification_message_id = manager
            .get_dialog_mut(dialog_id)
            .map(|d| get_next_local_message_id(d, ctx.is_bot()))
            .unwrap_or_default();
    }

    state.remove_notification_group(group_id, max_notification_message_id, 0, true, source);
}

/// `MessagesManager::get_next_message_id` (MessagesManager.cpp:28247-28277)
/// — the allocator walk; the `get_message_force` probes collapse to the
/// `Dialog::messages` map (the db-load leg is the dialog-db receive seam).
fn get_next_message_id(d: &mut Dialog, is_bot: bool, message_type: MessageType) -> MessageId {
    let last_message_id = if is_bot {
        d.last_assigned_message_id.max(d.max_unavailable_message_id)
    } else {
        let candidate = [
            d.last_message_id,
            d.last_new_message_id,
            d.last_database_message_id,
            d.last_assigned_message_id,
            d.last_clear_history_message_id,
            d.deleted_last_message_id,
            d.max_unavailable_message_id,
            d.max_added_message_id,
        ]
        .into_iter()
        .max()
        .unwrap();
        let mut candidate = candidate;
        if candidate < d.last_read_inbox_message_id
            && d.last_read_inbox_message_id < d.last_new_message_id.get_next_server_message_id()
        {
            candidate = d.last_read_inbox_message_id;
        }
        if candidate < d.last_read_outbox_message_id
            && d.last_read_outbox_message_id < d.last_new_message_id.get_next_server_message_id()
        {
            candidate = d.last_read_outbox_message_id;
        }
        candidate
    };

    d.last_assigned_message_id = last_message_id.get_next_message_id(message_type);
    assert!(
        d.last_assigned_message_id <= MessageId::max(),
        "Force restart because of message_id overflow"
    );
    assert!(d.last_assigned_message_id.is_valid());
    if d.last_assigned_message_id.get_prev_server_message_id()
        != last_message_id.get_prev_server_message_id()
    {
        d.had_yet_unsent_message_id_overflow = true;
    }
    d.last_assigned_message_id
}

/// `MessagesManager::get_next_local_message_id` (MessagesManager.cpp:28281-28287).
fn get_next_local_message_id(d: &mut Dialog, is_bot: bool) -> MessageId {
    let mut message_id = get_next_message_id(d, is_bot, MessageType::Local);
    while d.messages.contains_key(&message_id) {
        message_id = message_id.get_next_message_id(MessageType::Local);
    }
    message_id
}

/// `MessagesManager::set_dialog_unread_mention_count` (MessagesManager.cpp:
/// 12288-12294) — the CHECK parity: unequal to the old value and >= 0.
fn set_dialog_unread_mention_count(
    manager: &mut MessagesManager,
    dialog_id: DialogId,
    unread_mention_count: i32,
) {
    let d = manager.get_dialog_mut(dialog_id).unwrap_or_else(|| {
        panic!("set_dialog_unread_mention_count without the dialog {dialog_id:?}")
    });
    assert!(d.unread_mention_count != unread_mention_count);
    assert!(unread_mention_count >= 0);

    d.unread_mention_count = unread_mention_count;
    d.message_count_by_index
        [message_search_filter_index(MessageSearchFilter::UnreadMention) as usize] =
        unread_mention_count;
}

// ---------------------------------------------------------------------------
// M.10.8 — the outgoing send skeleton (MessagesManager.cpp:20892-21351,
// 28289-28307, 31092-31700, 35822-35941, 35951-35991): the client-side id
// allocation, `create_message_to_send`/`get_message_to_send`, the reply
// plumbing (`create_message_input_reply_to`, `get_message_input_reply_to`),
// and the durable send plane (`SendMessageLogEvent` + the
// `HandlerType::SendMessage` crash-recovery replay arm through
// `continue_send_message`).
//
// Seams (each pinned at its use):
// - the td_api entry ladder (`send_message` 21721: can_send_message,
//   `MessageSendOptions::get_message_send_options`,
//   `process_input_message_content`, the error-string parity) is M.10.10 —
//   this slice takes the pre-validated `MessageContent` form.
// - the wire query (`do_send_message` → messages.sendMessage, the
//   upload/secret-media scheduling) and `on_message_sent`/
//   `updateMessageID`/the `yet_unsent_message_full_id_to_persistent_message_id`
//   writes are M.10.9's net flip; `do_send_message` trace-logs here.
// - `add_message_to_dialog`'s ordering/pos/notification fan-out stays the
//   M.10.3/M.10.9 container seam (`need_update_dialog_pos` is carried as an
//   out-param); the ported spine covers the send/replay configuration
//   (`from_database = false, from_update = true, need_update = false` — the
//   C++ calls at 21112/35915 pass `from_update = true`) exactly, including
//   the yet-unsent random-id correspondence and the live from_update legs
//   that write dialog state (last_new LOG, the set_dialog_last_message_id
//   field, the channel slow-mode next-send date, has_outgoing_messages).
// - the cross-chat reply's forwarded-content embedding
//   (`get_forwarded_message_info` 21316 + `create_automatic_quote`) is the
//   M.10.11 forward path; the seam's None answer routes to the C++'s own
//   reset-to-default branch (RepliedMessageInfo.cpp:152-156).
// - the Dependencies resolve + get_dialog_force db-load legs of the replay
//   ride the dialog-db receive seam, like M.10.6's replay arm.
// - `fail_send_message`/`send_update_new_message`/
//   `send_update_chat_has_scheduled_messages` emissions are the M.10.9/M.13
//   update plane; the decisions are computed, the sends trace-log.
// - `get_topic_id`'s `is_valid_in` chat check rides the SavedMessagesManager
//   slice; the raw conversion is exact.
//
// 'PendingMessageOperation' is the plan doc's name for this plane; the C++
// truth is `SendMessageLogEvent`/`being_sent_messages_`/
// `send_message_log_event_id` (zero C++ hits for the plan name).
//
// Framing note for the D1 cross-read: the C++ `log_event_store` writes a
// version word in front of EVERY binlog event body
// (logevent/LogEvent.h:167-186). The M.10.8 `SendMessageLogEvent` pins that
// framing exactly (`store_log_event_version` + `Parser::new_log_event`);
// the landed M.10.6 `DeleteMessageLogEvent` omits the word (its store/parse
// use the bare `Parser`) — pre-existing, recorded here, to be reconciled at
// the D1 fixture cross-read, not silently changed.
// ---------------------------------------------------------------------------

/// `td::MessageSendOptions` (MessageSendOptions.h:21-35) — the send
/// parameters behind `messageSendOptions`. The td_api parser
/// (`get_message_send_options`) and the `can_use_for` content gates are the
/// M.10.10 entry ladder; the engine takes the parsed form.
#[derive(Clone, Debug, Default)]
pub struct MessageSendOptions {
    pub disable_notification: bool,
    pub from_background: bool,
    pub update_stickersets_order: bool,
    pub protect_content: bool,
    pub allow_paid: bool,
    pub only_preview: bool,
    pub schedule_date: i32,
    pub schedule_repeat_period: i32,
    pub sending_id: i32,
    pub effect_id: MessageEffectId,
    pub paid_message_star_count: i64,
    pub suggested_post: Option<SuggestedPost>,
}

/// `SCHEDULE_WHEN_ONLINE_DATE` (MessageSendOptions.cpp) — hoisted for the
/// options builders (the object twin lives with
/// [`get_message_scheduling_state_object`]).
const MESSAGE_SEND_SCHEDULE_WHEN_ONLINE_DATE: i32 = 2147483646;

impl MessageSendOptions {
    /// `MessageSendOptions::get_message_schedule_date`
    /// (MessageSendOptions.cpp:44-79).
    pub fn get_message_schedule_date(
        unix_time: i32,
        is_test_dc: bool,
        scheduling_state: Option<td_api::MessageSchedulingState>,
        allow_repeat_period: bool,
    ) -> Result<(i32, i32), (i32, String)> {
        let Some(scheduling_state) = scheduling_state else {
            return Ok((0, 0));
        };

        match scheduling_state {
            td_api::MessageSchedulingState::messageSchedulingStateSendWhenVideoProcessed(_) => {
                Err((400, "Can't force video processing".to_owned()))
            }
            td_api::MessageSchedulingState::messageSchedulingStateSendWhenOnline(_) => {
                Ok((MESSAGE_SEND_SCHEDULE_WHEN_ONLINE_DATE, 0))
            }
            td_api::MessageSchedulingState::messageSchedulingStateSendAtDate(state) => {
                let send_date = state.send_date;
                if send_date <= 0 {
                    return Err((400, "Invalid send date specified".to_owned()));
                }
                if send_date <= unix_time + 10 {
                    return Ok((0, 0));
                }
                if send_date - unix_time > 367 * 86400 {
                    return Err((400, "Send date is too far in the future".to_owned()));
                }
                let repeat_period = state.repeat_period;
                if !allow_repeat_period && repeat_period != 0 {
                    return Err((
                        400,
                        "Repeated scheduled messages aren't supported".to_owned(),
                    ));
                }
                if repeat_period != 0
                    && repeat_period != 86400
                    && repeat_period != 7 * 86400
                    && repeat_period != 14 * 86400
                    && repeat_period != 30 * 86400
                    && repeat_period != 91 * 86400
                    && repeat_period != 182 * 86400
                    && repeat_period != 365 * 86400
                    && (!is_test_dc || (repeat_period != 60 && repeat_period != 300))
                {
                    return Err((400, "Invalid message repeat period specified".to_owned()));
                }
                Ok((send_date, repeat_period))
            }
        }
    }

    /// `MessageSendOptions::check_paid_message_star_count`
    /// (MessageSendOptions.cpp:102-116).
    pub fn check_paid_message_star_count(
        ctx: &dyn SendMessageContext,
        paid_message_star_count: &mut i64,
        message_count: i32,
    ) -> Result<(), (i32, String)> {
        if *paid_message_star_count < 0 || *paid_message_star_count > 1000000 {
            return Err((400, "Invalid price for paid message specified".to_owned()));
        }
        assert!(message_count > 0);
        if *paid_message_star_count % i64::from(message_count) != 0 {
            return Err((400, "Invalid price for paid messages specified".to_owned()));
        }
        if *paid_message_star_count > 0 && !ctx.has_owned_star_count(*paid_message_star_count) {
            return Err((400, "Have not enough Telegram Stars".to_owned()));
        }
        *paid_message_star_count /= i64::from(message_count);
        Ok(())
    }

    /// `MessageSendOptions::get_message_send_options`
    /// (MessageSendOptions.cpp:118-184).
    #[allow(clippy::too_many_arguments)]
    pub fn get_message_send_options(
        ctx: &dyn SendMessageContext,
        dialog_id: DialogId,
        options: Option<td_api::MessageSendOptions>,
        allow_update_stickersets_order: bool,
        allow_effect: bool,
        allow_suggested_post: bool,
        allow_repeat_period: bool,
        message_count: i32,
    ) -> Result<MessageSendOptions, (i32, String)> {
        let mut result = MessageSendOptions::default();
        let Some(options) = options else {
            return Ok(result);
        };

        result.disable_notification = options.disable_notification;
        result.from_background = options.from_background;
        if allow_update_stickersets_order {
            result.update_stickersets_order = options.update_order_of_installed_sticker_sets;
        }
        if ctx.is_bot() {
            result.protect_content = options.protect_content;
            result.allow_paid = options.allow_paid_broadcast;
        } else {
            result.paid_message_star_count = options.paid_message_star_count;
            Self::check_paid_message_star_count(
                ctx,
                &mut result.paid_message_star_count,
                message_count,
            )?;
        }
        result.only_preview = options.only_preview;
        let (schedule_date, schedule_repeat_period) = Self::get_message_schedule_date(
            ctx.unix_time(),
            ctx.is_test_dc(),
            options.scheduling_state,
            allow_repeat_period,
        )?;
        result.schedule_date = schedule_date;
        result.schedule_repeat_period = schedule_repeat_period;
        result.sending_id = options.sending_id;

        if result.schedule_date != 0 {
            let dialog_type = dialog_id.get_type();
            if dialog_type == DialogType::SecretChat {
                return Err((400, "Can't schedule messages in secret chats".to_owned()));
            }
            if ctx.is_bot() {
                return Err((400, "Bots can't send scheduled messages".to_owned()));
            }

            if result.schedule_date == MESSAGE_SEND_SCHEDULE_WHEN_ONLINE_DATE {
                if dialog_type != DialogType::User {
                    return Err((
                        400,
                        "Messages can be scheduled till online only in private chats".to_owned(),
                    ));
                }
                if dialog_id == ctx.content_context().get_my_dialog_id() {
                    return Err((
                        400,
                        "Can't scheduled till online messages in chat with self".to_owned(),
                    ));
                }
            }
            if result.paid_message_star_count > 0 {
                return Err((400, "Can't schedule paid messages".to_owned()));
            }
            if ctx.is_admined_monoforum_channel(dialog_id) {
                return Err((
                    400,
                    "Can't schedule messages in channel direct messages chats".to_owned(),
                ));
            }
        }
        if options.effect_id != 0 {
            let dialog_type = dialog_id.get_type();
            if dialog_type != DialogType::User {
                return Err((400, "Can't use message effects in the chat".to_owned()));
            }
            if !allow_effect {
                return Err((400, "Can't use message effects in the method".to_owned()));
            }
            result.effect_id = MessageEffectId::new(options.effect_id);
        }
        let suggested_post = Self::get_suggested_post_info(options.suggested_post_info)?;
        if let Some(suggested_post) = suggested_post {
            if !allow_suggested_post {
                return Err((400, "Can't send suggested posts with the method".to_owned()));
            }
            if !ctx
                .content_context()
                .is_monoforum_channel(dialog_id.get_channel_id())
            {
                return Err((
                    400,
                    "Suggested posts can be sent only to channel direct messages".to_owned(),
                ));
            }
            result.suggested_post = Some(suggested_post);
        }

        Ok(result)
    }

    /// `SuggestedPost::get_suggested_post(const Td *, td_api::...)`
    /// (SuggestedPost.cpp:29-40).
    fn get_suggested_post_info(
        post: Option<td_api::InputSuggestedPostInfo>,
    ) -> Result<Option<SuggestedPost>, (i32, String)> {
        let Some(post) = post else {
            return Ok(None);
        };
        let price = match post.price {
            Some(td_api::SuggestedPostPrice::suggestedPostPriceStar(price)) => {
                if price.star_count == 0 {
                    SuggestedPostPrice::default()
                } else {
                    SuggestedPostPrice {
                        r#type: crate::message_content::SuggestedPostPriceType::Star,
                        amount: price.star_count,
                    }
                }
            }
            Some(_) => {
                // the Gram/TON price arms ride the Wave-2 payment plane
                SuggestedPostPrice::default()
            }
            None => SuggestedPostPrice::default(),
        };
        let send_date = post.send_date;
        if send_date < 0 {
            return Err((400, "Invalid post send date specified".to_owned()));
        }
        Ok(Some(SuggestedPost {
            price,
            schedule_date: send_date,
            is_accepted: false,
            is_rejected: false,
        }))
    }

    /// `MessageSendOptions::can_use_for(const unique_ptr<MessageContent> &,
    /// MessageSelfDestructType)` (MessageSendOptions.cpp:186-196).
    pub fn can_use_for(
        &self,
        content: &crate::message_content::MessageContent,
        ttl: &MessageSelfDestructType,
    ) -> Result<(), (i32, String)> {
        if self.schedule_date != 0 {
            if ttl.is_valid() {
                return Err((
                    400,
                    "Can't send scheduled self-destructing messages".to_owned(),
                ));
            }
            if content.get_type() == crate::message_content::MessageContentType::LiveLocation {
                return Err((
                    400,
                    "Can't send scheduled live location messages".to_owned(),
                ));
            }
        }
        Ok(())
    }

    /// `MessageSendOptions::can_use_for(const InputMessageContent &)`
    /// (MessageSendOptions.cpp:198-201).
    pub fn can_use_for_input(
        &self,
        content: &crate::message_content::InputMessageContent,
    ) -> Result<(), (i32, String)> {
        self.can_use_for(&content.content, &content.ttl)
    }
}

