/// `MessagesManager::get_next_yet_unsent_message_id`
/// (MessagesManager.cpp:28277-28279).
fn get_next_yet_unsent_message_id(d: &mut Dialog, is_bot: bool) -> MessageId {
    get_next_message_id(d, is_bot, MessageType::YetUnsent)
}

/// `MessagesManager::get_next_yet_unsent_scheduled_message_id`
/// (MessagesManager.cpp:28289-28307) — the per-date ladder over the
/// scheduled container and the last-assigned marker.
fn get_next_yet_unsent_scheduled_message_id(d: &mut Dialog, date: i32) -> MessageId {
    assert!(date > 0);

    // `add_dialog_scheduled_messages` (MessagesManager.cpp:29877-29882)
    if d.scheduled_messages.is_none() {
        d.scheduled_messages = Some(DialogScheduledMessages::default());
    }
    let scheduled_messages = d.scheduled_messages.as_mut().unwrap();
    let mut message_id = MessageId::from_scheduled(ScheduledServerMessageId::new(1), date, false);
    for it in scheduled_messages.scheduled_messages.keys() {
        if it.get_scheduled_message_date() == date && *it > message_id {
            message_id = *it;
        }
    }

    let last_assigned_message_id = scheduled_messages
        .last_assigned_scheduled_message_id
        .entry(date)
        .or_default();
    if *last_assigned_message_id != MessageId::default() && *last_assigned_message_id > message_id {
        message_id = *last_assigned_message_id;
    }

    *last_assigned_message_id = message_id.get_next_message_id(MessageType::YetUnsent);
    *last_assigned_message_id
}

/// `MessagesManager::generate_new_random_id` (MessagesManager.cpp:20898-20905)
/// — a secure random id, nonzero and fresh against both the being-sent
/// registry and the dialog's yet-unsent correspondence.
fn generate_new_random_id(d: &Dialog, being_sent_messages: &HashMap<i64, MessageFullId>) -> i64 {
    loop {
        let random_id = tdutils::random::secure_int64();
        if random_id != 0
            && !being_sent_messages.contains_key(&random_id)
            && !d.random_id_to_message_id.contains_key(&random_id)
        {
            return random_id;
        }
    }
}

/// `MessagesManager::begin_send_message` (MessagesManager.cpp:21120-21127) —
/// the random-id registration that makes the in-flight message crash-visible.
pub fn begin_send_message(manager: &mut MessagesManager, dialog_id: DialogId, m: &Message) -> i64 {
    tracing::info!(
        "Begin to send {}:{} with random_id = {}",
        dialog_id.get(),
        DisplayMessageId(m.message_id),
        m.random_id
    );
    assert!(m.random_id != 0);
    assert!(m.message_id.is_yet_unsent());
    let is_inserted = manager
        .being_sent_messages
        .insert(m.random_id, MessageFullId::new(dialog_id, m.message_id))
        .is_none();
    assert!(is_inserted);
    m.random_id
}

/// `MessagesManager::get_persistent_message_id`
/// (MessagesManager.cpp:21133-21147) — the yet-unsent → server-id rewrite
/// read; the registry writes are M.10.9, so an empty registry falls through
/// exactly like the C++ miss.
pub fn get_persistent_message_id(
    manager: &MessagesManager,
    d: &Dialog,
    message_id: MessageId,
) -> MessageId {
    if !message_id.is_valid() && !message_id.is_valid_scheduled() {
        return MessageId::default();
    }
    if message_id.is_yet_unsent() {
        // it is possible that user tries to do something with an already sent
        // message by its temporary identifier; use the real message then
        if let Some(persistent) = manager
            .yet_unsent_message_full_id_to_persistent_message_id
            .get(&MessageFullId::new(d.dialog_id, message_id))
        {
            return *persistent;
        }
    }
    message_id
}

/// `MessagesManager::add_random_id_to_message_id_correspondence`
/// (MessagesManager.cpp:13284-13293).
fn add_random_id_to_message_id_correspondence(
    d: &mut Dialog,
    random_id: i64,
    message_id: MessageId,
) {
    if random_id == 0 {
        return;
    }
    let replace = match d.random_id_to_message_id.get(&random_id) {
        Some(old) => old.get() < message_id.get(),
        None => true,
    };
    if replace {
        d.random_id_to_message_id.insert(random_id, message_id);
    }
}

/// `MessagesManager::delete_random_id_to_message_id_correspondence`
/// (MessagesManager.cpp:13295-13302) — the call sites are the
/// send-completion/delete walks (MessagesManager.cpp:27992/13857/13781); the
/// M.10.9 `on_message_sent` flip owns the first.
#[allow(dead_code)]
fn delete_random_id_to_message_id_correspondence(
    d: &mut Dialog,
    random_id: i64,
    message_id: MessageId,
) {
    if let Some(old) = d.random_id_to_message_id.get(&random_id)
        && *old == message_id
    {
        d.random_id_to_message_id.remove(&random_id);
    }
}

/// `MessagesManager::get_message_id_by_random_id`
/// (MessagesManager.cpp:32917-32959) — the memory-map read; the secret-chat
/// message-db leg is the [`SendMessageContext::get_message_by_random_id_from_database`]
/// seam. The C++ takes `Dialog *` because that leg would populate the
/// correspondence from the database; with the leg seamed the read is
/// shared-borrow (the signature widens back when the db wiring lands).
pub fn get_message_id_by_random_id(
    ctx: &dyn SendMessageContext,
    d: &Dialog,
    random_id: i64,
    source: &str,
) -> MessageId {
    if random_id == 0 {
        return MessageId::default();
    }
    if let Some(message_id) = d.random_id_to_message_id.get(&random_id) {
        tracing::info!(
            "Found {}:{} by random_id {} from {}",
            d.dialog_id.get(),
            DisplayMessageId(*message_id),
            random_id,
            source
        );
        return *message_id;
    }
    if d.dialog_id.get_type() == DialogType::SecretChat
        && let Some(m) = ctx.get_message_by_random_id_from_database(d.dialog_id, random_id)
    {
        assert!(
            m.random_id == random_id,
            "get_message_id_by_random_id random-id mismatch in {:?}",
            d.dialog_id
        );
        assert!(
            d.random_id_to_message_id.contains_key(&random_id),
            "get_message_id_by_random_id did not populate the correspondence from {}",
            source
        );
        let message_id = d.random_id_to_message_id[&random_id];
        assert!(
            message_id == m.message_id,
            "get_message_id_by_random_id correspondence mismatch from {}",
            source
        );
        tracing::info!(
            "Found {}:{} by random_id {} from {}",
            d.dialog_id.get(),
            DisplayMessageId(message_id),
            random_id,
            source
        );
        return message_id;
    }
    tracing::info!(
        "Found no message by random_id {} from {}",
        random_id,
        source
    );
    MessageId::default()
}

/// `MessagesManager::is_deleted_message` (MessagesManager.cpp:13791-13798).
fn is_deleted_message(d: &Dialog, message_id: MessageId) -> bool {
    if message_id.is_scheduled()
        && message_id.is_valid_scheduled()
        && message_id.is_scheduled_server()
    {
        d.scheduled_messages.as_ref().is_some_and(|scheduled| {
            scheduled
                .deleted_scheduled_server_message_ids
                .contains(&message_id.get_scheduled_server_message_id())
        })
    } else {
        d.deleted_message_ids.contains(&message_id)
    }
}

/// `MessagesManager::get_message(Dialog *, MessageId)` (MessagesManager.cpp
/// 13720-13740) — the in-memory half; the db-load leg is the dialog-db
/// receive seam.
fn get_message_in_dialog(d: &Dialog, message_id: MessageId) -> Option<&Message> {
    if message_id.is_scheduled() {
        d.scheduled_messages
            .as_ref()
            .and_then(|scheduled| scheduled.scheduled_messages.get(&message_id))
            .map(|m| m.as_ref())
    } else {
        d.messages.get(&message_id).map(|m| m.as_ref())
    }
}

/// `MessagesManager::have_message_force(Dialog *, MessageId, source)`
/// (MessagesManager.cpp:13829-13840) — the in-memory probe; the db-load leg
/// is the dialog-db receive seam.
fn have_message_force(d: &Dialog, message_id: MessageId, source: &str) -> bool {
    let have = get_message_in_dialog(d, message_id).is_some();
    if have {
        tracing::info!(
            "Have message {} in {:?} from {}",
            DisplayMessageId(message_id),
            d.dialog_id,
            source
        );
    }
    have
}

/// `MessagesManager::have_message_force(MessageFullId, source)` — the
/// dialog-lookup form over the same in-memory probe.
pub(crate) fn have_message_force_full(
    manager: &MessagesManager,
    message_full_id: MessageFullId,
    source: &str,
) -> bool {
    manager
        .get_dialog(message_full_id.get_dialog_id())
        .is_some_and(|d| have_message_force(d, message_full_id.get_message_id(), source))
}

/// `MessagesManager::register_dialog_ephemeral_message` /
/// `unregister_dialog_ephemeral_message` (MessagesManager.cpp:13806-13820).
fn register_dialog_ephemeral_message(d: &mut Dialog, ephemeral_message_id: EphemeralMessageId) {
    if ephemeral_message_id.is_valid() {
        d.ephemeral_message_ids
            .entry(ephemeral_message_id)
            .or_default();
    }
}

fn unregister_dialog_ephemeral_message(d: &mut Dialog, ephemeral_message_id: EphemeralMessageId) {
    if ephemeral_message_id.is_valid() {
        d.ephemeral_message_ids.remove(&ephemeral_message_id);
    }
}

/// `MessagesManager::add_message_to_dialog` (MessagesManager.cpp:31092-31661)
/// in the send/replay configuration (`from_database = false, from_update =
/// true, need_update = false` — MessagesManager.cpp:21112/35915 pass
/// `from_update = true`) — the gates, the live from_update legs, the
/// yet-unsent random-id correspondence and the container insert are exact;
/// the C++ lines that only fire in the receive/database configurations or
/// whose bodies belong to other managers are marked as the M.10.9 container
/// seam. `Err` carries the C++ `debug_add_message_to_dialog_fail_reason_`.
#[allow(clippy::too_many_arguments)]
pub fn add_message_to_dialog(
    global: &mut crate::global::Global,
    manager: &mut MessagesManager,
    reactions_ctx: &dyn DialogReactionsContext,
    ctx: &dyn SendMessageContext,
    state: &mut dyn ReadStateContext,
    dialog_id: DialogId,
    mut message: Box<Message>,
    from_database: bool,
    from_update: bool,
    need_update: &mut bool,
    need_update_dialog_pos: &mut bool,
    source: &'static str,
) -> Result<MessageFullId, String> {
    let message_id = message.message_id;
    if !message_id.is_valid() {
        // `add_scheduled_message_to_dialog` dispatch (MessagesManager.cpp:31096)
        return add_scheduled_message_to_dialog(
            global,
            manager,
            reactions_ctx,
            ctx,
            dialog_id,
            message,
            from_database,
            from_update,
            need_update,
            source,
        );
    }

    manager.debug_add_message_to_dialog_fail_reason = "success".to_string();

    // `fix_new_message(d, message, false)` (31104) — reads the dialog only
    if manager.get_dialog(dialog_id).is_some() {
        fix_new_message(manager, reactions_ctx, ctx, dialog_id, &mut message, false);
    }

    // the ttl decisions need the message and the clocks only
    let ttl_expired = message.ttl.is_valid()
        && message.ttl_expires_at != 0.0
        && message.ttl_expires_at <= ctx.now();
    let ttl_period_expired =
        message.ttl_period > 0 && (message.date + message.ttl_period) as f64 <= ctx.server_time();
    if ttl_period_expired {
        assert!(dialog_id.get_type() != DialogType::SecretChat);
    }
    let ephemeral_expired = message
        .ephemeral_message
        .as_ref()
        .is_some_and(|ephemeral_message| {
            (ephemeral_message.date + ephemeral_message.ttl_period) as f64 <= ctx.server_time()
        });

    // phase 1 — the dialog-scoped gates and mutations
    let registered_ephemeral_message_id;
    {
        let Some(d) = manager.get_dialog_mut(dialog_id) else {
            // `get_dialog_force` (35888) — the db-load leg is the dialog-db
            // receive seam
            return Err("no dialog".to_string());
        };

        // `*need_update` CHECK (31100-31102)
        if *need_update {
            assert!(
                from_update,
                "need_update without from_update in add_message_to_dialog"
            );
        }

        if message_id <= d.last_clear_history_message_id {
            tracing::info!(
                "Skip adding cleared {} to {}",
                DisplayMessageId(message_id),
                dialog_id.get()
            );
            if from_database {
                // delete_message_from_database (31122) — the from_database
                // leg; the caller passes the message for the column set
            }
            manager.debug_add_message_to_dialog_fail_reason = "cleared full history".to_string();
            return Err("cleared full history".to_string());
        }

        if is_deleted_message(d, message_id) {
            tracing::info!(
                "Skip adding deleted {} to {}",
                DisplayMessageId(message_id),
                dialog_id.get()
            );
            return Err("adding deleted message".to_string());
        }

        // the from_update last_new_message_id LOG(ERROR) (31136-31142)
        if from_update
            && !message.is_failed_to_send
            && message_id <= d.last_new_message_id
            && dialog_id.get_type() != DialogType::Channel
            && (message_id.is_server() || !ctx.is_bot())
        {
            log_error!(
                "New {} in {:?} from {} has identifier less than last_new_message_id = {}",
                DisplayMessageId(message_id),
                dialog_id,
                source,
                DisplayMessageId(d.last_new_message_id)
            );
        }

        // the too-new not-from-update gate (31145-31181): server/local ids
        // only, so a yet-unsent id keeps `max_message_id` empty and never
        // fires
        if !from_update && !message.is_failed_to_send && !is_ephemeral_message(&message) {
            let max_message_id = if message_id.is_server() {
                if d.being_added_message_id.is_valid() {
                    d.being_updated_last_new_message_id
                } else {
                    d.last_new_message_id
                }
            } else if message_id.is_local() {
                if d.being_added_message_id.is_valid() {
                    d.being_updated_last_database_message_id
                } else {
                    d.last_database_message_id
                }
            } else {
                MessageId::default()
            };
            if max_message_id != MessageId::default() && message_id > max_message_id {
                // the need_channel_difference leg (31163-31174) is the
                // net/channel-difference seam
                return Err("too new message not from update".to_string());
            }
        }
        if (message_id.is_server()
            || (message_id.is_local() && dialog_id.get_type() == DialogType::SecretChat))
            && message_id <= d.max_unavailable_message_id
            && !is_ephemeral_message(&message)
        {
            tracing::info!(
                "Can't add an unavailable {} to {}",
                DisplayMessageId(message_id),
                dialog_id.get()
            );
            return Err("ignore unavailable message".to_string());
        }

        let message_content_type = message
            .content
            .as_ref()
            .expect("message without content")
            .get_type();
        if message_content_type == MessageContentType::ChatDeleteHistory {
            // the delete_message + last-clear-history walk (31192-31220)
            // rides the M.10.9 delete/container plane; unreachable from the
            // send path because content validation (M.10.10) rejects service
            // contents
            unimplemented!("ChatDeleteHistory content in the send path is the M.10.9 seam");
        }

        // the need_update downgrades (31222-31224)
        if *need_update && message_id <= d.last_new_message_id && !ctx.is_bot() {
            *need_update = false;
        }

        // the need_update reply-markup block (31226-31241) — the
        // set_dialog_reply_markup flip rides the M.10.14 reply-markup
        // slice

        // the re-add branch (31246-31296): the memory probe; the
        // get_message_force db load is the dialog-db receive seam
        let existing = if from_database {
            get_message_in_dialog(d, message_id).is_some()
        } else {
            // get_message_force — the db-load leg is the seam; the memory
            // probe covers the loaded dialogs
            d.messages.contains_key(&message_id)
        };
        if existing {
            // `update_message(d, m, std::move(message), true, source)`
            // (31274) — the existing-message merge; the M.10.5 update core
            // rides the caller's ctx bundle, the add returns the existing
            // id
            manager.debug_add_message_to_dialog_fail_reason =
                "adding already existing message".to_string();
            return Err("adding already existing message".to_string());
        }

        // the notification preload block (31298-31332) — the pinned/top
        // thread preloads are the db-load seam; `may_need_message_notification`
        // + the group-id assignment are the M.13 plane

        assert!(
            !d.being_added_message_id.is_valid(),
            "recursive add_message_to_dialog in {:?} from {}",
            dialog_id,
            source
        );
        assert!(
            !d.being_deleted_message_id.is_valid(),
            "recursive delete in {:?} from {}",
            dialog_id,
            source
        );

        d.being_added_message_id = message_id;
        d.being_updated_last_new_message_id = d.last_new_message_id;
        d.being_updated_last_database_message_id = d.last_database_message_id;

        // the new-secret-chat notification removal (31345-31347) is the M.13
        // notification seam

        if message.message_id > d.max_added_message_id {
            d.max_added_message_id = message.message_id;
        }

        // the unload-schedule timeout (31353-31358) is the actor-timer seam

        if ephemeral_expired {
            let ephemeral_message_id = message
                .ephemeral_message
                .as_ref()
                .unwrap()
                .ephemeral_message_id;
            unregister_dialog_ephemeral_message(d, ephemeral_message_id);
            message.ephemeral_message = None;
        }

        registered_ephemeral_message_id = message.ephemeral_message_id;
    }

    // phase 2 — the ttl-expired legs (MessagesManager.cpp:31360-31395); they
    // delete through the message database and unwind the add
    if ttl_expired && dialog_id.get_type() == DialogType::SecretChat {
        tracing::info!(
            "Can't add {} with expired self-destruct timer to {} from {}",
            DisplayMessageId(message_id),
            dialog_id.get(),
            source
        );
        delete_message_from_database(
            global,
            manager,
            dialog_id,
            message_id,
            Some(&message),
            true,
            "delete self-destructed message",
        );
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        d.being_added_message_id = MessageId::default();
        return Err("delete self-destructed message".to_string());
    }
    if ttl_expired {
        // `on_message_ttl_expired_impl` (31371) — the expired-content swap is
        // the receive-plane seam (M.9/M.10.9); unreachable from the send
        // path, whose ttl_expires_at is 0 until the secret media leg sets it
        log_error!(
            "on_message_ttl_expired seam: expired non-secret {} in {:?}",
            DisplayMessageId(message_id),
            dialog_id
        );
    }
    if ttl_period_expired {
        tracing::info!(
            "Can't add auto-deleted {} sent at {} with auto-delete time {} to {} from {}",
            DisplayMessageId(message_id),
            message.date,
            message.ttl_period,
            dialog_id.get(),
            source
        );
        delete_message_from_database(
            global,
            manager,
            dialog_id,
            message_id,
            Some(&message),
            true,
            "delete auto-deleted message",
        );
        // the C++ `unregister_dialog_ephemeral_message` (31387) ran inside
        // phase 1 through the decision above
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        unregister_dialog_ephemeral_message(d, registered_ephemeral_message_id);
        d.being_added_message_id = MessageId::default();
        return Err("delete auto-deleted message".to_string());
    }
    // `ttl_register_message`/`ttl_period_register_message` (31378/31393) —
    // the ttl scheduler is the actor-timer seam

    if !message.are_media_timestamp_entities_found {
        message.are_media_timestamp_entities_found = true;
        // the from_database entity-fix leg (31404-31411) — from_database =
        // false in this configuration
    }

    // the keep_media_order yet-unsent media queue (31415-31427) is the
    // files/net send-ordering seam (M.10.18/M.10.9)

    // `update_has_outgoing_messages` (31547 -> 35786-35817) — live with
    // from_update = true; it sits after every fallible add gate, so
    // computing and flipping it here (outside the dialog borrow) is
    // order-equivalent to the C++'s pre-insert position
    let outgoing_flip_target =
        update_has_outgoing_messages_target(ctx, manager, dialog_id, &message);
    if let Some(target) = outgoing_flip_target {
        let d = manager.get_dialog_mut(target).unwrap();
        d.has_outgoing_messages = true;
    }

    // the notification blocks (31429-31454) — the add_new_message_notification
    // leg is the M.13 plane; the mention-notification removal is the
    // from_database M.13 leg

    // `add_message_to_dialog_message_list` (30948-31089) — the full
    // container/counter maintenance (the is_bot gate at 30951)
    if !ctx.is_bot() {
        let old_last_message_id;
        {
            let (drop_full_history, is_empty_flip, gap_walk) = {
                let Some(d) = manager.get_dialog_mut(dialog_id) else {
                    return Err("no dialog".to_string());
                };
                let drop_full_history = d.have_full_history
                    && !from_database
                    && !from_update
                    && !message_id.is_local()
                    && !message_id.is_yet_unsent();
                if drop_full_history {
                    log_error!(
                        "Have full history in {}, but receive unknown {} from {}. Last new is {}, last is {}",
                        dialog_id.get(),
                        DisplayMessageId(message_id),
                        source,
                        DisplayMessageId(d.last_new_message_id),
                        DisplayMessageId(d.last_message_id)
                    );
                    d.have_full_history = false;
                    d.have_full_history_source = 0;
                }
                let is_empty_flip = d.is_empty;
                if d.is_empty {
                    d.is_empty = false;
                    *need_update_dialog_pos = true;
                }
                let gap_walk = !(d.have_full_history && from_update)
                    && d.last_message_id.is_valid()
                    && d.last_message_id
                        < MessageId::from_server_message_id(ServerMessageId::new(1))
                    && message_id >= MessageId::from_server_message_id(ServerMessageId::new(1));
                (drop_full_history, is_empty_flip, gap_walk)
            };
            if drop_full_history {
                on_dialog_updated(manager, dialog_id, "drop have_full_history");
            }
            let _ = is_empty_flip;

            if gap_walk {
                set_dialog_last_message_id(
                    manager,
                    dialog_id,
                    MessageId::default(),
                    "add_message_to_dialog_message_list",
                );
                set_dialog_first_database_message_id(
                    manager,
                    dialog_id,
                    MessageId::default(),
                    "add_message_to_dialog_message_list",
                );
                set_dialog_last_database_message_id(
                    manager,
                    dialog_id,
                    MessageId::default(),
                    source,
                    false,
                );
                {
                    let d = manager.get_dialog_mut(dialog_id).unwrap();
                    d.have_full_history = false;
                    d.have_full_history_source = 0;
                    invalidate_message_indexes(d);
                    d.local_unread_count = 0; // read all local messages. They will not be reachable anymore
                }
                on_dialog_updated(manager, dialog_id, "add gap to dialog");
                *need_update_dialog_pos = false;
            }

            let advance_last_new = from_update
                && !message.is_failed_to_send
                && {
                    let d = manager.get_dialog(dialog_id).unwrap();
                    message_id > d.last_new_message_id
                }
                && !message_id.is_yet_unsent()
                && (dialog_id.get_type() == DialogType::SecretChat || message_id.is_server());
            if advance_last_new {
                // can delete messages, therefore must be called before
                // message attaching/adding
                set_dialog_last_new_message_id(
                    global,
                    manager,
                    ctx,
                    dialog_id,
                    message_id,
                    "add_message_to_dialog_message_list",
                );
            }

            old_last_message_id = manager.get_dialog(dialog_id).unwrap().last_message_id;
        }
        let is_new = message_id >= manager.get_dialog(dialog_id).unwrap().last_new_message_id;

        // the unread-inbox gates (31004-31024)
        if *need_update
            && message_id
                > manager
                    .get_dialog(dialog_id)
                    .unwrap()
                    .last_read_inbox_message_id
        {
            let has_incoming = has_incoming_notification(ctx, dialog_id, &message);
            if has_incoming {
                let (mut server_unread_count, mut local_unread_count) = {
                    let d = manager.get_dialog(dialog_id).unwrap();
                    (d.server_unread_count, d.local_unread_count)
                };
                if message_id.is_server() {
                    server_unread_count += 1;
                } else {
                    local_unread_count += 1;
                }
                set_dialog_last_read_inbox_message_id(
                    manager,
                    ctx,
                    state,
                    dialog_id,
                    MessageId::min(),
                    server_unread_count,
                    local_unread_count,
                    false,
                    source,
                );
            } else {
                // if non-scheduled outgoing message has identifier one
                // greater than last_read_inbox_message_id, then definitely
                // there are no unread incoming messages before it
                let read_next = {
                    let d = manager.get_dialog(dialog_id).unwrap();
                    message_id.is_server()
                        && d.last_read_inbox_message_id.is_valid()
                        && d.last_read_inbox_message_id.is_server()
                        && message_id
                            == d.last_read_inbox_message_id
                                .get_next_message_id(MessageType::Server)
                };
                if read_next {
                    read_history_inbox(
                        manager,
                        ctx,
                        state,
                        dialog_id,
                        message_id,
                        0,
                        "add_message_to_dialog_message_list",
                    );
                }
            }
        }
        // the mention/reaction/vote counters (31025-31040) — the
        // forum-topic count is the ForumTopicManager seam; the dialog
        // counters are live
        if *need_update && message.contains_unread_mention && !ctx.is_bot() {
            set_dialog_unread_mention_count(
                manager,
                dialog_id,
                manager.get_dialog(dialog_id).unwrap().unread_mention_count + 1,
            );
            send_update_chat_unread_mention_count(manager, ctx, state, dialog_id);
        }
        // the unread-reaction/poll-vote counts ride the same plane through
        // the ReadStateContext emission helpers (M.10.7)
        if *need_update {
            update_message_count_by_index_message(
                manager,
                reactions_ctx,
                ctx.content_context(),
                dialog_id,
                1,
                &message,
            );
        }
        // the last-message/database-window advances (31044-31061)
        {
            let (
                last_message_valid,
                last_database_message_id,
                last_new_valid,
                last_database_valid,
                last_message_id_now,
            ) = {
                let d = manager.get_dialog(dialog_id).unwrap();
                (
                    d.last_message_id.is_valid(),
                    d.last_database_message_id,
                    d.last_new_message_id.is_valid(),
                    d.last_database_message_id.is_valid(),
                    d.last_message_id,
                )
            };
            if from_update && message_id > last_message_id_now && is_new {
                let media_album_id = message.media_album_id;
                set_dialog_last_message_id(
                    manager,
                    dialog_id,
                    message_id,
                    "add_message_to_dialog_message_list",
                );
                let d = manager.get_dialog_mut(dialog_id).unwrap();
                d.last_media_album_id = media_album_id;
                *need_update_dialog_pos = true;
            }
            if from_update
                && !message_id.is_yet_unsent()
                && is_new
                && (last_new_valid
                    || (message_id.is_local()
                        && last_message_valid
                        && (message_id >= manager.get_dialog(dialog_id).unwrap().last_message_id
                            || (last_database_valid && message_id > last_database_message_id))))
            {
                assert!(message_id <= manager.get_dialog(dialog_id).unwrap().last_message_id);
                if message_id > last_database_message_id {
                    set_dialog_last_database_message_id(
                        manager,
                        dialog_id,
                        message_id,
                        "add_message_to_dialog_message_list",
                        false,
                    );
                    if !manager
                        .get_dialog(dialog_id)
                        .unwrap()
                        .first_database_message_id
                        .is_valid()
                    {
                        set_dialog_first_database_message_id(
                            manager,
                            dialog_id,
                            message_id,
                            "add_message_to_dialog_message_list",
                        );
                        // `try_restore_dialog_reply_markup` (31058) — the
                        // M.10.14 reply-markup slice
                    }
                }
            }
        }

        // the not-from-update newer-than-last walk (31063-31086)
        if !from_update
            && message_id.is_server()
            && manager
                .get_dialog(dialog_id)
                .unwrap()
                .last_message_id
                .is_valid()
            && message_id > manager.get_dialog(dialog_id).unwrap().last_message_id
        {
            tracing::info!(
                "Receive {}, which is newer than the last {} not from update",
                DisplayMessageId(message_id),
                DisplayMessageId(manager.get_dialog(dialog_id).unwrap().last_message_id)
            );
            set_dialog_last_message_id(manager, dialog_id, MessageId::default(), source);
            {
                let d = manager.get_dialog_mut(dialog_id).unwrap();
                if message_id > d.deleted_last_message_id {
                    d.delete_last_message_date = message.date;
                    d.deleted_last_message_id = message_id;
                }
            }
            set_dialog_first_database_message_id(manager, dialog_id, MessageId::default(), source);
            set_dialog_last_database_message_id(
                manager,
                dialog_id,
                MessageId::default(),
                source,
                false,
            );
            {
                let d = manager.get_dialog_mut(dialog_id).unwrap();
                d.have_full_history = false;
                d.have_full_history_source = 0;
            }
            invalidate_message_indexes(manager.get_dialog_mut(dialog_id).unwrap());
            on_dialog_updated(manager, dialog_id, source);
            *need_update_dialog_pos = false;
            on_dialog_updated(manager, dialog_id, "do delete last message");
            // `load_last_dialog_message_later` — the M.10.15 history seam
        }

        // the ordered-container insert (31088) — from_update drives the
        // auto-attach
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        d.ordered_messages
            .insert(message_id, from_update, old_last_message_id, source);
    }

    // update_replied_by_message_count (+1) (31462) — the reply registry is
    // the M.10.14 reply plane

    if !from_database && !message.message_id.is_yet_unsent() {
        let reactions_ctx2 = MessageObjectReactionsContext { ctx };
        let time = crate::user_manager::TimeCtx {
            now: ctx.now(),
            server_time: ctx.server_time(),
        };
        add_message_to_database(
            global,
            manager,
            &reactions_ctx2,
            ctx.content_context(),
            &time,
            dialog_id,
            &message,
            "add_message_to_dialog",
        );
    }

    // the Channel slow-mode/repair walk (31468-31485) — the repair arm
    // (31470-31473) only fires from the "updateNewChannelMessage" source
    if from_update && !message.is_failed_to_send && dialog_id.get_type() == DialogType::Channel {
        let now = ctx.unix_time().max(message.date);
        if message.date + 3600 >= now && message.is_outgoing {
            let channel_id = dialog_id.get_channel_id();
            let slow_mode_delay = ctx.get_channel_slow_mode_delay(channel_id);
            if (message.date + slow_mode_delay) > now && !ctx.is_channel_administrator(channel_id) {
                ctx.on_update_channel_slow_mode_next_send_date(
                    channel_id,
                    message.date + slow_mode_delay,
                );
            }
        }
        if message.date > now - 14 * 86400 {
            ctx.remove_inactive_channel(dialog_id.get_channel_id());
        }
    }

    let message_content_type = message
        .content
        .as_ref()
        .expect("message without content")
        .get_type();
    if message_content_type == MessageContentType::ContactRegistered
        && !manager
            .get_dialog(dialog_id)
            .unwrap()
            .has_contact_registered_message
    {
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        d.has_contact_registered_message = true;
        on_dialog_updated(manager, dialog_id, "update_has_contact_registered_message");
    }

    // the story-reply fan-out (31492-31500) is the StoryManager seam;
    // `reget_message_from_server_if_needed` (31502) is [blocked: net];
    // `add_message_file_sources` (31504) is M.10.18; the content/reply
    // registrations (31506/31508) are the M.9.12 register plane through
    // the Td wiring

    // the PinMessage/SetBackground/ChatSetTheme/Create ttl flips
    // (31510-31536) ride the M.10.14 pinned/background/theme slices

    // the from_update speculation family (31538-31576) — the
    // group-call/participant/hashtag/top-dialog/action-bar bodies are the
    // manager seams; update_has_outgoing_messages flipped above

    // the forum-topic count (31578-31580) is the ForumTopicManager seam

    let result_message_id = message.message_id;
    let random_id = message.random_id;
    let is_yet_unsent = message.message_id.is_yet_unsent();
    let is_scheduled_message = message.message_id.is_scheduled();
    message.debug_source = source;
    {
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        d.messages.insert(message_id, message);
        d.message_lru_list.put_back(message_id);
    }

    match dialog_id.get_type() {
        DialogType::User | DialogType::Chat => {
            if result_message_id.is_server() {
                manager
                    .message_id_to_dialog_id
                    .insert(result_message_id, dialog_id);
            }
        }
        DialogType::Channel => {
            // `register_message_users`/`register_message_channels`
            // (31594-31598) — the UserManager/ChatManager receive seams
        }
        DialogType::SecretChat | DialogType::None => {}
    }
    {
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        register_dialog_ephemeral_message(d, registered_ephemeral_message_id);

        if is_yet_unsent || dialog_id.get_type() == DialogType::SecretChat {
            add_random_id_to_message_id_correspondence(d, random_id, result_message_id);
        }
    }

    // the saved-messages topic/user/notification/bot-command
    // media-timestamp fan-out (31612-31639) is the manager receive seam

    if !ctx.is_bot()
        && is_yet_unsent
        && !is_scheduled_message
        && message_top_thread_valid(manager, dialog_id, result_message_id)
    {
        let top_thread_message_id = manager
            .get_dialog(dialog_id)
            .unwrap()
            .messages
            .get(&result_message_id)
            .unwrap()
            .top_thread_message_id;
        let is_inserted = manager
            .yet_unsent_thread_message_ids
            .entry(MessageFullId::new(dialog_id, top_thread_message_id))
            .or_default()
            .insert(result_message_id);
        assert!(is_inserted);
    }

    if is_yet_unsent && is_scheduled_message {
        // `send_update_chat_has_scheduled_messages` (31643) — the update
        // plane rides the receive wiring
        tracing::info!(
            "send_update_chat_has_scheduled_messages: {:?} after sending {}",
            dialog_id,
            DisplayMessageId(message_id)
        );
    }

    // the paid-star pending walk (31645-31652) is the StarManager seam

    manager
        .get_dialog_mut(dialog_id)
        .unwrap()
        .being_added_message_id = MessageId::default();
    manager.added_message_count += 1;

    Ok(MessageFullId::new(dialog_id, result_message_id))
}

/// The `m->top_thread_message_id.is_valid()` read for the thread registry.
fn message_top_thread_valid(
    manager: &MessagesManager,
    dialog_id: DialogId,
    message_id: MessageId,
) -> bool {
    manager
        .get_dialog(dialog_id)
        .and_then(|d| d.messages.get(&message_id))
        .map(|m| m.top_thread_message_id.is_valid())
        .unwrap_or(false)
}

/// `MessagesManager::add_scheduled_message_to_dialog`
/// (MessagesManager.cpp:31663-31830) in the send configuration — same spine
/// over the scheduled container.
#[allow(clippy::too_many_arguments)]
fn add_scheduled_message_to_dialog(
    _global: &mut crate::global::Global,
    manager: &mut MessagesManager,
    reactions_ctx: &dyn DialogReactionsContext,
    ctx: &dyn SendMessageContext,
    dialog_id: DialogId,
    mut message: Box<Message>,
    _from_database: bool,
    _from_update: bool,
    _need_update: &mut bool,
    source: &'static str,
) -> Result<MessageFullId, String> {
    let message_id = message.message_id;
    assert!(message_id.is_valid_scheduled());
    assert!(!message.notification_id.is_valid());
    assert!(!message.removed_notification_id.is_valid());

    // `fix_new_message(d, message, false)` (31675) — reads the dialog only
    if manager.get_dialog(dialog_id).is_some() {
        fix_new_message(manager, reactions_ctx, ctx, dialog_id, &mut message, false);
    }

    let d = manager
        .get_dialog_mut(dialog_id)
        .expect("add_scheduled_message_to_dialog without the dialog");

    if is_deleted_message(d, message_id) {
        tracing::info!(
            "Skip adding deleted {} to {} from {}",
            DisplayMessageId(message_id),
            dialog_id.get(),
            source
        );
        return Err("adding deleted scheduled message".to_string());
    }

    if dialog_id.get_type() == DialogType::SecretChat {
        log_error!(
            "Tried to add {} to {:?} from {}",
            DisplayMessageId(message_id),
            dialog_id,
            source
        );
        return Err("skip adding scheduled message to secret chat".to_string());
    }
    if message.ttl != MessageSelfDestructType::default() || message.ttl_expires_at != 0.0 {
        log_error!(
            "Tried to add {} with self-destruct timer to {:?} from {}",
            DisplayMessageId(message_id),
            dialog_id,
            source
        );
        return Err("skip adding secret scheduled message".to_string());
    }
    if message.ttl_period != 0 {
        log_error!(
            "Tried to add {} with auto-delete timer to {:?} from {}",
            DisplayMessageId(message_id),
            dialog_id,
            source
        );
        return Err("skip adding auto-deleting scheduled message".to_string());
    }

    let message_content_type = message
        .content
        .as_ref()
        .expect("message without content")
        .get_type();
    if crate::message_content::is_service_message_content(message_content_type)
        || message_content_type == MessageContentType::LiveLocation
        || crate::message_content::is_expired_message_content(message_content_type)
    {
        log_error!(
            "Tried to add {} of type {message_content_type:?} to {:?} from {}",
            DisplayMessageId(message_id),
            dialog_id,
            source
        );
        return Err("skip adding message of unexpected type".to_string());
    }

    // the re-add branch (31722-31748) — the memory probe; the update/delete
    // walk rides the M.10.9 container seam
    if get_message_in_dialog(d, message_id).is_some() {
        return Err("adding already existing scheduled message".to_string());
    }

    // `add_message_to_database` (31759) — skipped for yet-unsent ids; the
    // file-source/content registrations (31764-31769) are the manager seams

    if message_id.is_yet_unsent() {
        let random_id = message.random_id;
        add_random_id_to_message_id_correspondence(d, random_id, message_id);
    }

    // the media-timestamp/reply registrations and the from_update
    // speculation (31776-31800) — the M.10.9 container/manager seams

    message.debug_source = source;
    let scheduled = d.scheduled_messages.as_mut().unwrap();
    if message_id.is_scheduled_server() {
        let is_inserted = scheduled
            .scheduled_message_date
            .insert(message_id.get_scheduled_server_message_id(), message.date)
            .is_none();
        assert!(is_inserted);
    }
    let is_inserted = scheduled
        .scheduled_messages
        .insert(message_id, message)
        .is_none();
    assert!(is_inserted);

    Ok(MessageFullId::new(dialog_id, message_id))
}

/// `MessagesManager::create_message_to_send` (MessagesManager.cpp:20907-21094)
/// — the outgoing message construction: the topic/reply resolution, the
/// sender ladder, the id allocation and the field set. The td_api entry
/// ladder (`send_message`, 21721) is M.10.10; the wire query is M.10.9.
#[allow(clippy::too_many_arguments)]
pub fn create_message_to_send(
    ctx: &dyn SendMessageContext,
    d: &mut Dialog,
    message_topic: &MessageTopic,
    mut input_reply_to: MessageInputReplyTo,
    options: &MessageSendOptions,
    content: MessageContent,
    invert_media: bool,
    suppress_reply_info: bool,
    forward_info: Option<MessageForwardInfo>,
    real_forward_from_dialog_id: DialogId,
    is_copy: bool,
    send_as_dialog_id: DialogId,
    is_quick_reply_message: bool,
) -> Box<Message> {
    let is_scheduled = options.schedule_date != 0;
    let dialog_id = d.dialog_id;

    let dialog_type = dialog_id.get_type();
    let my_id = ctx.content_context().get_my_id();

    let mut reply_to_random_id = 0i64;
    let is_general = message_topic.is_forum_general();
    let initial_is_topic_message = message_topic.is_forum() && !is_general;
    let initial_top_thread_message_id = MessageId::from_server_message_id(ServerMessageId::new(
        message_topic.get_input_top_msg_id(),
    ));
    let mut is_topic_message = initial_is_topic_message;
    let mut top_thread_message_id = if is_general {
        MessageId::default()
    } else {
        initial_top_thread_message_id
    };
    let same_chat_reply_to_message_id = input_reply_to.get_same_chat_reply_to_message_id();
    if same_chat_reply_to_message_id.is_valid()
        || same_chat_reply_to_message_id.is_valid_scheduled()
    {
        // the message was forcibly preloaded in create_message_input_reply_to
        // it can be missing, only if it is unknown message from a push
        // notification, or an unknown top thread message
        let reply_m = get_message_in_dialog(d, same_chat_reply_to_message_id);
        if let Some(reply_m) = reply_m
            && !same_chat_reply_to_message_id.is_scheduled()
        {
            if reply_m.top_thread_message_id.is_valid() {
                top_thread_message_id = reply_m.top_thread_message_id;
            }
            is_topic_message = reply_m.is_topic_message;
        }
        if dialog_type == DialogType::SecretChat || same_chat_reply_to_message_id.is_yet_unsent() {
            if let Some(reply_m) = reply_m {
                reply_to_random_id = reply_m.random_id;
            } else {
                assert!(dialog_type == DialogType::SecretChat);
                assert!(message_topic.is_empty());
                input_reply_to = MessageInputReplyTo::default();
            }
        }
    } else if top_thread_message_id.is_valid()
        && dialog_type == DialogType::Channel
        && let Some(top_m) = get_message_in_dialog(d, top_thread_message_id)
    {
        is_topic_message = top_m.is_topic_message;
    }
    tracing::debug!(
        "Create {}topic message in thread of {}",
        if is_topic_message { "" } else { "non-" },
        DisplayMessageId(top_thread_message_id)
    );

    let mut message = Box::new(Message {
        content: Some(content),
        ..Message::default()
    });
    let is_channel_post = ctx.is_broadcast_channel_dialog(dialog_id);
    if !is_channel_post
        || (!is_scheduled && ctx.get_channel_sign_messages(dialog_id.get_channel_id()))
    {
        if message_topic.is_monoforum() {
            assert!(dialog_id.get_type() == DialogType::Channel);
            let channel_id = ctx.get_monoforum_channel_id(dialog_id.get_channel_id());
            assert!(channel_id.is_valid());
            message.sender_dialog_id = DialogId::from_channel_id(channel_id);
        } else if send_as_dialog_id.is_valid() {
            // for resend_messages
            if send_as_dialog_id.get_type() == DialogType::User {
                message.sender_user_id = send_as_dialog_id.get_user_id();
            } else {
                message.sender_dialog_id = send_as_dialog_id;
            }
            if dialog_type == DialogType::Channel {
                message.has_explicit_sender = true;
            }
        } else if d.default_send_message_as_dialog_id.is_valid() {
            if d.default_send_message_as_dialog_id.get_type() == DialogType::User {
                // 1:1 with the C++ (20975-20981): the User-typed default
                // send-as resolves to the own sender
                message.sender_user_id = my_id;
            } else {
                message.sender_dialog_id = d.default_send_message_as_dialog_id;
            }
            message.has_explicit_sender = true;
        } else {
            if !is_channel_post
                && let Some(author_signature) = ctx.is_anonymous_administrator(dialog_id)
            {
                message.author_signature = author_signature;
                message.sender_dialog_id = dialog_id;
            } else {
                message.sender_user_id = my_id;
            }
        }
    } else {
        message.sender_dialog_id = dialog_id;
    }
    if is_channel_post && !is_scheduled && ctx.get_channel_sign_messages(dialog_id.get_channel_id())
    {
        let show_message_sender = ctx.get_channel_show_message_sender(dialog_id.get_channel_id());
        if message.sender_dialog_id != dialog_id || !message.has_explicit_sender {
            message.author_signature = if message.sender_dialog_id == dialog_id
                || message.sender_dialog_id == DialogId::default()
            {
                ctx.get_user_title(my_id)
            } else {
                ctx.get_dialog_title(message.sender_dialog_id)
            };
        }
        if !show_message_sender {
            message.initial_sender_dialog_id = get_message_sender(&message);
            message.sender_user_id = UserId::default();
            message.sender_dialog_id = dialog_id;
        }
    }
    message.message_id = if is_scheduled {
        get_next_yet_unsent_scheduled_message_id(d, options.schedule_date)
    } else {
        get_next_yet_unsent_message_id(d, ctx.is_bot())
    };
    message.send_date = ctx.unix_time();
    message.date = if is_scheduled {
        options.schedule_date
    } else {
        message.send_date
    };
    message.schedule_repeat_period = options.schedule_repeat_period;
    message.replied_message_info =
        replied_message_info_from_input_reply_to(ctx, dialog_id, &input_reply_to, message_topic);
    message.reply_to_story_full_id = input_reply_to.story_full_id;
    message.input_reply_to = input_reply_to.clone();
    message.reply_to_random_id = reply_to_random_id;
    message.top_thread_message_id = top_thread_message_id;
    message.initial_top_thread_message_id = initial_top_thread_message_id;
    message.is_topic_message = is_topic_message;
    message.initial_is_topic_message = initial_is_topic_message;
    message.is_channel_post = is_channel_post;
    message.is_outgoing = is_scheduled || dialog_id != DialogId::from_user_id(my_id);
    message.from_background = options.from_background;
    message.is_quick_reply_message = is_quick_reply_message;
    message.update_stickersets_order = options.update_stickersets_order;
    message.noforwards = options.protect_content;
    message.allow_paid = options.allow_paid;
    message.paid_message_star_count = options.paid_message_star_count;
    message.view_count = if is_channel_post && !is_scheduled {
        1
    } else {
        0
    };
    message.forward_count = 0;
    if !suppress_reply_info
        && !is_scheduled
        && dialog_type == DialogType::Channel
        && !ctx.is_bot()
        && if is_channel_post {
            ctx.get_channel_has_linked_channel(dialog_id.get_channel_id())
        } else {
            !message.input_reply_to.is_valid()
        }
    {
        message.reply_info.reply_count = 0;
        if is_channel_post {
            let linked_channel_id = ctx.get_channel_linked_channel_id(
                dialog_id.get_channel_id(),
                "create_message_to_send",
            );
            if linked_channel_id.is_valid() {
                message.reply_info.is_comment = true;
                message.reply_info.channel_id = linked_channel_id;
            }
        }
    }
    if message.sender_user_id == my_id && dialog_type == DialogType::Channel && !is_channel_post {
        message.sender_boost_count = ctx.get_channel_my_boost_count(dialog_id.get_channel_id());
        // m->sender_rank = get_my_rank — the DialogManager seam (21058)
    }
    message.effect_id = MessageEffectId::new(options.effect_id.get());
    message.invert_media = invert_media;
    message.forward_info = forward_info;
    message.real_forward_from_dialog_id = real_forward_from_dialog_id;
    message.is_copy = is_copy || message.forward_info.is_some();
    message.sending_id = options.sending_id;
    message.suggested_post = options.suggested_post.clone();

    message.disable_notification = if ctx.is_bot()
        || options.disable_notification
        || ctx.ignore_default_disable_notification()
    {
        options.disable_notification
    } else {
        d.notification_settings.silent_send_message
    };

    if dialog_type == DialogType::SecretChat {
        assert!(!is_scheduled);
        let content_type = message
            .content
            .as_ref()
            .expect("message without content")
            .get_type();
        if crate::message_content::is_service_message_content(content_type) {
            message.ttl = MessageSelfDestructType::default();
        } else {
            message.ttl = MessageSelfDestructType::with_ttl(
                ctx.get_secret_chat_ttl(dialog_id.get_secret_chat_id()),
                false,
            );
        }
        message.is_content_secret = message.ttl.is_secret_message_content(content_type);
    }
    if dialog_id == DialogId::from_user_id(my_id) {
        message.saved_messages_topic_id = SavedMessagesTopicId::from_forward(
            ctx,
            dialog_id,
            message.forward_info.as_ref(),
            message.real_forward_from_dialog_id,
        );
    } else if message_topic.is_monoforum() {
        message.saved_messages_topic_id = message_topic.get_monoforum_saved_messages_topic_id();
    }
    if message.sender_dialog_id.is_valid() && message.sender_dialog_id != dialog_id {
        ctx.force_create_dialog(message.sender_dialog_id, "create_message_to_send");
    }
    message
}

/// `MessagesManager::get_message_actual_content` (MessagesManager.h:3229,
/// MessagesManager.cpp:23448-23452) — the ephemeral unwrap.
pub(crate) fn get_message_actual_content(m: &Message) -> &MessageContent {
    match &m.ephemeral_message {
        None => m.content.as_ref().expect("message without content"),
        Some(ephemeral_message) => ephemeral_message
            .content
            .as_ref()
            .expect("message without content"),
    }
}

/// `MessagesManager::can_forward_message` (MessagesManager.cpp:8275-8310) —
/// the `can_be_forwarded` input of the cross-chat reply gate.
pub fn can_forward_message(
    ctx: &dyn SendMessageContext,
    from_dialog_id: DialogId,
    m: Option<&Message>,
    is_copy: bool,
) -> bool {
    let Some(m) = m else {
        return false;
    };
    if !m.ttl.is_empty() {
        return false;
    }
    assert!(!m.is_content_secret);
    if m.message_id.is_scheduled() {
        return false;
    }
    if !is_copy && !m.message_id.is_server() && !is_ephemeral_message(m) {
        return false;
    }
    match from_dialog_id.get_type() {
        DialogType::User | DialogType::Chat | DialogType::Channel => {}
        DialogType::SecretChat => return false,
        DialogType::None => unreachable!(),
    }
    let content = get_message_actual_content(m);
    if !crate::message_content::can_forward_message_content(ctx.content_context(), content, is_copy)
    {
        return false;
    }
    if !(is_copy && ctx.is_bot()) && get_message_has_protected_content(ctx, from_dialog_id, m) {
        return false;
    }
    true
}

/// `MessagesManager::can_reply_to_message` (MessagesManager.cpp:8311-8328).
pub fn can_reply_to_message(
    ctx: &dyn SendMessageContext,
    d: &Dialog,
    message_id: MessageId,
    m: Option<&Message>,
) -> bool {
    let dialog_id = d.dialog_id;
    if m.is_some_and(is_ephemeral_message) {
        let m = m.unwrap();
        return m.ephemeral_message_id.is_valid() && !m.is_outgoing;
    }
    if !ctx.is_bot()
        && let Some(m) = m
        && m.is_topic_message
        && d.is_forum
    {
        let forum_topic_id = ForumTopicId::from_top_thread_message_id(m.top_thread_message_id);
        if !ctx.can_send_message_to_forum_topic(dialog_id, forum_topic_id) {
            return false;
        }
    }
    message_id.is_valid()
        && !(message_id == MessageId::from_server_message_id(ServerMessageId::new(1))
            && dialog_id.get_type() == DialogType::Channel)
        && !message_id.is_yet_unsent()
        && (!message_id.is_local() || dialog_id.get_type() == DialogType::SecretChat)
        && ctx.can_send_message_to_dialog(dialog_id).is_ok()
}

/// `MessagesManager::can_reply_to_message_in_another_dialog`
/// (MessagesManager.cpp:8329-8334).
pub fn can_reply_to_message_in_another_dialog(
    ctx: &dyn SendMessageContext,
    dialog_id: DialogId,
    m: Option<&Message>,
    can_be_forwarded: bool,
) -> bool {
    can_be_forwarded
        && m.is_some_and(|m| m.message_id.is_server())
        && m.is_none_or(|m| m.ephemeral_message.is_none())
        && !ctx.is_monoforum_channel_dialog(dialog_id)
        && !(m.is_some_and(|m| {
            m.message_id == MessageId::from_server_message_id(ServerMessageId::new(1))
        }) && dialog_id.get_type() == DialogType::Channel)
}

/// `MessageQuote::MessageQuote(Td *, td_api::InputTextQuote)`
/// (MessageQuote.cpp:54-70) — the input quote parse behind the
/// `inputMessageReplyToMessage`/`...ExternalMessage` arms.
fn get_message_quote_from_input(
    ctx: &mut dyn SendMessageContext,
    quote: Option<td_api::InputTextQuote>,
) -> MessageQuote {
    let Some(quote) = quote else {
        return MessageQuote::default();
    };
    let mut ltrim_count = 0i32;
    let my_dialog_id = ctx.get_my_dialog_id();
    let always_parse_markdown = ctx
        .content_context()
        .get_option_boolean("always_parse_markdown", false);
    let session_count = ctx.content_context().get_option_integer("session_count", 0) as i32;
    let can_use_premium_custom_emoji_in_dialog = ctx
        .content_context()
        .can_use_premium_custom_emoji_in_dialog(my_dialog_id);
    let mut user_manager = crate::message_content::ContextUserManager::new(ctx.content_context());
    let r_text = crate::message_entity::get_formatted_text_of_input(
        Some(&mut user_manager),
        crate::message_content::to_message_entity_dialog_id(my_dialog_id),
        quote.text,
        ctx.is_bot(),
        true,
        true,
        false,
        Some(&mut ltrim_count),
        always_parse_markdown,
        session_count,
        Some(&mut |custom_emoji_id, is_premium| {
            is_premium
                || ctx
                    .content_context()
                    .is_premium_custom_emoji(custom_emoji_id)
        }),
        can_use_premium_custom_emoji_in_dialog,
    );
    let text = match r_text {
        Result::Ok(text) if !text.text.is_empty() => text,
        _ => return MessageQuote::default(),
    };
    let mut position = quote.position;
    if (0..=1_000_000).contains(&position) {
        // some unreasonably big bound
        position += ltrim_count;
    } else {
        position = 0;
    }
    MessageQuote {
        text,
        position,
        is_manual: false,
    }
}

/// `RepliedMessageInfo::RepliedMessageInfo(Td *, const MessageInputReplyTo &,
/// DialogId, const MessageTopic &)` (RepliedMessageInfo.cpp:142-199) — the
/// send-path ctor. The same-chat/ephemeral legs are exact; the cross-chat
/// content embedding rides the [`SendMessageContext::get_forwarded_message_info`]
/// seam (M.10.11's forward path).
pub fn replied_message_info_from_input_reply_to(
    ctx: &dyn SendMessageContext,
    dialog_id: DialogId,
    input_reply_to: &MessageInputReplyTo,
    // the C++ reads the topic only inside the cross-chat origin rewrite
    // (RepliedMessageInfo.cpp:193-198), which rides the
    // get_forwarded_message_info seam (M.10.11)
    _message_topic: &MessageTopic,
) -> RepliedMessageInfo {
    let mut result = RepliedMessageInfo::default();
    if !input_reply_to.message_id.is_valid() && !input_reply_to.message_id.is_valid_scheduled() {
        if input_reply_to.ephemeral_message_id.is_valid() {
            result.message_id = ctx.get_message_id_of_ephemeral_message_id(
                dialog_id,
                input_reply_to.ephemeral_message_id,
            );
        }
        return result;
    }
    result.message_id = input_reply_to.message_id;
    result.quote = input_reply_to.quote.clone();
    result.todo_item_id = input_reply_to.todo_item_id;
    result.poll_option_id = input_reply_to.poll_option_id.clone();
    if input_reply_to.dialog_id != DialogId::default() && input_reply_to.message_id.is_valid() {
        let Some(info) =
            ctx.get_forwarded_message_info(input_reply_to.dialog_id, input_reply_to.message_id)
        else {
            // the C++ `*this = {}` reset when the replied message cannot be
            // loaded (RepliedMessageInfo.cpp:152-156); per the seam contract
            // the M.10.11 implementation also answers None for a
            // partially-populated info failing the C++
            // `origin_date == 0 || origin.is_empty() || content == nullptr`
            // tri-condition, which lands here the same way
            return RepliedMessageInfo::default();
        };
        result.origin_date = info.origin_date;
        result.origin = info.origin;
        result.content = info.content;
        // the automatic-quote embedding, the Text-content strip and the
        // origin-id rewrite (RepliedMessageInfo.cpp:158-198) ride the same
        // M.10.11 forward seam with the info fetch
    }
    result
}

/// `MessagesManager::can_send_message` (MessagesManager.cpp:21129-21131) —
/// the direct pass-through kept for the call-shape parity.
pub fn can_send_message(
    ctx: &dyn SendMessageContext,
    dialog_id: DialogId,
) -> Result<(), (i32, String)> {
    ctx.can_send_message_to_dialog(dialog_id)
}

/// `MessagesManager::get_message_to_send` (MessagesManager.cpp:21096-21118)
/// — creates the outgoing message, assigns its random id and inserts it
/// through `add_message_to_dialog`. The wire query stays the M.10.9 seam.
#[allow(clippy::too_many_arguments)]
pub fn get_message_to_send(
    ctx: &mut dyn SendMessageContext,
    global: &mut crate::global::Global,
    manager: &mut MessagesManager,
    reactions_ctx: &dyn DialogReactionsContext,
    state: &mut dyn ReadStateContext,
    dialog_id: DialogId,
    message_topic: &MessageTopic,
    input_reply_to: MessageInputReplyTo,
    options: &MessageSendOptions,
    content: MessageContent,
    invert_media: bool,
    need_update_dialog_pos: &mut bool,
    suppress_reply_info: bool,
    forward_info: Option<MessageForwardInfo>,
    real_forward_from_dialog_id: DialogId,
    is_copy: bool,
    send_as_dialog_id: DialogId,
    is_quick_reply_message: bool,
) -> MessageFullId {
    let message = {
        let d = manager
            .get_dialog_mut(dialog_id)
            .expect("get_message_to_send without the dialog");
        d.was_opened = true;
        create_message_to_send(
            ctx,
            d,
            message_topic,
            input_reply_to,
            options,
            content,
            invert_media,
            suppress_reply_info,
            forward_info,
            real_forward_from_dialog_id,
            is_copy,
            send_as_dialog_id,
            is_quick_reply_message,
        )
    };
    let message_id = message.message_id;
    let random_id = {
        let d = manager
            .get_dialog(dialog_id)
            .expect("get_message_to_send without the dialog");
        generate_new_random_id(d, &manager.being_sent_messages)
    };
    let mut message = message;
    message.random_id = random_id;

    assert!(
        ctx.have_input_peer_read(dialog_id, true),
        "have_input_peer(Read) failed for {dialog_id:?} in get_message_to_send"
    );
    let mut need_update = false;
    let result = add_message_to_dialog(
        global,
        manager,
        reactions_ctx,
        &*ctx,
        state,
        dialog_id,
        message,
        false,
        true,
        &mut need_update,
        need_update_dialog_pos,
        "send message",
    );
    let result_full_id = match result {
        Result::Ok(full_id) => full_id,
        Result::Err(fail_reason) => {
            panic!("LOG_CHECK failed in get_message_to_send: {message_id:?} {fail_reason}")
        }
    };
    if options.update_stickersets_order && !ctx.is_bot() {
        let d = manager
            .get_dialog(dialog_id)
            .expect("get_message_to_send without the dialog");
        if let Some(result_message) = get_message_in_dialog(d, result_full_id.get_message_id())
            && let Some(content) = result_message.content.as_ref()
        {
            crate::message_content::move_message_content_sticker_set_to_top(
                ctx.content_context_mut(),
                content,
            );
        }
    }
    result_full_id
}

/// `MessagesManager::get_message_input_reply_to` (MessagesManager.cpp:21331-21335).
pub fn get_message_input_reply_to(m: &Message) -> &MessageInputReplyTo {
    assert!(!m.message_id.is_any_server());
    &m.input_reply_to
}

/// `MessagesManager::get_message_random_id(MessageFullId)`
/// (MessagesManager.cpp:21337-21343) — the db-load leg of
/// `get_dialog_force` is the dialog-db receive seam.
pub fn get_message_random_id(manager: &MessagesManager, message_full_id: MessageFullId) -> i64 {
    let Some(d) = manager.get_dialog(message_full_id.get_dialog_id()) else {
        return 0;
    };
    get_message_random_id_in_dialog(d, message_full_id.get_message_id())
}

/// `MessagesManager::get_message_random_id(Dialog *, MessageId)`
/// (MessagesManager.cpp:21345-21351).
pub fn get_message_random_id_in_dialog(d: &Dialog, message_id: MessageId) -> i64 {
    get_message_in_dialog(d, message_id).map_or(0, |m| m.random_id)
}

/// `MessagesManager::create_message_input_reply_to(DialogId, ...)`
/// (MessagesManager.cpp:20892-20896) — the wrapper over the loaded dialog.
pub fn create_message_input_reply_to(
    ctx: &mut dyn SendMessageContext,
    manager: &MessagesManager,
    dialog_id: DialogId,
    message_topic: &MessageTopic,
    reply_to: Option<td_api::InputMessageReplyTo>,
    for_draft: bool,
) -> MessageInputReplyTo {
    let d = manager
        .get_dialog(dialog_id)
        .expect("create_message_input_reply_to without the dialog");
    create_message_input_reply_to_full(ctx, manager, d, message_topic, reply_to, for_draft, false)
}

/// `MessagesManager::create_message_input_reply_to(Dialog *, ...)`
/// (MessagesManager.cpp:21149-21314) — the four td_api arms. Every guard
/// SILENTLY DROPS (`return {}`) like the C++; the user-visible errors live
/// in the M.10.10 send entry ladder.
#[allow(clippy::too_many_arguments)]
pub fn create_message_input_reply_to_full(
    ctx: &mut dyn SendMessageContext,
    manager: &MessagesManager,
    d: &Dialog,
    message_topic: &MessageTopic,
    reply_to: Option<td_api::InputMessageReplyTo>,
    for_draft: bool,
    for_ephemeral_message: bool,
) -> MessageInputReplyTo {
    let implicit_reply_to_message_id = message_topic.get_implicit_reply_to_message_id(ctx);
    if implicit_reply_to_message_id.is_valid()
        && !have_message_force(
            d,
            implicit_reply_to_message_id,
            "create_message_input_reply_to 1",
        )
    {
        tracing::info!(
            "Have implicit reply to unknown {}",
            DisplayMessageId(implicit_reply_to_message_id)
        );
    }
    assert!(
        implicit_reply_to_message_id == MessageId::default()
            || implicit_reply_to_message_id.is_server()
    );
    let Some(reply_to) = reply_to else {
        if !for_draft && implicit_reply_to_message_id.is_valid() {
            return MessageInputReplyTo::regular(implicit_reply_to_message_id);
        }
        return MessageInputReplyTo::default();
    };
    match reply_to {
        td_api::InputMessageReplyTo::inputMessageReplyToStory(reply_to_story) => {
            if for_draft || for_ephemeral_message {
                return MessageInputReplyTo::default();
            }
            let story_id = StoryId::new(reply_to_story.story_id);
            let sender_dialog_id = DialogId::new(reply_to_story.story_poster_chat_id);
            if d.dialog_id != sender_dialog_id
                || ctx
                    .content_context()
                    .is_broadcast_channel_dialog(sender_dialog_id)
            {
                tracing::info!(
                    "Ignore reply to story from {:?} in a wrong {:?}",
                    sender_dialog_id,
                    d.dialog_id
                );
                return MessageInputReplyTo::default();
            }
            if !story_id.is_server() {
                tracing::info!("Ignore reply to invalid story {:?}", story_id);
                return MessageInputReplyTo::default();
            }
            if !message_topic.is_empty() {
                tracing::info!("Story replies can't be sent to a specific topic");
                return MessageInputReplyTo::default();
            }
            MessageInputReplyTo {
                story_full_id: StoryFullId::new(sender_dialog_id, story_id),
                ..MessageInputReplyTo::default()
            }
        }
        td_api::InputMessageReplyTo::inputMessageReplyToMessage(reply_to_message) => {
            let mut message_id = MessageId::new(reply_to_message.message_id);
            if !message_id.is_valid() {
                if message_id == MessageId::default()
                    && !for_draft
                    && implicit_reply_to_message_id.is_valid()
                {
                    return MessageInputReplyTo::regular(implicit_reply_to_message_id);
                }
                return MessageInputReplyTo::default();
            }
            message_id = get_persistent_message_id(manager, d, message_id);
            let checklist_task_id = reply_to_message.checklist_task_id.max(0);
            let mut poll_option_id = reply_to_message.poll_option_id;
            if crate::misc::clean_input_string(&poll_option_id).is_none() {
                poll_option_id.clear();
            }
            // `get_message_force(d, message_id, "create_message_input_reply_to 2")`
            // — the memory probe; the db load is the dialog-db receive seam
            let mut m = get_message_in_dialog(d, message_id);
            if !can_reply_to_message(ctx, d, message_id, m)
                || (!for_ephemeral_message && m.is_some_and(is_ephemeral_message))
            {
                message_id = MessageId::default();
                m = None;
            }
            let Some(m) = m else {
                if message_id.is_server()
                    && d.dialog_id.get_type() != DialogType::SecretChat
                    && d.last_new_message_id.is_valid()
                    && message_id > d.last_new_message_id
                    && d.notification_info
                        .as_ref()
                        .is_some_and(|notification_info| {
                            message_id <= notification_info.max_push_notification_message_id
                        })
                {
                    // allow to reply to yet unreceived server message in the
                    // same chat
                    return MessageInputReplyTo {
                        message_id,
                        ephemeral_message_id: EphemeralMessageId::default(),
                        dialog_id: DialogId::default(),
                        quote: get_message_quote_from_input(ctx, reply_to_message.quote),
                        todo_item_id: checklist_task_id,
                        poll_option_id,
                        debug_source: "create_message_input_reply_to 4",
                        story_full_id: StoryFullId::default(),
                    };
                }
                if !for_draft && implicit_reply_to_message_id.is_valid() {
                    return MessageInputReplyTo::regular(implicit_reply_to_message_id);
                }
                tracing::info!(
                    "Can't find {} in {:?}",
                    DisplayMessageId(message_id),
                    d.dialog_id
                );

                // TODO local replies to local messages can be allowed
                // TODO replies to yet unsent messages can be allowed with
                // special handling of them on application restart
                return MessageInputReplyTo::default();
            };

            // the replied message must be in the same topic; check this if
            // possible
            if !message_topic.is_empty() {
                let reply_message_topic = get_message_topic(ctx, d.dialog_id, m);
                if *message_topic != reply_message_topic {
                    if !message_topic.is_thread()
                        || !reply_message_topic.is_empty()
                        || m.media_album_id == 0
                    {
                        tracing::info!("Ignore reply to message from a different topic");
                        return MessageInputReplyTo::default();
                    }
                    assert!(d.dialog_id.get_type() == DialogType::Channel);

                    // if the message is in an album and not in the thread,
                    // it can be in the album of the top thread message
                    // `get_message_force(..., "create_message_input_reply_to 3")`
                    // — the memory probe; the db load is the dialog-db seam
                    let top_m = get_message_in_dialog(d, implicit_reply_to_message_id);
                    if top_m.is_some_and(|top_m| {
                        top_m.media_album_id != m.media_album_id
                            || top_m.top_thread_message_id != top_m.message_id
                    }) {
                        tracing::info!("Ignore reply to an album message from a different topic");
                        return MessageInputReplyTo::default();
                    }
                }
            }

            let mut checklist_task_id = checklist_task_id;
            let content_type = m
                .content
                .as_ref()
                .expect("message without content")
                .get_type();
            if checklist_task_id != 0 && content_type != MessageContentType::ToDoList {
                checklist_task_id = 0;
            }
            if !poll_option_id.is_empty() && content_type != MessageContentType::Poll {
                poll_option_id.clear();
            }
            MessageInputReplyTo {
                message_id: m.message_id,
                ephemeral_message_id: m.ephemeral_message_id,
                dialog_id: DialogId::default(),
                quote: get_message_quote_from_input(ctx, reply_to_message.quote),
                todo_item_id: checklist_task_id,
                poll_option_id,
                debug_source: "create_message_input_reply_to 5",
                story_full_id: StoryFullId::default(),
            }
        }
        td_api::InputMessageReplyTo::inputMessageReplyToExternalMessage(reply_to_message) => {
            if d.dialog_id.get_type() == DialogType::SecretChat || for_ephemeral_message {
                return MessageInputReplyTo::default();
            }
            let reply_dialog_id = DialogId::new(reply_to_message.chat_id);
            // `get_dialog_force(reply_dialog_id, "create_message_input_reply_to")`
            // — the memory probe; the db-load/create leg is the dialog-db
            // receive seam
            let Some(reply_d) = manager.get_dialog(reply_dialog_id) else {
                return MessageInputReplyTo::default();
            };
            let message_id = get_persistent_message_id(
                manager,
                reply_d,
                MessageId::new(reply_to_message.message_id),
            );
            // `get_message_force(reply_d, message_id, "create_message_input_reply_to 2")`
            // — the memory probe; the db load is the dialog-db receive seam
            let m = get_message_in_dialog(reply_d, message_id);
            if !can_reply_to_message_in_another_dialog(
                ctx,
                reply_dialog_id,
                m,
                can_forward_message(ctx, reply_dialog_id, m, false),
            ) {
                tracing::info!(
                    "Can't reply in another chat {} in {:?}",
                    DisplayMessageId(message_id),
                    reply_d.dialog_id
                );
                return MessageInputReplyTo::default();
            }
            let mut checklist_task_id = reply_to_message.checklist_task_id.max(0);
            if let Some(m) = m
                && checklist_task_id != 0
                && m.content
                    .as_ref()
                    .expect("message without content")
                    .get_type()
                    != MessageContentType::ToDoList
            {
                checklist_task_id = 0;
            }
            let mut poll_option_id = reply_to_message.poll_option_id;
            if crate::misc::clean_input_string(&poll_option_id).is_none()
                || m.is_some_and(|m| {
                    m.content
                        .as_ref()
                        .expect("message without content")
                        .get_type()
                        != MessageContentType::Poll
                })
            {
                poll_option_id.clear();
            }
            MessageInputReplyTo {
                message_id: m.map_or(MessageId::default(), |m| m.message_id),
                ephemeral_message_id: EphemeralMessageId::default(),
                dialog_id: reply_dialog_id,
                quote: get_message_quote_from_input(ctx, reply_to_message.quote),
                todo_item_id: checklist_task_id,
                poll_option_id,
                debug_source: "create_message_input_reply_to 6",
                story_full_id: StoryFullId::default(),
            }
        }
        td_api::InputMessageReplyTo::inputMessageReplyToEphemeralMessage(reply_to_message) => {
            let ephemeral_message_id =
                EphemeralMessageId::new(reply_to_message.ephemeral_message_id);
            if !for_ephemeral_message || !ctx.is_bot() || !ephemeral_message_id.is_valid() {
                return MessageInputReplyTo::default();
            }
            MessageInputReplyTo {
                message_id: MessageId::default(),
                ephemeral_message_id,
                dialog_id: DialogId::default(),
                quote: MessageQuote::default(),
                todo_item_id: 0,
                poll_option_id: String::new(),
                debug_source: "create_message_input_reply_to 7",
                story_full_id: StoryFullId::default(),
            }
        }
    }
}

/// `MessagesManager::SendMessageLogEvent` (MessagesManager.cpp:21696-21719)
/// — the durable half-sent message: `dialog_id` + the full `Message` store.
/// The framing matches the C++ `get_log_event_storer` exactly (the log-event
/// version word, then `td::store(dialog_id)` + `td::store(*m)`); the store
/// side borrows the live message like the C++ `m_in`.
pub struct SendMessageLogEvent {
    pub dialog_id: DialogId,
    pub message: Box<Message>,
}

impl SendMessageLogEvent {
    /// `SendMessageLogEvent::store` (MessagesManager.cpp:21708-21712).
    pub fn store(
        dialog_id: DialogId,
        m: &Message,
        storage: &dyn crate::message_content::MessageContentStorage,
        time: &crate::user_manager::TimeCtx,
        out: &mut Vec<u8>,
    ) {
        crate::store_parse::store_log_event_version(out);
        dialog_id.store(out);
        m.store(storage, time, out);
    }

    /// The binlog `add` payload for the live message.
    pub fn store_to_bytes(
        dialog_id: DialogId,
        m: &Message,
        storage: &dyn crate::message_content::MessageContentStorage,
        time: &crate::user_manager::TimeCtx,
    ) -> Vec<u8> {
        let mut bytes = Vec::new();
        Self::store(dialog_id, m, storage, time, &mut bytes);
        bytes
    }

    /// `SendMessageLogEvent::parse` (MessagesManager.cpp:21714-21718).
    pub fn parse_from(
        parser: &mut Parser,
        storage: &mut dyn crate::message_content::MessageContentStorage,
        time: &crate::user_manager::TimeCtx,
    ) -> Result<SendMessageLogEvent, &'static str> {
        let dialog_id = DialogId::parse_from(parser)?;
        let message = Message::parse_from(parser, storage, time)?;
        Ok(SendMessageLogEvent {
            dialog_id,
            message: Box::new(message),
        })
    }

    /// `log_event_parse(SendMessageLogEvent, event.get_data())` — the binlog
    /// event body with the version word.
    pub fn parse_from_bytes(
        input: &[u8],
        storage: &mut dyn crate::message_content::MessageContentStorage,
        time: &crate::user_manager::TimeCtx,
    ) -> Result<SendMessageLogEvent, &'static str> {
        let mut parser = Parser::new_log_event(input)?;
        let log_event = Self::parse_from(&mut parser, storage, time)?;
        parser.fetch_end()?;
        Ok(log_event)
    }
}

/// `MessagesManager::save_send_message_log_event`
/// (MessagesManager.cpp:21980-21991) — the event FIRST half of the
/// save-then-send crash-consistency contract (21800-21801).
pub fn save_send_message_log_event(
    global: &mut crate::global::Global,
    dialog_id: DialogId,
    m: &mut Message,
) {
    if !global.use_message_database() {
        return;
    }

    tracing::info!(
        "Save {}:{} to binlog",
        dialog_id.get(),
        DisplayMessageId(m.message_id)
    );
    let time = crate::user_manager::TimeCtx::from_global(global);
    let data = SendMessageLogEvent::store_to_bytes(dialog_id, m, &MessageDbStorageBridge, &time);
    assert!(m.send_message_log_event_id == 0);
    m.send_message_log_event_id = global
        .td_db()
        .binlog()
        .add(tddb::td_db::LOG_EVENT_HANDLER_TYPE_SEND_MESSAGE, &data);
}

/// `MessagesManager::get_message_reply_to_random_id`
/// (MessagesManager.cpp:32205-32215).
pub fn get_message_reply_to_random_id(d: &Dialog, m: &Message) -> i64 {
    let same_chat_reply_to_message_id = m
        .replied_message_info
        .get_same_chat_reply_to_message_id(true);
    if same_chat_reply_to_message_id != MessageId::default()
        && m.message_id.is_yet_unsent()
        && (d.dialog_id.get_type() == DialogType::SecretChat
            || same_chat_reply_to_message_id.is_yet_unsent())
        && let Some(replied_m) = get_message_in_dialog(d, same_chat_reply_to_message_id)
    {
        return replied_m.random_id;
    }
    0
}

/// `MessagesManager::update_message_reply_to_message_id`
/// (MessagesManager.cpp:35823-35840) — the replied-id rewrite; the reply
/// registry walks (`unregister/register_message_reply`) are the M.10.9
/// container seam.
pub fn update_message_reply_to_message_id(
    d: &Dialog,
    m: &mut Message,
    reply_to_message_id: MessageId,
    _source: &'static str,
) {
    tracing::info!(
        "Update identifier of replied message of {}:{} to {}",
        d.dialog_id.get(),
        DisplayMessageId(m.message_id),
        DisplayMessageId(reply_to_message_id)
    );
    // `unregister_message_reply` (35827) — the M.10.9 container seam
    m.replied_message_info.set_message_id(reply_to_message_id);
    if !m.message_id.is_any_server() {
        m.input_reply_to
            .set_message_id(reply_to_message_id, "restore_message_reply_to_message_id");
    }
    // `register_message_reply` (35835) — the same seam
}

/// `MessagesManager::set_message_reply` (MessagesManager.cpp:35822-35838) —
/// the implicit-reply reset leg of the restore.
/// `MessagesManager::update_has_outgoing_messages`
/// (MessagesManager.cpp:35786-35817) — the live from_update send leg:
/// computes the C++ gates and answers the dialog whose
/// `has_outgoing_messages` must flip (`None` when the C++ returns early).
/// The caller performs the flip; `on_dialog_updated`
/// ("update_has_outgoing_messages") — the binlog-pmc dirty marker — is the
/// dialog-db receive seam, and the action-bar re-emit (35815-35817,
/// `DialogActionBar::on_outgoing_message` → `send_update_chat_action_bar`)
/// is the update/action-bar seam.
fn update_has_outgoing_messages_target(
    ctx: &dyn SendMessageContext,
    manager: &MessagesManager,
    dialog_id: DialogId,
    m: &Message,
) -> Option<DialogId> {
    if ctx.is_bot()
        || (!m.is_outgoing
            && dialog_id != DialogId::from_user_id(ctx.content_context().get_my_id()))
    {
        return None;
    }

    // the dialog whose flag flips is the User dialog itself, or the peer
    // user behind a secret chat
    let target_dialog_id = match dialog_id.get_type() {
        DialogType::User => dialog_id,
        DialogType::SecretChat => {
            let user_id = ctx
                .content_context()
                .get_secret_chat_user_id(dialog_id.get_secret_chat_id());
            if !user_id.is_valid() {
                return None;
            }
            DialogId::from_user_id(user_id)
        }
        DialogType::Chat | DialogType::Channel => return None,
        DialogType::None => unreachable!(),
    };
    let d = manager.get_dialog(target_dialog_id)?;
    // `get_dialog`/`get_dialog_force` — the db-load leg is the dialog-db
    // receive seam
    if d.has_outgoing_messages {
        return None;
    }
    Some(target_dialog_id)
}

/// `MessagesManager::update_message_max_reply_media_timestamp`
/// (MessagesManager.cpp:23959-24013). The closing update emission
/// (24005-24012, `need_send_update_message_content = true`) is the M.10.9
/// update plane over the M.9 `has_media_timestamps` helper.
fn update_message_max_reply_media_timestamp(
    manager: &MessagesManager,
    ctx: &dyn SendMessageContext,
    d: &Dialog,
    m: &mut Message,
    need_send_update_message_content: bool,
) {
    if ctx.is_bot() {
        return;
    }

    let mut new_max_reply_media_timestamp = -1;
    let reply_message_full_id = m
        .replied_message_info
        .get_reply_message_full_id(d.dialog_id, false);
    let reply_message_id = reply_message_full_id.get_message_id();
    if reply_message_id.is_valid() && !reply_message_id.is_yet_unsent() {
        let reply_d = if reply_message_full_id.get_dialog_id() != d.dialog_id {
            // `get_dialog(reply_message_full_id.get_dialog_id())` — the
            // db-load leg is the dialog-db receive seam
            manager.get_dialog(reply_message_full_id.get_dialog_id())
        } else {
            Some(d)
        };
        let Some(reply_d) = reply_d else {
            // replied message isn't loaded yet
            return;
        };
        match get_message_in_dialog(reply_d, reply_message_id) {
            Some(replied_m) => {
                new_max_reply_media_timestamp = get_message_own_max_media_timestamp(ctx, replied_m);
            }
            None => {
                if !is_deleted_message(reply_d, reply_message_id)
                    && reply_message_id > reply_d.last_clear_history_message_id
                    && reply_message_id > reply_d.max_unavailable_message_id
                {
                    // replied message isn't deleted and isn't loaded yet
                    return;
                }
            }
        }
    } else if m.reply_to_story_full_id != StoryFullId::default() {
        if !ctx.have_story(m.reply_to_story_full_id) {
            if !ctx.is_inaccessible_story(m.reply_to_story_full_id) {
                // replied story isn't loaded yet
                return;
            }
        } else {
            new_max_reply_media_timestamp = ctx.get_story_duration(m.reply_to_story_full_id);
        }
    }

    if m.max_reply_media_timestamp == new_max_reply_media_timestamp {
        return;
    }

    let old_max_media_timestamp = get_message_max_media_timestamp(m);
    m.max_reply_media_timestamp = new_max_reply_media_timestamp;
    let new_max_media_timestamp = get_message_max_media_timestamp(m);
    if need_send_update_message_content && old_max_media_timestamp != new_max_media_timestamp {
        // the swap + has_media_timestamps range check +
        // send_update_message_content_impl emission (24005-24012)
        tracing::info!(
            "update_message_max_reply_media_timestamp seam: updateMessageContent emission for {} in {:?} is the M.10.9 update plane",
            DisplayMessageId(m.message_id),
            d.dialog_id
        );
    }
}

fn set_message_reply(
    manager: &MessagesManager,
    ctx: &dyn SendMessageContext,
    dialog_id: DialogId,
    m: &mut Message,
    input_reply_to: MessageInputReplyTo,
    is_message_in_dialog: bool,
) {
    tracing::info!(
        "Update replied message of {}:{}",
        dialog_id.get(),
        DisplayMessageId(m.message_id)
    );
    if is_message_in_dialog {
        // `unregister_message_reply` (35827) — the M.10.9 container seam
    }
    m.replied_message_info = replied_message_info_from_input_reply_to(
        ctx,
        dialog_id,
        &input_reply_to,
        &get_message_topic(ctx, dialog_id, m),
    );
    m.reply_to_story_full_id = StoryFullId::default();
    let d = manager.get_dialog(dialog_id);
    m.reply_to_random_id = d.map_or(0, |d| get_message_reply_to_random_id(d, m));
    if !m.message_id.is_any_server() {
        m.input_reply_to = input_reply_to;
    }
    if is_message_in_dialog {
        // `register_message_reply` (35836) — the same seam
    }
    if let Some(d) = manager.get_dialog(dialog_id) {
        update_message_max_reply_media_timestamp(manager, ctx, d, m, is_message_in_dialog);
    }
}

/// `MessagesManager::restore_message_reply_to_message_id`
/// (MessagesManager.cpp:35857-35880) — the crash-replay reply repair: a
/// replied-to yet-unsent id is rewritten to its persisted form, or the reply
/// resets to the implicit topic reply.
pub fn restore_message_reply_to_message_id(
    manager: &MessagesManager,
    ctx: &dyn SendMessageContext,
    dialog_id: DialogId,
    m: &mut Message,
) {
    let input_reply_to_is_empty = get_message_input_reply_to(m).is_empty();
    if input_reply_to_is_empty {
        return;
    }
    let replied_message_full_id =
        get_message_input_reply_to(m).get_reply_message_full_id(dialog_id);
    let replied_message_id = replied_message_full_id.get_message_id();
    if replied_message_id == MessageId::default() || !replied_message_id.is_yet_unsent() {
        return;
    }
    assert!(replied_message_full_id.get_dialog_id() == dialog_id);
    let log_check_reply_full_id = m
        .replied_message_info
        .get_reply_message_full_id(dialog_id, true);
    assert!(
        log_check_reply_full_id == replied_message_full_id,
        "restore_message_reply_to_message_id reply mismatch: {replied_message_full_id:?} vs {log_check_reply_full_id:?}"
    );
    let message_id = {
        let d = manager.get_dialog(dialog_id).unwrap();
        get_message_id_by_random_id(
            ctx,
            d,
            m.reply_to_random_id,
            "restore_message_reply_to_message_id",
        )
    };
    if (message_id.is_valid() || message_id.is_valid_scheduled())
        && !message_id.is_local()
        && (is_message_forward(m) || !message_id.is_yet_unsent())
    {
        let d = manager.get_dialog(dialog_id).unwrap();
        update_message_reply_to_message_id(d, m, message_id, "restore_message_reply_to_message_id");
    } else {
        let implicit_reply_to_message_id =
            get_message_topic(ctx, dialog_id, m).get_implicit_reply_to_message_id(ctx);
        assert!(
            implicit_reply_to_message_id == MessageId::default()
                || implicit_reply_to_message_id.is_server()
        );
        set_message_reply(
            manager,
            ctx,
            dialog_id,
            m,
            MessageInputReplyTo::regular(implicit_reply_to_message_id),
            false,
        );
    }
}

/// `MessagesManager::do_send_message` (MessagesManager.cpp:22023-22191) —
/// the wire/files plane: the messages.sendMessage query, the upload
/// scheduling, the secret-media encryption. It is M.10.9's
/// `on_message_sent` flip (net + Files owners); M.10.8 trace-logs the call.
pub fn do_send_message(
    manager: &mut MessagesManager,
    ctx: &dyn SendMessageContext,
    dialog_id: DialogId,
    message_id: MessageId,
    media_pos: i32,
    bad_parts: Vec<i32>,
) -> DoSendAction {
    let (media_album_id, edit_generation, content) = {
        let Some(m) = manager
            .get_dialog(dialog_id)
            .and_then(|d| d.messages.get(&message_id))
        else {
            return DoSendAction::None;
        };
        (
            m.media_album_id,
            m.edit_generation,
            m.content.clone().expect("message without content"),
        )
    };
    let m = Message {
        media_album_id,
        edit_generation,
        content: Some(content),
        message_id,
        ..Message::default()
    };
    let is_edit = m.message_id.is_any_server();
    let is_secret = dialog_id.get_type() == DialogType::SecretChat;

    // the album fan-in registration
    if m.media_album_id != 0 && bad_parts.is_empty() && !is_secret && !is_edit {
        let media_album_id = m.media_album_id;
        let request = manager
            .pending_message_group_sends
            .entry(media_album_id)
            .or_default();
        if !request.message_ids.contains(&m.message_id) {
            request.dialog_id = dialog_id;
            request.message_ids.push(m.message_id);
            request.is_finished.push(false);
            request.results.push(Ok(()));
        }
    }

    // the edit plane (`edited_messages_` reads) rides the M.10.5 wiring
    // ([blocked: M.10.20])
    let content = m.content.as_ref().expect("message without content");
    let content_type = content.get_type();
    if content_type == crate::message_content::MessageContentType::Text {
        assert!(!is_edit);
        // `on_text_message_ready_to_send` — the text wire send
        return DoSendAction::TextReady;
    }

    if !is_secret {
        // `get_message_content_need_to_upload_covers` +
        // `upload_message_covers` — the covers upload (the
        // MessageQueryManager seam; [blocked: M.12/net])
    }

    if bad_parts.is_empty() {
        let file_ids = crate::message_content::get_message_content_any_file_ids(
            ctx.content_context(),
            content,
        );
        // `get_message_content_thumbnail_file_ids` — [blocked: M.12]: the
        // per-document-manager thumbnail reads; the photo-class thumbnail
        // clear rides the same FileView seam
        let file_upload_ids: Vec<FileUploadId> = file_ids
            .iter()
            .map(|&file_id| FileUploadId::new(file_id, 0))
            .collect();
        if !is_edit {
            let upload_ids = file_upload_ids.clone();
            if let Some(stored) = manager
                .get_dialog_mut(dialog_id)
                .and_then(|d| d.messages.get_mut(&message_id))
            {
                stored.file_upload_ids = upload_ids;
            }
        }
        if is_secret {
            // the secret-chat upload arm — `get_message_content_secret_input_media`
            // and the encrypted resume_upload are the SecretChats/M.12 seams
            return DoSendAction::SecretUpload {
                file_upload_id: file_upload_ids.first().copied().unwrap_or_default(),
            };
        }
        let can_have_multiple_files =
            crate::message_content::can_message_content_have_multiple_files(content_type);
        // `get_message_content_input_media(...).is_empty()` — the
        // FileView remote-location read is the M.12 seam; the port always
        // takes the upload path (the conservative arm)
        let input_media_is_empty = true;
        if input_media_is_empty
            || media_pos >= 0
            || !bad_parts.is_empty()
            || can_have_multiple_files
        {
            if content_type == crate::message_content::MessageContentType::Game
                || content_type == crate::message_content::MessageContentType::Story
            {
                return DoSendAction::None;
            }
            if can_have_multiple_files && bad_parts.is_empty() {
                debug_assert_eq!(media_pos, -1);
                let request = manager
                    .pending_internal_media_sends
                    .entry(MessageFullId::new(dialog_id, message_id))
                    .or_default();
                assert!(request.is_finished.is_empty());
                request.is_finished.resize(file_upload_ids.len(), false);
                request
                    .results
                    .resize_with(file_upload_ids.len(), || Ok(()));
            }
            for (i, &file_upload_id) in file_upload_ids.iter().enumerate() {
                if media_pos >= 0 && media_pos as usize != i {
                    continue;
                }
                let is_inserted = manager
                    .being_uploaded_files
                    .insert(
                        file_upload_id,
                        UploadedFileInfo {
                            message_full_id: MessageFullId::new(dialog_id, message_id),
                            media_pos: if can_have_multiple_files {
                                i as i32
                            } else {
                                -1
                            },
                            edit_generation: m.edit_generation,
                        },
                    )
                    .is_none();
                assert!(is_inserted);
                // `td_->file_manager_->resume_upload(...)` — the M.12 seam
            }
            if can_have_multiple_files && file_upload_ids.is_empty() {
                return DoSendAction::InternalMediaGroup;
            }
            return DoSendAction::UploadFiles {
                file_upload_ids,
                media_pos,
            };
        }
        return DoSendAction::MediaReady;
    }
    DoSendAction::UploadFiles {
        file_upload_ids: Vec::new(),
        media_pos,
    }
}

/// The `do_send_message` upload decision (the C++ void fn's observable
/// effects) — every variant's wire leg is the net/M.12 seam.
#[derive(Clone, Debug, PartialEq)]
pub enum DoSendAction {
    /// `on_text_message_ready_to_send` — the text wire send.
    TextReady,
    /// `upload_message_covers` — the covers upload (recorded above).
    UploadCovers,
    /// `resume_upload` per file — the registry inserts happened.
    UploadFiles {
        file_upload_ids: Vec<FileUploadId>,
        media_pos: i32,
    },
    /// the secret-chat upload arm.
    SecretUpload { file_upload_id: FileUploadId },
    /// `on_message_media_uploaded` with a ready input media.
    MediaReady,
    /// `do_send_internal_media_group` directly (no files to upload).
    InternalMediaGroup,
    /// nothing to do (Game/Story contents, missing dialogs).
    None,
}

/// `MessageTopic::get_message_topic` (MessageTopic.cpp:138-207) — the
/// td_api-object overload (the message form lives at
/// [`MessageTopic::new_from_message`]).
pub fn get_message_topic_from_td_api(
    ctx: &dyn MessageObjectContext,
    dialog_id: DialogId,
    topic: Option<&td_api::MessageTopic>,
) -> Result<MessageTopic, (i32, String)> {
    let Some(topic) = topic else {
        return Ok(MessageTopic::default());
    };
    if !ctx.have_dialog(dialog_id) {
        // `have_dialog_force` — the registry form
        return Err((400, "Chat not found".to_owned()));
    }
    let mut result = MessageTopic::default();
    match topic {
        td_api::MessageTopic::messageTopicThread(state) => {
            let top_thread_message_id = MessageId::new(state.message_thread_id);
            if dialog_id.get_type() != DialogType::Channel
                || !ctx.is_megagroup_channel(dialog_id.get_channel_id())
                || ctx
                    .content_context()
                    .is_monoforum_channel(dialog_id.get_channel_id())
            {
                return Err((400, "Chat doesn't have threads".to_owned()));
            }
            if !top_thread_message_id.is_server() {
                return Err((
                    400,
                    "Invalid message thread identifier specified".to_owned(),
                ));
            }
            result.r#type = MessageTopicType::Thread;
            result.dialog_id = dialog_id;
            result.top_thread_message_id = top_thread_message_id;
        }
        td_api::MessageTopic::messageTopicForum(state) => {
            let forum_topic_id = ForumTopicId::from_raw(state.forum_topic_id);
            if !forum_topic_id.is_valid() {
                return Err((400, "Invalid topic identifier specified".to_owned()));
            }
            if !can_be_forum(ctx, dialog_id) {
                return Err((400, "Chat is not a forum".to_owned()));
            }
            result.r#type = MessageTopicType::Forum;
            result.dialog_id = dialog_id;
            result.forum_topic_id = forum_topic_id;
        }
        td_api::MessageTopic::messageTopicDirectMessages(state) => {
            if !ctx.is_admined_monoforum_channel(dialog_id) {
                return Err((
                    400,
                    "Chat is not an administered channel direct messages chat".to_owned(),
                ));
            }
            // `SavedMessagesManager::get_topic_id` — the id parse; the
            // m10.4 readers answer raw ids
            let saved_messages_topic_id =
                SavedMessagesTopicId::new(DialogId::new(state.direct_messages_chat_topic_id));
            if !saved_messages_topic_id.is_valid() {
                return Err((400, "Topic not found".to_owned()));
            }
            result.r#type = MessageTopicType::Monoforum;
            result.dialog_id = dialog_id;
            result.saved_messages_topic_id = saved_messages_topic_id;
        }
        td_api::MessageTopic::messageTopicSavedMessages(state) => {
            if dialog_id != ctx.content_context().get_my_dialog_id() {
                return Err((400, "Chat is not the Saved Messages chat".to_owned()));
            }
            let saved_messages_topic_id =
                SavedMessagesTopicId::new(DialogId::new(state.saved_messages_topic_id));
            if !saved_messages_topic_id.is_valid() {
                return Err((400, "Topic not found".to_owned()));
            }
            result.r#type = MessageTopicType::SavedMessages;
            result.dialog_id = dialog_id;
            result.saved_messages_topic_id = saved_messages_topic_id;
        }
    }
    Ok(result)
}

/// `MessageTopic::get_send_message_topic(td, dialog_id, topic_id)`
/// (MessageTopic.cpp:210-214).
pub fn get_send_message_topic(
    ctx: &dyn MessageObjectContext,
    dialog_id: DialogId,
    topic_id: Option<&td_api::MessageTopic>,
) -> Result<MessageTopic, (i32, String)> {
    let message_topic = get_message_topic_from_td_api(ctx, dialog_id, topic_id)?;
    get_send_message_topic_parsed(ctx, dialog_id, message_topic)
}

/// `MessageTopic::get_send_message_topic(td, dialog_id, MessageTopic &&)`
/// (MessageTopic.cpp:216-231).
pub fn get_send_message_topic_parsed(
    ctx: &dyn MessageObjectContext,
    dialog_id: DialogId,
    message_topic: MessageTopic,
) -> Result<MessageTopic, (i32, String)> {
    // topic is required in administered direct messages chats
    if ctx.is_admined_monoforum_channel(dialog_id) && !message_topic.is_monoforum() {
        return Err((
            400,
            "Channel direct messages topic must be specified".to_owned(),
        ));
    }

    // in other chats the topic can be specified implicitly
    if message_topic.is_empty() {
        return Ok(MessageTopic::default());
    }

    if message_topic.is_saved_messages() {
        return Err((
            400,
            "Messages can't be explicitly sent to a Saved Messages topic".to_owned(),
        ));
    }

    Ok(message_topic)
}

/// `MessagesManager::process_input_message_content`
/// (MessagesManager.cpp:21813-21879) — the non-copy arm is complete; the
/// `inputMessageForwarded` copy leg rides the M.10.11 copy plane (the
/// validation gates are live).
pub fn process_input_message_content(
    ctx: &mut dyn SendMessageContext,
    // the copy arm's dialog/message reads land with the M.10.11 copy plane
    _manager: &MessagesManager,
    dialog_id: DialogId,
    input_message_content: Option<td_api::InputMessageContent>,
    check_permissions: bool,
) -> Result<crate::message_content::InputMessageContent, (i32, String)> {
    assert!(dialog_id.is_valid());
    if let Some(td_api::InputMessageContent::inputMessageForwarded(input_message)) =
        input_message_content
    {
        // for sendMessageAlbum/editMessageMedia/addLocalMessage
        let _ = input_message;
        // `MessageCopyOptions::get_message_copy_options` gates
        // (!send_copy → "Can't use forwarded message",
        // replace_video_start_timestamp → the error) + the copy walk —
        // the M.10.11 copy plane ([blocked: M.10.20])
        return Err((
            500,
            "The forwarded-content copy arm lands with the M.10.20 wiring".to_owned(),
        ));
    }
    let is_premium = ctx.is_premium();
    let content = crate::message_content::get_input_message_content(
        ctx.content_context_mut(),
        dialog_id,
        input_message_content.expect("message content must be non-null"),
        is_premium,
    )
    .map_err(|status| (status.code(), status.message().to_owned()))?;
    crate::message_content::can_send_message_content(
        ctx.content_context(),
        dialog_id,
        &content.content,
        false,
        check_permissions,
    )
    .map_err(|status| (status.code(), status.message().to_owned()))?;
    Ok(content)
}

/// `MessagesManager::send_message_group` (MessagesManager.cpp:21896-21978)
/// — the album send path: options, the M.9.5 group-content splat gate, the
/// album id and the per-message send loop.
#[allow(clippy::too_many_arguments)]
pub fn send_message_group(
    global: &mut crate::global::Global,
    manager: &mut MessagesManager,
    reactions_ctx: &dyn DialogReactionsContext,
    ctx: &mut dyn SendMessageContext,
    state: &mut dyn ReadStateContext,
    dialog_id: DialogId,
    topic_id: Option<td_api::MessageTopic>,
    reply_to: Option<td_api::InputMessageReplyTo>,
    options: Option<td_api::MessageSendOptions>,
    input_message_contents: Vec<Option<td_api::InputMessageContent>>,
) -> Result<td_api::Messages, (i32, String)> {
    if manager.get_dialog(dialog_id).is_none() {
        // `get_dialog_force` + the bot paid-broadcast force-create — the
        // DialogManager info seam
        if ctx.is_bot()
            && options
                .as_ref()
                .is_some_and(|options| options.allow_paid_broadcast)
            && dialog_id.get_type() == DialogType::User
        {
            // `force_create_dialog` — the M.10.20 wiring
        }
        return Err((400, "Chat not found".to_owned()));
    }

    if input_message_contents.is_empty() {
        return Err((400, "There are no messages to send".to_owned()));
    }

    can_send_message(ctx, dialog_id)?;

    let message_send_options = MessageSendOptions::get_message_send_options(
        ctx,
        dialog_id,
        options,
        true,
        true,
        false,
        false,
        input_message_contents.len() as i32,
    )?;

    let mut message_contents: Vec<crate::message_content::InputMessageContent> = Vec::new();
    for input_message_content in input_message_contents {
        let message_content = process_input_message_content(
            ctx,
            manager,
            dialog_id,
            input_message_content,
            !message_send_options.allow_paid,
        )?;
        message_send_options
            .can_use_for_input(&message_content)
            .map_err(|status| (status.0, status.1))?;
        message_contents.push(message_content);
    }
    crate::message_content::check_message_group_message_contents(&message_contents)
        .map_err(|status| (status.code(), status.message().to_owned()))?;

    let topic_id_ref = topic_id.as_ref();
    let message_topic = get_send_message_topic(ctx, dialog_id, topic_id_ref)?;
    let input_reply_to =
        create_message_input_reply_to(ctx, manager, dialog_id, &message_topic, reply_to, false);

    let media_album_id = if message_contents.len() > 1 {
        generate_new_media_album_id(manager)
    } else {
        0
    };

    // there must be no errors after get_message_to_send calls

    let mut result: Vec<Option<td_api::Message>> = Vec::new();
    let mut need_update_dialog_pos = false;
    for (i, message_content) in message_contents.into_iter().enumerate() {
        let ttl = message_content.ttl;
        let invert_media = message_content.invert_media;
        let content = *message_content.content;
        let message_full_id = get_message_to_send(
            ctx,
            global,
            manager,
            reactions_ctx,
            state,
            dialog_id,
            &message_topic,
            input_reply_to.clone(),
            &message_send_options,
            content,
            invert_media,
            &mut need_update_dialog_pos,
            i != 0,
            None,
            DialogId::default(),
            false,
            DialogId::default(),
            false,
        );
        let message_id = message_full_id.get_message_id();

        // take/put-back dance: the object/update builders borrow the
        // manager while mutating the message
        let mut m = manager
            .get_dialog_mut(dialog_id)
            .and_then(|d| d.messages.remove(&message_id))
            .expect("get_message_to_send inserted the message");
        if ttl.is_valid() {
            m.ttl = ttl;
            m.is_content_secret =
                ttl.is_secret_message_content(m.content.as_ref().expect("content").get_type());
        }
        m.media_album_id = media_album_id;
        let obj_ctx: &dyn MessageObjectContext = ctx;
        let message_object = get_message_object(
            manager,
            reactions_ctx,
            obj_ctx,
            dialog_id,
            &mut m,
            "send_message_group",
        );
        result.push(message_object);

        if !message_send_options.only_preview {
            save_send_message_log_event(global, dialog_id, &mut m);
            manager
                .get_dialog_mut(dialog_id)
                .and_then(|d| d.messages.insert(message_id, m))
                .expect("get_message_to_send inserted the message");
            do_send_message(manager, ctx, dialog_id, message_id, -1, Vec::new());

            if !ctx.is_bot() {
                let mut m = manager
                    .get_dialog_mut(dialog_id)
                    .and_then(|d| d.messages.remove(&message_id))
                    .expect("get_message_to_send inserted the message");
                send_update_new_message(manager, ctx, state, reactions_ctx, dialog_id, &mut m);
                manager
                    .get_dialog_mut(dialog_id)
                    .and_then(|d| d.messages.insert(message_id, m))
                    .expect("get_message_to_send inserted the message");
            }
        } else {
            manager
                .get_dialog_mut(dialog_id)
                .and_then(|d| d.messages.insert(message_id, m))
                .expect("get_message_to_send inserted the message");
        }
    }

    if need_update_dialog_pos {
        assert!(!message_send_options.only_preview);
        send_update_chat_last_message(
            manager,
            ctx,
            state,
            reactions_ctx,
            dialog_id,
            "send_message_group",
        );
    }

    Ok(get_messages_object(-1, result, false))
}

/// `MessagesManager::send_message` (MessagesManager.cpp:21721-21868) — the
/// single-message send entry behind the `sendMessage` arm: the topic/reply
/// plumbing, the reply-markup conversion, `get_message_to_send`, the draft
/// clear, the durable send log event and the wire kick. The
/// `inputMessageForwarded` arm routes to `forward_message` in the C++ — the
/// M.10.11 forward plane ([blocked: the forwardMessages flip]).
#[allow(clippy::too_many_arguments)]
pub fn send_message(
    global: &mut crate::global::Global,
    manager: &mut MessagesManager,
    reactions_ctx: &dyn DialogReactionsContext,
    ctx: &mut dyn SendMessageContext,
    state: &mut dyn ReadStateContext,
    dialog_id: DialogId,
    topic_id: Option<td_api::MessageTopic>,
    reply_to: Option<td_api::InputMessageReplyTo>,
    options: Option<td_api::MessageSendOptions>,
    reply_markup: Option<td_api::ReplyMarkup>,
    input_message_content: Option<td_api::InputMessageContent>,
) -> Result<td_api::Message, (i32, String)> {
    let Some(input_message_content) = input_message_content else {
        return Err((400, "Can't send message without content".to_owned()));
    };

    if manager.get_dialog(dialog_id).is_none() {
        // `get_dialog_force` + the bot paid-broadcast force-create — the
        // DialogManager info seam (as send_message_group)
        if ctx.is_bot()
            && options
                .as_ref()
                .is_some_and(|options| options.allow_paid_broadcast)
            && dialog_id.get_type() == DialogType::User
        {
            // `force_create_dialog` — the M.10.20 wiring
        }
        return Err((400, "Chat not found".to_owned()));
    }

    let message_topic = get_send_message_topic(ctx, dialog_id, topic_id.as_ref())?;
    let input_reply_to =
        create_message_input_reply_to(ctx, manager, dialog_id, &message_topic, reply_to, false);

    if matches!(
        input_message_content,
        td_api::InputMessageContent::inputMessageForwarded(_)
    ) {
        // forward_message (MessagesManager.cpp:21749-21760) — the
        // M.10.11 forward plane owns the flip
        return Err((
            500,
            "The forwarded send arm lands with the M.10.11 forward plane".to_owned(),
        ));
    }

    can_send_message(ctx, dialog_id)?;
    let message_reply_markup = get_dialog_reply_markup(ctx, dialog_id, reply_markup)?;
    let message_send_options = MessageSendOptions::get_message_send_options(
        ctx, dialog_id, options, true, true, true, true, 1,
    )?;
    let message_content = process_input_message_content(
        ctx,
        manager,
        dialog_id,
        Some(input_message_content),
        !message_send_options.allow_paid,
    )?;
    message_send_options
        .can_use_for_input(&message_content)
        .map_err(|status| (status.0, status.1))?;

    // there must be no errors after the get_message_to_send call

    let ttl = message_content.ttl;
    let invert_media = message_content.invert_media;
    let content = *message_content.content;
    let mut need_update_dialog_pos = false;
    let message_full_id = get_message_to_send(
        ctx,
        global,
        manager,
        reactions_ctx,
        state,
        dialog_id,
        &message_topic,
        input_reply_to,
        &message_send_options,
        content,
        invert_media,
        &mut need_update_dialog_pos,
        false,
        None,
        DialogId::default(),
        message_content.via_bot_user_id.is_valid(),
        DialogId::default(),
        false,
    );
    let message_id = message_full_id.get_message_id();

    // take/put-back dance: the reply-markup assignment, the object/update
    // builders and the log-event writer borrow the manager while mutating
    // the message
    let mut m = manager
        .get_dialog_mut(dialog_id)
        .and_then(|d| d.messages.remove(&message_id))
        .expect("get_message_to_send inserted the message");
    m.reply_markup = message_reply_markup.map(Box::new);
    m.via_bot_user_id = message_content.via_bot_user_id;
    m.disable_web_page_preview = message_content.disable_web_page_preview;
    m.clear_draft = message_content.clear_draft;
    if ttl.is_valid() {
        m.ttl = ttl;
        m.is_content_secret =
            ttl.is_secret_message_content(m.content.as_ref().expect("content").get_type());
    }
    m.send_emoji = message_content.emoji;

    if message_send_options.only_preview {
        let obj_ctx: &dyn MessageObjectContext = ctx;
        let message_object = get_message_object(
            manager,
            reactions_ctx,
            obj_ctx,
            dialog_id,
            &mut m,
            "send_message",
        );
        manager
            .get_dialog_mut(dialog_id)
            .and_then(|d| d.messages.insert(message_id, m))
            .expect("get_message_to_send inserted the message");
        return message_object.ok_or_else(|| (500, "Can't send message".to_owned()));
    }

    let obj_ctx: &dyn MessageObjectContext = ctx;
    clear_dialog_draft_by_sent_message(
        manager,
        obj_ctx,
        state,
        dialog_id,
        &m,
        !need_update_dialog_pos,
    );

    save_send_message_log_event(global, dialog_id, &mut m);
    manager
        .get_dialog_mut(dialog_id)
        .and_then(|d| d.messages.insert(message_id, m))
        .expect("get_message_to_send inserted the message");
    let send_action = do_send_message(manager, ctx, dialog_id, message_id, -1, Vec::new());
    if send_action == DoSendAction::TextReady {
        // `on_text_message_ready_to_send` — the text wire send (the
        // C++ DoSendAction switch); the upload/media actions keep their
        // M.12/net seams in do_send_message.
        on_text_message_ready_to_send(manager, ctx, dialog_id, message_id);
    }

    if !ctx.is_bot() {
        let mut m = manager
            .get_dialog_mut(dialog_id)
            .and_then(|d| d.messages.remove(&message_id))
            .expect("get_message_to_send inserted the message");
        send_update_new_message(manager, ctx, state, reactions_ctx, dialog_id, &mut m);
        manager
            .get_dialog_mut(dialog_id)
            .and_then(|d| d.messages.insert(message_id, m))
            .expect("get_message_to_send inserted the message");

        if need_update_dialog_pos {
            send_update_chat_last_message(
                manager,
                ctx,
                state,
                reactions_ctx,
                dialog_id,
                "send_message",
            );
        }
    }

    let mut m = manager
        .get_dialog_mut(dialog_id)
        .and_then(|d| d.messages.remove(&message_id))
        .expect("get_message_to_send inserted the message");
    let obj_ctx: &dyn MessageObjectContext = ctx;
    let message_object = get_message_object(
        manager,
        reactions_ctx,
        obj_ctx,
        dialog_id,
        &mut m,
        "send_message",
    );
    manager
        .get_dialog_mut(dialog_id)
        .and_then(|d| d.messages.insert(message_id, m))
        .expect("get_message_to_send inserted the message");
    message_object.ok_or_else(|| (500, "Can't send message".to_owned()))
}

/// `MessagesManager::on_message_media_uploaded`
/// (MessagesManager.cpp:22198-22230) — the album/single dispatch head.
pub fn on_message_media_uploaded(
    manager: &mut MessagesManager,
    ctx: &dyn SendMessageContext,
    dialog_id: DialogId,
    message_id: MessageId,
    media_pos: i32,
) -> MediaUploadedAction {
    let Some(m) = manager
        .get_dialog(dialog_id)
        .and_then(|d| d.messages.get(&message_id))
    else {
        panic!("on_message_media_uploaded without the message");
    };
    let is_edit = message_id.is_any_server();
    if (!is_edit && m.media_album_id != 0) || media_pos != -1 {
        // `get_message_content_input_media` + `is_uploaded_input_media` —
        // the ready-input decision is the M.9/M.12 file-view seam; the
        // port always routes through the UploadMediaQuery leg
        let _ = ctx;
        return MediaUploadedAction::UploadMedia {
            media_album_id: m.media_album_id,
            media_pos,
        };
    }
    MediaUploadedAction::DirectSend
}

/// The `on_message_media_uploaded` dispatch (the C++ void fn's observable
/// effects).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum MediaUploadedAction {
    /// `UploadMediaQuery` — the net seam.
    UploadMedia { media_album_id: i64, media_pos: i32 },
    /// `do_send_message_media` — the single-message wire send (net seam).
    DirectSend,
}

/// `MessagesManager::generate_new_media_album_id`
/// (MessagesManager.cpp:21883-21889).
pub fn generate_new_media_album_id(mm: &MessagesManager) -> i64 {
    loop {
        let media_album_id = tdutils::random::secure_int64();
        if media_album_id < 0 && !mm.pending_message_group_sends.contains_key(&media_album_id) {
            return media_album_id;
        }
    }
}

/// `MessagesManager::on_upload_message_media_file_error`
/// (MessagesManager.cpp:22435-22458) — the retry re-entry.
pub fn on_upload_message_media_file_error(
    manager: &mut MessagesManager,
    ctx: &dyn SendMessageContext,
    dialog_id: DialogId,
    message_id: MessageId,
    media_pos: i32,
    edit_generation: u64,
    bad_parts: Vec<i32>,
) -> DoSendAction {
    let Some(m) = manager
        .get_dialog(dialog_id)
        .and_then(|d| d.messages.get(&message_id))
    else {
        // the message has already been deleted by the user or sent to an
        // inaccessible chat
        return DoSendAction::None;
    };
    let is_edit = message_id.is_any_server();
    if is_edit && m.edit_generation != edit_generation {
        return DoSendAction::None;
    }
    if !ctx.have_input_peer_read(dialog_id, true) {
        // the message should be deleted soon
        return DoSendAction::None;
    }
    assert!(dialog_id.get_type() != DialogType::SecretChat);
    do_send_message(manager, ctx, dialog_id, message_id, media_pos, bad_parts)
}

/// `MessagesManager::on_upload_message_media_fail`
/// (MessagesManager.cpp:22460-22484) — the failure fan-in.
pub fn on_upload_message_media_fail(
    manager: &mut MessagesManager,
    ctx: &dyn SendMessageContext,
    dialog_id: DialogId,
    message_id: MessageId,
    media_pos: i32,
    edit_generation: u64,
    error: (i32, String),
) -> UploadFinishedAction {
    let Some(m) = manager
        .get_dialog(dialog_id)
        .and_then(|d| d.messages.get(&message_id))
    else {
        return UploadFinishedAction::None;
    };
    let is_edit = message_id.is_any_server();
    if is_edit && m.edit_generation != edit_generation {
        return UploadFinishedAction::None;
    }
    if !ctx.have_input_peer_read(dialog_id, true) {
        return UploadFinishedAction::None;
    }
    assert!(dialog_id.get_type() != DialogType::SecretChat);
    let media_album_id = m.media_album_id;
    on_upload_message_media_finished(
        manager,
        media_album_id,
        dialog_id,
        message_id,
        media_pos,
        edit_generation,
        Err(error),
    )
}

/// The `on_upload_message_media_finished` outcome.
#[derive(Clone, Debug, PartialEq)]
pub enum UploadFinishedAction {
    /// nothing to do (unknown group, duplicate completion, generation
    /// mismatch).
    None,
    /// `do_send_internal_media_group` for the message.
    InternalMediaGroup,
    /// the album completed (or failed early) — `do_send_message_group`.
    Group(i64),
}

/// `MessagesManager::on_upload_message_media_finished`
/// (MessagesManager.cpp:22486-22578) — the upload fan-in state machine over
/// both pending tables.
pub fn on_upload_message_media_finished(
    manager: &mut MessagesManager,
    media_album_id: i64,
    dialog_id: DialogId,
    message_id: MessageId,
    media_pos: i32,
    edit_generation: u64,
    result: Result<(), (i32, String)>,
) -> UploadFinishedAction {
    let message_full_id = MessageFullId::new(dialog_id, message_id);
    if media_pos >= 0 {
        assert_eq!(media_album_id, 0);
        if !manager
            .pending_internal_media_sends
            .contains_key(&message_full_id)
        {
            // the message may be already sent or failed to be sent
            return UploadFinishedAction::None;
        }
        let is_edit = message_id.is_any_server();
        let generation_matches = manager
            .get_dialog(dialog_id)
            .and_then(|d| d.messages.get(&message_id))
            .is_some_and(|m| !is_edit || m.edit_generation == edit_generation);
        if !generation_matches {
            // the message edit generation doesn't match
            return UploadFinishedAction::None;
        }
        let request = manager
            .pending_internal_media_sends
            .get_mut(&message_full_id)
            .unwrap();
        debug_assert!((media_pos as usize) < request.is_finished.len());
        if request.is_finished[media_pos as usize] {
            // already finished
            return UploadFinishedAction::None;
        }
        request.results[media_pos as usize] = result;
        request.is_finished[media_pos as usize] = true;
        request.finished_count += 1;

        if request.finished_count == request.results.len()
            || request.results[media_pos as usize].is_err()
        {
            return UploadFinishedAction::InternalMediaGroup;
        }
        return UploadFinishedAction::None;
    }
    assert!(media_album_id < 0);
    let Some(request) = manager.pending_message_group_sends.get_mut(&media_album_id) else {
        // the group may be already sent or failed to be sent
        return UploadFinishedAction::None;
    };
    assert!(request.dialog_id == dialog_id);
    let Some(pos) = request.message_ids.iter().position(|&id| id == message_id) else {
        // the message may be already deleted and the album recreated
        // without it
        assert!(message_id.is_yet_unsent());
        return UploadFinishedAction::None;
    };
    if request.is_finished[pos] {
        // already finished
        return UploadFinishedAction::None;
    }
    request.results[pos] = result;
    request.is_finished[pos] = true;
    request.finished_count += 1;

    if request.finished_count == request.results.len() || request.results[pos].is_err() {
        // the C++ ready-to-send promise chain collapses to the direct
        // group send (`on_media_message_ready_to_send` is the M.10.20
        // wiring point)
        return UploadFinishedAction::Group(media_album_id);
    }
    UploadFinishedAction::None
}

/// The `do_send_message_group` wire request record — the
/// `SendMultiMediaQuery` send is the net seam ([blocked: net]).
#[derive(Clone, Debug, Default, PartialEq)]
pub struct GroupSendWireRequest {
    pub dialog_id: DialogId,
    pub random_ids: Vec<i64>,
    pub message_count: usize,
    pub is_copy: bool,
    pub paid_message_star_count: i64,
}

/// The `do_send_message_group` outcome.
#[derive(Clone, Debug, PartialEq)]
pub enum GroupSendOutcome {
    /// the group completed — the wire request record.
    Sent(GroupSendWireRequest),
    /// nothing to do (unknown group).
    None,
    /// the group failed — `on_send_message_fail` fired per random id.
    Failed,
}

/// `begin_send_message` over the stored message — the
/// `do_send_message_group` walk form (the borrow-splitting twin of
/// [`begin_send_message`], same body).
fn begin_send_message_in_dialog(
    manager: &mut MessagesManager,
    dialog_id: DialogId,
    message_id: MessageId,
) -> i64 {
    let random_id = manager
        .get_dialog(dialog_id)
        .and_then(|d| d.messages.get(&message_id))
        .expect("begin_send_message_in_dialog: message gone")
        .random_id;
    assert!(random_id != 0);
    assert!(message_id.is_yet_unsent());
    let is_inserted = manager
        .being_sent_messages
        .insert(random_id, MessageFullId::new(dialog_id, message_id))
        .is_none();
    assert!(is_inserted);
    random_id
}

/// `MessagesManager::do_send_message_group` (MessagesManager.cpp:22580-22700)
/// — the album assembly: skip deleted messages, aggregate the results,
/// allocate the random ids and either fail every message or record the
/// `SendMultiMediaQuery`. The per-message inputSingleMedia assembly (the
/// input media + caption entities) and the wire send are the net/M.12
/// seams.
pub fn do_send_message_group(
    global: &mut crate::global::Global,
    manager: &mut MessagesManager,
    ctx: &mut dyn SendMessageContext,
    state: &mut dyn ReadStateContext,
    media_album_id: i64,
) -> GroupSendOutcome {
    assert!(media_album_id < 0);
    let Some(request) = manager.pending_message_group_sends.get(&media_album_id) else {
        // the group may be already sent or failed to be sent
        return GroupSendOutcome::None;
    };
    let dialog_id = request.dialog_id;
    let message_ids = request.message_ids.clone();
    let results = request.results.clone();
    let is_finished = request.is_finished.clone();

    let default_status = can_send_message(ctx, dialog_id);
    let mut success = default_status.is_ok();
    let mut random_ids: Vec<i64> = Vec::new();
    let mut is_copy = false;
    let mut paid_message_star_count = 0i64;
    for (i, &message_id) in message_ids.iter().enumerate() {
        let Some(m) = manager
            .get_dialog(dialog_id)
            .and_then(|d| d.messages.get(&message_id))
        else {
            // skip deleted messages
            random_ids.push(0);
            continue;
        };
        is_copy = m.is_copy;
        paid_message_star_count += m.paid_message_star_count;
        let message_id = m.message_id;

        let random_id = begin_send_message_in_dialog(manager, dialog_id, message_id);
        random_ids.push(random_id);

        if results[i].is_err() || !is_finished[i] {
            success = false;
        }
    }

    if !success {
        let default_error = default_status
            .err()
            .unwrap_or_else(|| (400, "Group send failed".to_owned()));
        for (i, &random_id) in random_ids.iter().enumerate() {
            if random_id != 0 {
                let error = results[i]
                    .clone()
                    .err()
                    .unwrap_or_else(|| default_error.clone());
                on_send_message_fail(global, manager, ctx, state, random_id, error.0, &error.1);
            }
        }
        manager.pending_message_group_sends.remove(&media_album_id);
        return GroupSendOutcome::Failed;
    }
    manager.pending_message_group_sends.remove(&media_album_id);

    // the SendMultiMediaQuery assembly (flags, reply/topic, per-message
    // inputSingleMedia) — the net seam
    GroupSendOutcome::Sent(GroupSendWireRequest {
        dialog_id,
        random_ids,
        message_count: message_ids.len(),
        is_copy,
        paid_message_star_count,
    })
}

/// `MessagesManager::continue_send_message` (MessagesManager.cpp:35882-35941)
/// — the durable-event continuation: re-allocate the id, repair the reply,
/// re-add the message and re-gate the send.
#[allow(clippy::too_many_arguments)]
pub fn continue_send_message(
    global: &mut crate::global::Global,
    manager: &mut MessagesManager,
    reactions_ctx: &dyn DialogReactionsContext,
    ctx: &mut dyn SendMessageContext,
    state: &mut dyn ReadStateContext,
    dialog_id: DialogId,
    mut message: Box<Message>,
    need_update_dialog_pos: &mut bool,
    log_event_id: u64,
) -> Option<MessageFullId> {
    assert!(log_event_id != 0);
    assert!(message.content.is_some());

    // `get_dialog_force(dialog_id, "continue_send_message")` — the db-load
    // leg is the dialog-db receive seam
    if manager.get_dialog(dialog_id).is_none() {
        log_error!("Can't find {dialog_id:?} to continue send a message");
        global.td_db().binlog().erase(log_event_id);
        return None;
    }
    if !ctx.have_input_peer_read(dialog_id, true) {
        global.td_db().binlog().erase(log_event_id);
        return None;
    }

    tracing::info!(
        "Continue to send {} to {:?} initially sent at {} from binlog",
        DisplayMessageId(message.message_id),
        dialog_id,
        message.send_date
    );

    {
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        d.was_opened = true;
    }

    let now = ctx.unix_time();
    {
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        if message.message_id.is_scheduled() {
            message.message_id = get_next_yet_unsent_scheduled_message_id(d, message.date);
        } else {
            message.message_id = get_next_yet_unsent_message_id(d, ctx.is_bot());
            message.date = now;
        }
    }

    {
        restore_message_reply_to_message_id(manager, ctx, dialog_id, &mut message);
    }

    let mut need_update = false;
    let result_full_id = add_message_to_dialog(
        global,
        manager,
        reactions_ctx,
        &*ctx,
        state,
        dialog_id,
        message,
        false,
        true,
        &mut need_update,
        need_update_dialog_pos,
        "continue_send_message",
    );
    let result_full_id = match result_full_id {
        Result::Ok(full_id) => full_id,
        Result::Err(fail_reason) => {
            panic!("CHECK failed in continue_send_message: {fail_reason}")
        }
    };

    let result_message = manager
        .get_dialog(dialog_id)
        .and_then(|d| get_message_in_dialog(d, result_full_id.get_message_id()))
        .map(|m| {
            (
                m.message_id.is_scheduled(),
                m.send_date,
                is_ephemeral_message(m),
            )
        });
    let (is_scheduled_result, send_date, result_is_ephemeral) =
        result_message.expect("continue_send_message lost the added message");
    if is_scheduled_result {
        // `send_update_chat_has_scheduled_messages` (35920) — the update
        // plane is the M.10.9 seam
        tracing::info!(
            "send_update_chat_has_scheduled_messages seam: {dialog_id:?} after continue_send_message"
        );
    }

    let mut can_send_status = if result_is_ephemeral {
        Result::Ok(())
    } else {
        ctx.can_send_message_to_dialog(dialog_id)
    };
    if can_send_status.is_ok()
        && send_date < now - MAX_RESEND_DELAY
        && dialog_id != DialogId::from_user_id(ctx.content_context().get_my_id())
    {
        can_send_status = Result::Err((
            400,
            "Message is too old to be re-sent automatically".to_string(),
        ));
    }
    if let Result::Err((error_code, error_message)) = &can_send_status {
        tracing::info!(
            "Can't continue to send a message to {dialog_id:?}: ({error_code}, {error_message})"
        );

        // `send_update_new_message` (35931) — the update plane is the M.10.9
        // seam; `fail_send_message` (35936) — the error/resend state machine
        // is M.10.9
        tracing::info!(
            "fail_send_message seam: {}:{} failed with ({error_code}, {error_message})",
            dialog_id.get(),
            DisplayMessageId(result_full_id.get_message_id())
        );
        return None;
    }

    Some(result_full_id)
}

/// `MAX_RESEND_DELAY` (MessagesManager.h:1702).
const MAX_RESEND_DELAY: i32 = 86400;

/// The `LogEvent::HandlerType::SendMessage` binlog replay arm
/// (MessagesManager.cpp:35951-35991) — `on_binlog_events`'s half-sent
/// recovery: erase when the binlog predates the dialog db, erase
/// Unsupported-content events with an error log, otherwise dup the content
/// for the Send direction and continue the send.
pub fn replay_send_message_log_event(
    global: &mut crate::global::Global,
    manager: &mut MessagesManager,
    reactions_ctx: &dyn DialogReactionsContext,
    ctx: &mut dyn SendMessageContext,
    event: &tddb::binlog::BinlogEvent,
) {
    // `have_old_message_database` (35947) — the binlog is older than the
    // dialog db only when the dialog db was never created
    let have_old_message_database =
        global.use_message_database() && !global.td_db().was_dialog_db_created();
    assert!(event.id != 0);
    if !have_old_message_database {
        global.td_db().binlog().erase(event.id);
        return;
    }

    let time = crate::user_manager::TimeCtx::from_global(global);
    let log_event =
        SendMessageLogEvent::parse_from_bytes(event.get_data(), &mut MessageDbStorageBridge, &time)
            .expect("corrupt SendMessageLogEvent in the binlog");

    let dialog_id = log_event.dialog_id;
    let mut message = log_event.message;
    message.send_message_log_event_id = event.id;

    if message
        .content
        .as_ref()
        .expect("message without content")
        .get_type()
        == MessageContentType::Unsupported
    {
        log_error!("Message content is invalid: {:?}", event.get_data());
        global.td_db().binlog().erase(event.id);
        return;
    }

    // `dependencies.add_dialog_dependencies/add_message_dependencies +
    // resolve_force` (35970-35973) — the dialog-db receive seam; the
    // in-memory skeleton stands in, like M.10.6's replay arm

    let content = message.content.as_ref().expect("message without content");
    message.content = crate::message_content::dup_message_content(
        ctx.content_context_mut(),
        dialog_id,
        content,
        crate::message_content_dup_type::MessageContentDupType::Send,
        false,
        crate::message_content::MessageCopyOptions::default(),
    );

    let mut need_update_dialog_pos = false;
    let mut state = NoReadStateContext;
    let result_full_id = continue_send_message(
        global,
        manager,
        reactions_ctx,
        ctx,
        &mut state,
        dialog_id,
        message,
        &mut need_update_dialog_pos,
        event.id,
    );
    if let Some(result_full_id) = result_full_id {
        // uses send_closure_later internally
        manager
            .get_dialog(dialog_id)
            .and_then(|d| get_message_in_dialog(d, result_full_id.get_message_id()))
            .expect("replayed message vanished");
        do_send_message(
            manager,
            ctx,
            dialog_id,
            result_full_id.get_message_id(),
            -1,
            Vec::new(),
        );
        // `send_update_new_message` (35984) — the update plane is the M.10.9
        // seam; the pos update (35985-35987) is the M.10.12 seam
        tracing::info!(
            "send_update_new_message seam: {dialog_id:?} replayed {}",
            DisplayMessageId(result_full_id.get_message_id())
        );
    }
}

// ---------------------------------------------------------------------------
// M.10.9 — the message containers + the receive/send-completion fan-out
// ---------------------------------------------------------------------------

/// The combined write plane the M.10.9+ slices drive: every read the
/// object/send contexts answer plus the `Td::send_update` delivery leg and
/// the read-state notification dialogs of [`ReadStateContext`]. `Td`
/// implements all three supertraits; the blanket impl carries it.
pub trait MessageManagerContext: ReadStateContext + SendMessageContext {}
impl<T: ReadStateContext + SendMessageContext> MessageManagerContext for T {}

/// `MessagesManager::get_message(const Dialog *, MessageId)`
/// (MessagesManager.cpp:30605-30637) — the container read with the
/// scheduled-date rewrite and the LRU access touch. The C++ returns a
/// mutable-or-const pointer; the Rust callers pick
/// [`get_message_in_dialog`] for the shared read or re-borrow the dialog
/// for the write paths.
pub fn get_message_touched(
    d: &mut Dialog,
    unix_time: i32,
    message_id: MessageId,
) -> Option<&Message> {
    if message_id.is_scheduled() {
        if let Some(scheduled_messages) = &d.scheduled_messages
            && message_id.is_valid_scheduled()
        {
            let mut rewritten = message_id;
            if message_id.is_scheduled_server() {
                let server_message_id = message_id.get_scheduled_server_message_id();
                if let Some(date) = scheduled_messages
                    .scheduled_message_date
                    .get(&server_message_id)
                {
                    rewritten = MessageId::from_scheduled(server_message_id, *date, false);
                    assert!(rewritten.is_scheduled_server());
                }
            }
            return scheduled_messages
                .scheduled_messages
                .get(&rewritten)
                .map(|m| m.as_ref());
        }
        None
    } else {
        if let Some(m) = d.messages.get(&message_id)
            && unix_time > m.last_access_date + 5
        {
            let last_access_date = &mut d.messages.get_mut(&message_id).unwrap().last_access_date;
            *last_access_date = unix_time;
            d.message_lru_list.touch(message_id);
        }
        d.messages.get(&message_id).map(|m| m.as_ref())
    }
}

/// `MessagesManager::get_message_static` (MessagesManager.cpp:30640).
pub fn get_message_static(d: &Dialog, message_id: MessageId) -> Option<&Message> {
    get_message_in_dialog(d, message_id)
}

/// `MessagesManager::have_message_force(Dialog *, MessageId, const char *)`
/// (MessagesManager.cpp:14632-14652) — the memory half; the message-db
/// load leg is the dialog-db receive seam.
pub fn have_message_in_dialog(
    manager: &MessagesManager,
    dialog_id: DialogId,
    message_id: MessageId,
) -> bool {
    match manager.get_dialog(dialog_id) {
        Some(d) => have_message_in_dialog_memory(d, message_id),
        None => false,
    }
}

/// The memory probe of `have_message_force`.
pub fn have_message_in_dialog_memory(d: &Dialog, message_id: MessageId) -> bool {
    if message_id.is_scheduled() {
        if !message_id.is_valid_scheduled() {
            return false;
        }
        let Some(scheduled_messages) = &d.scheduled_messages else {
            return false;
        };
        if message_id.is_scheduled_server() {
            // a scheduled server message must be found by the date-rewritten
            // id; an unknown date means the message is unknown
            let server_message_id = message_id.get_scheduled_server_message_id();
            match scheduled_messages
                .scheduled_message_date
                .get(&server_message_id)
            {
                Some(date) => scheduled_messages
                    .scheduled_messages
                    .contains_key(&MessageId::from_scheduled(server_message_id, *date, false)),
                None => false,
            }
        } else {
            scheduled_messages
                .scheduled_messages
                .contains_key(&message_id)
        }
    } else {
        d.messages.contains_key(&message_id)
    }
}

/// `MessagesManager::update_message_count_by_index(Dialog *, int, const
/// Message *)` (MessagesManager.cpp:4109-4119) — the per-message form.
pub fn update_message_count_by_index_message(
    manager: &mut MessagesManager,
    reactions_ctx: &dyn DialogReactionsContext,
    content_ctx: &dyn crate::message_content::MessageContentContext,
    dialog_id: DialogId,
    diff: i32,
    m: &Message,
) {
    let mut index_mask = get_message_index_mask(manager, reactions_ctx, content_ctx, dialog_id, m);
    index_mask &= !message_search_filter_index_mask(MessageSearchFilter::UnreadMention);
    index_mask &= !message_search_filter_index_mask(MessageSearchFilter::UnreadReaction);
    index_mask &= !message_search_filter_index_mask(MessageSearchFilter::UnreadPollVote);
    update_message_count_by_index_mask(manager, dialog_id, diff, index_mask);
}

/// `MessagesManager::update_message_count_by_index(Dialog *, int, int32)`
/// (MessagesManager.cpp:4121-4159) — the mask form with the calls-db tail.
pub fn update_message_count_by_index_mask(
    manager: &mut MessagesManager,
    dialog_id: DialogId,
    diff: i32,
    index_mask: i32,
) {
    if index_mask == 0 {
        return;
    }
    tracing::info!(
        "Update message count by {} in index mask {}",
        diff,
        index_mask
    );
    let is_secret = dialog_id.get_type() == DialogType::SecretChat;
    let failed_to_send_index =
        message_search_filter_index(MessageSearchFilter::FailedToSend) as usize;
    let mut changed = false;
    if let Some(d) = manager.get_dialog_mut(dialog_id) {
        for (i, message_count) in d.message_count_by_index.iter_mut().enumerate() {
            if ((index_mask >> i) & 1) != 0 && *message_count != -1 {
                *message_count += diff;
                if *message_count < 0 {
                    if is_secret || i == failed_to_send_index {
                        *message_count = 0;
                    } else {
                        *message_count = -1;
                    }
                }
                changed = true;
            }
        }
    }
    let mut calls_counts = manager.calls_db_state.message_count_by_index;
    for (loop_i, message_count) in calls_counts.iter_mut().enumerate() {
        let i = MessageSearchFilter::Call as i32 - 1 + loop_i as i32;
        if ((index_mask >> i) & 1) != 0 && *message_count != -1 {
            *message_count += diff;
            if *message_count < 0 {
                if is_secret {
                    *message_count = 0;
                } else {
                    *message_count = -1;
                }
            }
            save_calls_db_state(manager);
        }
    }
    manager.calls_db_state.message_count_by_index = calls_counts;
    if changed {
        on_dialog_updated(manager, dialog_id, "update_message_count_by_index");
    }
}

/// `MessagesManager::save_calls_db_state` (MessagesManager.cpp:3798-3808)
/// — the `calls_db_state` pmc row; the sqlite write rides the TdDb pmc
/// seam, the in-memory value is the engine.
fn save_calls_db_state(manager: &MessagesManager) {
    tracing::debug!(
        "calls_db_state = {:?}",
        manager.calls_db_state.message_count_by_index
    );
}

/// `MessagesManager::invalidate_message_indexes`
/// (MessagesManager.cpp:4093-4107).
pub fn invalidate_message_indexes(d: &mut Dialog) {
    let is_secret = d.dialog_id.get_type() == DialogType::SecretChat;
    let failed_to_send_index =
        message_search_filter_index(MessageSearchFilter::FailedToSend) as usize;
    for (i, slot) in d
        .message_count_by_index
        .iter_mut()
        .zip(d.first_database_message_id_by_index.iter_mut())
        .enumerate()
    {
        let (message_count, first_database_message_id) = slot;
        if is_secret || i == failed_to_send_index {
            // always know all messages
            *first_database_message_id = MessageId::min();
            // keep the count
        } else {
            // some messages are unknown; drop first_database_message_id and
            // count
            *first_database_message_id = MessageId::default();
            *message_count = -1;
        }
    }
}

/// `MessagesManager::set_dialog_last_new_message_id`
/// (MessagesManager.cpp:12214-12236).
pub fn set_dialog_last_new_message_id(
    global: &mut crate::global::Global,
    manager: &mut MessagesManager,
    ctx: &dyn SendMessageContext,
    dialog_id: DialogId,
    last_new_message_id: MessageId,
    source: &'static str,
) {
    assert!(!last_new_message_id.is_scheduled());
    assert!(!ctx.is_bot());
    {
        let d = manager
            .get_dialog(dialog_id)
            .expect("set_dialog_last_new_message_id without the dialog");
        assert!(
            last_new_message_id > d.last_new_message_id,
            "LOG_CHECK failed: {} {:?} {:?} {}",
            DisplayMessageId(last_new_message_id),
            DisplayMessageId(d.last_new_message_id),
            dialog_id,
            source
        );
        assert!(dialog_id.get_type() == DialogType::SecretChat || last_new_message_id.is_server());
    }

    if !manager
        .get_dialog(dialog_id)
        .unwrap()
        .last_new_message_id
        .is_valid()
    {
        // `remove_dialog_newer_messages` (12177-12210) — the gap repair
        // deletes the too-new memory messages and resets the db window
        remove_dialog_newer_messages(global, manager, dialog_id, last_new_message_id, source);

        let has_last_new = {
            let d = manager.get_dialog(dialog_id).unwrap();
            d.messages.contains_key(&last_new_message_id)
        };
        if has_last_new {
            let taken = manager
                .get_dialog_mut(dialog_id)
                .unwrap()
                .messages
                .remove(&last_new_message_id);
            if let Some(m) = &taken {
                let reactions_ctx = MessageObjectReactionsContext { ctx };
                let time = crate::user_manager::TimeCtx {
                    now: ctx.now(),
                    server_time: ctx.server_time(),
                };
                add_message_to_database(
                    global,
                    manager,
                    &reactions_ctx,
                    ctx.content_context(),
                    &time,
                    dialog_id,
                    m,
                    "set_dialog_last_new_message_id",
                );
            }
            manager
                .get_dialog_mut(dialog_id)
                .unwrap()
                .messages
                .insert(last_new_message_id, taken.unwrap());
            set_dialog_first_database_message_id(manager, dialog_id, last_new_message_id, source);
            set_dialog_last_database_message_id(
                manager,
                dialog_id,
                last_new_message_id,
                source,
                false,
            );
            // `try_restore_dialog_reply_markup` — the reply-markup restore
            // rides the M.10.14 pinned/reply-markup slice
        }
    }

    tracing::info!(
        "Set {} last new message to {} from {}",
        dialog_id.get(),
        DisplayMessageId(last_new_message_id),
        source
    );
    let d = manager.get_dialog_mut(dialog_id).unwrap();
    d.last_new_message_id = last_new_message_id;
    on_dialog_updated(manager, dialog_id, source);
}

/// `MessagesManager::remove_dialog_newer_messages`
/// (MessagesManager.cpp:12177-12210) — the channel-gap repair: everything
/// newer than `from_message_id` leaves memory and the database.
pub fn remove_dialog_newer_messages(
    global: &mut crate::global::Global,
    manager: &mut MessagesManager,
    dialog_id: DialogId,
    from_message_id: MessageId,
    source: &'static str,
) {
    tracing::info!(
        "Remove messages in {} newer than {} from {}",
        dialog_id.get(),
        DisplayMessageId(from_message_id),
        source
    );
    {
        let d = manager.get_dialog(dialog_id).unwrap();
        assert!(!d.last_new_message_id.is_valid());
    }

    // the function is called to handle channel gaps, and hence must always
    // delete all database messages, even if first_database_message_id and
    // last_database_message_id are empty
    delete_all_dialog_messages_from_database(
        global,
        dialog_id,
        MessageId::max(),
        "remove_dialog_newer_messages",
    );
    set_dialog_first_database_message_id(
        manager,
        dialog_id,
        MessageId::default(),
        "remove_dialog_newer_messages",
    );
    set_dialog_last_database_message_id(manager, dialog_id, MessageId::default(), source, false);
    {
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        if d.dialog_id.get_type() != DialogType::SecretChat && !d.is_empty {
            d.have_full_history = false;
            d.have_full_history_source = 0;
        }
        invalidate_message_indexes(d);
    }

    let to_delete_message_ids: Vec<MessageId> = {
        let d = manager.get_dialog(dialog_id).unwrap();
        d.ordered_messages
            .find_newer_messages(from_message_id)
            .into_iter()
            .filter(|message_id| !message_id.is_yet_unsent())
            .collect()
    };
    if !to_delete_message_ids.is_empty() {
        tracing::info!(
            "Delete {} messages newer than {} in {} from {}",
            to_delete_message_ids.len(),
            DisplayMessageId(from_message_id),
            dialog_id.get(),
            source
        );
        for message_id in to_delete_message_ids {
            let mut need_update_dialog_pos = false;
            let deleted = do_delete_message(
                global,
                manager,
                dialog_id,
                message_id,
                true,
                false,
                &mut need_update_dialog_pos,
                "remove_dialog_newer_messages",
            );
            if deleted.is_some() {
                send_update_delete_messages(manager, dialog_id, &[message_id], true);
            }
        }
    }
}

/// `MessagesManager::set_dialog_last_message_id`
/// (MessagesManager.cpp:12110-12145).
pub fn set_dialog_last_message_id(
    manager: &mut MessagesManager,
    dialog_id: DialogId,
    last_message_id: MessageId,
    source: &str,
) {
    assert!(!last_message_id.is_scheduled());
    tracing::info!(
        "Set {} last message to {} from {}",
        dialog_id.get(),
        DisplayMessageId(last_message_id),
        source
    );
    let needs_delete_last_repair = {
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        d.last_message_id = last_message_id;

        if !last_message_id.is_valid() {
            d.last_media_album_id = 0;
        } else {
            match d.messages.get(&last_message_id) {
                Some(m) => d.last_media_album_id = m.media_album_id,
                None => {
                    log_error!(
                        "Failed to find last {} in {}",
                        DisplayMessageId(last_message_id),
                        dialog_id.get()
                    );
                    d.last_media_album_id = 0;
                }
            }
        }
        // the dialog_suffix_load_queries_ reset (12132-12137) rides the
        // M.10.15 suffix-load slice
        last_message_id.is_valid() && d.delete_last_message_date != 0
    };
    if needs_delete_last_repair {
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        d.delete_last_message_date = 0;
        d.deleted_last_message_id = MessageId::default();
        d.is_last_message_deleted_locally = false;
        on_dialog_updated(manager, dialog_id, "update_delete_last_message_date");
    }
    let d = manager.get_dialog_mut(dialog_id).unwrap();
    d.pending_order = DEFAULT_ORDER;
}

/// `MessagesManager::set_dialog_first_database_message_id`
/// (MessagesManager.cpp:12147-12159).
pub fn set_dialog_first_database_message_id(
    manager: &mut MessagesManager,
    dialog_id: DialogId,
    first_database_message_id: MessageId,
    source: &str,
) {
    assert!(!first_database_message_id.is_scheduled());
    if manager
        .get_dialog(dialog_id)
        .map(|d| d.first_database_message_id == first_database_message_id)
        .unwrap_or(true)
    {
        return;
    }
    tracing::info!(
        "Set {} first database message to {} from {}",
        dialog_id.get(),
        DisplayMessageId(first_database_message_id),
        source
    );
    let d = manager.get_dialog_mut(dialog_id).unwrap();
    d.first_database_message_id = first_database_message_id;
    on_dialog_updated(manager, dialog_id, "set_dialog_first_database_message_id");
}

/// `MessagesManager::set_dialog_last_database_message_id`
/// (MessagesManager.cpp:12161-12175).
pub fn set_dialog_last_database_message_id(
    manager: &mut MessagesManager,
    dialog_id: DialogId,
    last_database_message_id: MessageId,
    source: &'static str,
    is_loaded_from_database: bool,
) {
    assert!(!last_database_message_id.is_scheduled());
    if manager
        .get_dialog(dialog_id)
        .map(|d| d.last_database_message_id == last_database_message_id)
        .unwrap_or(true)
    {
        return;
    }
    tracing::info!(
        "Set {} last database message to {} from {}",
        dialog_id.get(),
        DisplayMessageId(last_database_message_id),
        source
    );
    let d = manager.get_dialog_mut(dialog_id).unwrap();
    d.debug_set_dialog_last_database_message_id = source;
    d.last_database_message_id = last_database_message_id;
    if !is_loaded_from_database {
        on_dialog_updated(manager, dialog_id, "set_dialog_last_database_message_id");
    }
}

/// `MessagesManager::delete_message` (MessagesManager.cpp:13244-13248).
pub fn delete_message(
    global: &mut crate::global::Global,
    manager: &mut MessagesManager,
    dialog_id: DialogId,
    message_id: MessageId,
    is_permanently_deleted: bool,
    need_update_dialog_pos: &mut bool,
    source: &'static str,
) -> Option<Box<Message>> {
    do_delete_message(
        global,
        manager,
        dialog_id,
        message_id,
        is_permanently_deleted,
        false,
        need_update_dialog_pos,
        source,
    )
}

/// `MessagesManager::do_delete_message`
/// (MessagesManager.cpp:13494-13673) — the in-memory delete core with the
/// last-message/database-window repairs. The notification teardown
/// (`remove_message_notification_id`), the live-location persistence and
/// the file-source removal ride their manager seams; the memory container
/// walks are the port.
#[allow(clippy::too_many_arguments)]
pub fn do_delete_message(
    global: &mut crate::global::Global,
    manager: &mut MessagesManager,
    dialog_id: DialogId,
    message_id: MessageId,
    is_permanently_deleted: bool,
    only_from_memory: bool,
    need_update_dialog_pos: &mut bool,
    source: &'static str,
) -> Option<Box<Message>> {
    if !message_id.is_valid() {
        if message_id.is_valid_scheduled() {
            return do_delete_scheduled_message(
                global,
                manager,
                dialog_id,
                message_id,
                is_permanently_deleted,
                source,
            );
        }
        log_error!(
            "Trying to delete {} in {} from {}",
            DisplayMessageId(message_id),
            dialog_id.get(),
            source
        );
        return None;
    }

    let has_in_memory = manager
        .get_dialog(dialog_id)
        .map(|d| d.messages.contains_key(&message_id))
        .unwrap_or(false);
    if !has_in_memory {
        if only_from_memory {
            return None;
        }
        tracing::info!(
            "{} is not found in {} to be deleted from {}",
            DisplayMessageId(message_id),
            dialog_id.get(),
            source
        );
        // `get_message_force` db load — the dialog-db receive seam; the
        // database-delete safety net fires anyway
        delete_message_from_database(
            global,
            manager,
            dialog_id,
            message_id,
            None,
            is_permanently_deleted,
            source,
        );
        if is_permanently_deleted
            && manager
                .get_dialog(dialog_id)
                .map(|d| d.last_clear_history_message_id == message_id)
                .unwrap_or(false)
        {
            set_dialog_last_clear_history_date(
                manager,
                dialog_id,
                0,
                MessageId::default(),
                "do_delete_message",
            );
            *need_update_dialog_pos = true;
        }
        return None;
    }

    // `can_unload_message` (only_from_memory leg) — the pinned/open
    // message gate rides the M.10.13 unload slice; an in-memory message
    // with open_count == 0 unloads like the C++ default
    {
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        assert!(
            !d.being_deleted_message_id.is_valid(),
            "{} {} {}",
            DisplayMessageId(d.being_deleted_message_id),
            DisplayMessageId(message_id),
            source
        );
        d.being_deleted_message_id = message_id;
    }

    let mut need_get_history = false;
    if !only_from_memory {
        tracing::info!(
            "Deleting {}:{} from {}",
            dialog_id.get(),
            DisplayMessageId(message_id),
            source
        );

        delete_message_from_database(
            global,
            manager,
            dialog_id,
            message_id,
            None,
            is_permanently_deleted,
            source,
        );

        if delete_active_live_location(manager, MessageFullId::new(dialog_id, message_id)) {
            // `send_update_active_live_location_messages` + the db save
            // ride the live-location plane; the registry removal above is
            // the state change
        }
        // `remove_message_file_sources` — the M.10.18 files seam

        if message_id == manager.get_dialog(dialog_id).unwrap().last_message_id {
            let previous = {
                let d = manager.get_dialog(dialog_id).unwrap();
                d.ordered_messages.pred(message_id)
            };
            if let Some(previous) = previous {
                set_dialog_last_message_id(manager, dialog_id, previous, "do_delete_message");
            } else {
                need_get_history = true;
                let m_date = manager
                    .get_dialog(dialog_id)
                    .unwrap()
                    .messages
                    .get(&message_id)
                    .unwrap()
                    .date;
                set_dialog_last_message_id(
                    manager,
                    dialog_id,
                    MessageId::default(),
                    "do_delete_message",
                );
                let d = manager.get_dialog_mut(dialog_id).unwrap();
                d.delete_last_message_date = m_date;
                d.deleted_last_message_id = message_id;
                d.is_last_message_deleted_locally = source == DELETE_MESSAGE_USER_REQUEST_SOURCE;
                on_dialog_updated(manager, dialog_id, "do delete last message");
            }
            *need_update_dialog_pos = true;
        }

        if message_id
            == manager
                .get_dialog(dialog_id)
                .unwrap()
                .last_database_message_id
        {
            // walk down past the yet-unsent ids to the newest database one
            let mut it = manager
                .get_dialog(dialog_id)
                .unwrap()
                .ordered_messages
                .pred(message_id);
            while let Some(cur) = it
                && cur.is_yet_unsent()
            {
                it = manager
                    .get_dialog(dialog_id)
                    .unwrap()
                    .ordered_messages
                    .pred(cur);
            }
            let previous = it;
            match previous {
                Some(previous)
                    if previous
                        < manager
                            .get_dialog(dialog_id)
                            .unwrap()
                            .first_database_message_id
                        && dialog_id.get_type() == DialogType::Channel =>
                {
                    // possible if messages were deleted from database, but
                    // not from memory after updateChannelTooLong
                    set_dialog_last_database_message_id(
                        manager,
                        dialog_id,
                        MessageId::default(),
                        "do_delete_message 1",
                        false,
                    );
                }
                Some(previous) => {
                    set_dialog_last_database_message_id(
                        manager,
                        dialog_id,
                        previous,
                        "do_delete_message 2",
                        false,
                    );
                    let d = manager.get_dialog(dialog_id).unwrap();
                    if d.last_database_message_id < d.first_database_message_id {
                        log_error!(
                            "Last database {} became less than first database {} after deletion of {}:{}",
                            DisplayMessageId(d.last_database_message_id),
                            DisplayMessageId(d.first_database_message_id),
                            dialog_id.get(),
                            DisplayMessageId(message_id)
                        );
                        let last = d.last_database_message_id;
                        set_dialog_first_database_message_id(
                            manager,
                            dialog_id,
                            last,
                            "do_delete_message 2",
                        );
                    }
                }
                None => {
                    let d = manager.get_dialog(dialog_id).unwrap();
                    if d.first_database_message_id == d.last_database_message_id {
                        // database definitely has no more messages
                        set_dialog_last_database_message_id(
                            manager,
                            dialog_id,
                            MessageId::default(),
                            "do_delete_message 3",
                            false,
                        );
                    } else {
                        tracing::info!(
                            "Need to get history to repair last_database_message_id in {}",
                            dialog_id.get()
                        );
                        need_get_history = true;
                    }
                }
            }
        }
        {
            let d = manager.get_dialog(dialog_id).unwrap();
            if d.last_database_message_id.is_valid() {
                assert!(d.first_database_message_id.is_valid());
            } else if d.first_database_message_id.is_valid() {
                set_dialog_first_database_message_id(
                    manager,
                    dialog_id,
                    MessageId::default(),
                    "do_delete_message",
                );
            }
        }
        // the dialog_suffix_load_queries_ repair (13624-13637) rides the
        // M.10.15 suffix-load slice
    }

    let result = {
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        let result = d.messages.remove(&message_id);
        if result.is_some() {
            d.message_lru_list.remove(message_id);
        }
        d.ordered_messages
            .erase(message_id, only_from_memory, source);
        d.being_deleted_message_id = MessageId::default();
        result
    };

    if need_get_history {
        // `load_last_dialog_message_later` — the net/history seam
        // (M.10.15)
    }

    if let Some(result) = &result {
        on_message_deleted(manager, dialog_id, result, is_permanently_deleted, source);
    }

    result
}

/// `MessagesManager::do_delete_scheduled_message`
/// (MessagesManager.cpp:13800-13863).
pub fn do_delete_scheduled_message(
    global: &mut crate::global::Global,
    manager: &mut MessagesManager,
    dialog_id: DialogId,
    message_id: MessageId,
    is_permanently_deleted: bool,
    source: &str,
) -> Option<Box<Message>> {
    assert!(
        message_id.is_valid_scheduled(),
        "{} {:?} {}",
        dialog_id.get(),
        message_id,
        source
    );

    if manager
        .get_dialog(dialog_id)
        .map(|d| d.scheduled_messages.is_none())
        .unwrap_or(true)
    {
        delete_message_from_database(
            global,
            manager,
            dialog_id,
            message_id,
            None,
            is_permanently_deleted,
            source,
        );
        return None;
    }
    let in_container = manager
        .get_dialog(dialog_id)
        .unwrap()
        .scheduled_messages
        .as_ref()
        .unwrap()
        .scheduled_messages
        .contains_key(&message_id);
    if !in_container {
        tracing::info!(
            "{} is not found in {} to be deleted from {}",
            DisplayMessageId(message_id),
            dialog_id.get(),
            source
        );
        delete_message_from_database(
            global,
            manager,
            dialog_id,
            message_id,
            None,
            is_permanently_deleted,
            source,
        );
        return None;
    }

    tracing::info!(
        "Deleting {}:{} from {}",
        dialog_id.get(),
        DisplayMessageId(message_id),
        source
    );
    delete_message_from_database(
        global,
        manager,
        dialog_id,
        message_id,
        None,
        is_permanently_deleted,
        source,
    );

    let result = {
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        let scheduled_messages = d.scheduled_messages.as_mut().unwrap();
        let result = scheduled_messages.scheduled_messages.remove(&message_id);
        if message_id.is_scheduled_server() {
            assert!(
                scheduled_messages
                    .scheduled_message_date
                    .remove(&message_id.get_scheduled_server_message_id())
                    .is_some()
            );
        }
        result
    };

    if let Some(result) = &result {
        // `cancel_send_deleted_message` — the net cancel seam (M.10.9 net
        // flip)
        if result.is_topic_message {
            // the ForumTopicManager count seam
        }
        if message_id.is_yet_unsent() {
            let d = manager.get_dialog_mut(dialog_id).unwrap();
            delete_random_id_to_message_id_correspondence(d, result.random_id, result.message_id);
        }
    }
    result
}

/// `MessagesManager::on_message_deleted` (MessagesManager.cpp:13721-13789)
/// — the container/index teardown after the memory removal.
pub fn on_message_deleted(
    manager: &mut MessagesManager,
    dialog_id: DialogId,
    m: &Message,
    _is_permanently_deleted: bool,
    source: &str,
) {
    // also called for unloaded messages, but not for scheduled messages
    assert!(m.message_id.is_valid());

    if m.message_id.is_yet_unsent()
        && !m.message_id.is_scheduled()
        && m.top_thread_message_id.is_valid()
        && let Some(thread_ids) = manager
            .yet_unsent_thread_message_ids
            .get_mut(&MessageFullId::new(dialog_id, m.top_thread_message_id))
    {
        assert!(thread_ids.remove(&m.message_id));
        if thread_ids.is_empty() {
            manager
                .yet_unsent_thread_message_ids
                .remove(&MessageFullId::new(dialog_id, m.top_thread_message_id));
        }
    }

    // `cancel_send_deleted_message` — the net cancel seam; the upload
    // cancel rides the M.12/M.10.9 net flip

    match dialog_id.get_type() {
        DialogType::User | DialogType::Chat => {
            if m.message_id.is_server() {
                manager.message_id_to_dialog_id.remove(&m.message_id);
            }
        }
        DialogType::Channel => {
            // `unregister_message_users`/`unregister_message_channels` —
            // the UserManager/ChatManager receive seams
        }
        DialogType::SecretChat | DialogType::None => {}
    }
    {
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        unregister_dialog_ephemeral_message(d, m.ephemeral_message_id);
    }
    // `ttl_unregister_message`/`ttl_period_unregister_message` — the ttl
    // scheduler seam
    // `unregister_message_content`/`unregister_message_reply` — the M.9.12
    // register family through the content context; rides the Td wiring
    if m.is_topic_message {
        // the ForumTopicManager count seam
    }
    let _ = source;

    manager.added_message_count -= 1;
}

/// `MessagesManager::try_add_active_live_location`
/// (MessagesManager.cpp:18634-18670).
pub fn try_add_active_live_location(
    ctx: &dyn SendMessageContext,
    manager: &mut MessagesManager,
    dialog_id: DialogId,
    m: &Message,
) -> bool {
    if ctx.is_bot()
        || m.content.as_ref().map(|c| c.get_type()) != Some(MessageContentType::LiveLocation)
        || m.message_id.is_scheduled()
        || m.message_id.is_local()
        || m.message_id.is_yet_unsent()
        || m.via_bot_user_id.is_valid()
        || m.guest_bot_via_dialog_id.is_valid()
        || m.via_business_bot_user_id.is_valid()
        || m.forward_info.is_some()
    {
        return false;
    }
    let live_period = crate::message_content::get_message_content_live_location_period(
        m.content.as_ref().unwrap(),
    );
    if live_period <= ctx.unix_time() - m.date + 1 {
        // live location is expired
        return false;
    }
    add_active_live_location(manager, MessageFullId::new(dialog_id, m.message_id))
}

/// `MessagesManager::add_active_live_location`
/// (MessagesManager.cpp:18650-18671) — the registry insert; the db
/// save/load legs ride the TdDb seam.
pub fn add_active_live_location(
    manager: &mut MessagesManager,
    message_full_id: MessageFullId,
) -> bool {
    assert!(message_full_id.get_message_id().is_valid());
    if !manager
        .active_live_location_message_full_ids
        .insert(message_full_id)
    {
        return false;
    }
    true
}

/// `MessagesManager::delete_active_live_location`
/// (MessagesManager.cpp:18672-18674).
pub fn delete_active_live_location(
    manager: &mut MessagesManager,
    message_full_id: MessageFullId,
) -> bool {
    manager
        .active_live_location_message_full_ids
        .remove(&message_full_id)
}

/// `MessagesManager::update_reply_to_message_id`
/// (MessagesManager.cpp:27808-27846) — the yet-unsent id rewrite fanned
/// out to every replying message.
pub fn update_reply_to_message_id(
    manager: &mut MessagesManager,
    dialog_id: DialogId,
    old_message_id: MessageId,
    new_message_id: MessageId,
    have_new_message: bool,
    source: &'static str,
) {
    let old_message_full_id = MessageFullId::new(dialog_id, old_message_id);
    let Some(replies) = manager
        .replied_yet_unsent_messages
        .get(&old_message_full_id)
    else {
        return;
    };
    let replies = replies.clone();
    tracing::debug!(
        "Update replies to {}:{} to its new {} from {}",
        dialog_id.get(),
        DisplayMessageId(old_message_id),
        DisplayMessageId(new_message_id),
        source
    );
    assert!(old_message_id.is_yet_unsent());
    assert!(
        new_message_id == MessageId::default()
            || new_message_id.is_valid()
            || new_message_id.is_valid_scheduled()
    );

    let replies_count = replies.len();
    for message_full_id in replies {
        let reply_dialog_id = message_full_id.get_dialog_id();
        let reply_message_id = message_full_id.get_message_id();
        let has_message = manager
            .get_dialog(reply_dialog_id)
            .map(|d| d.messages.contains_key(&reply_message_id))
            .unwrap_or(false);
        assert!(has_message, "missing replying message {message_full_id:?}");
        if new_message_id != MessageId::default() {
            let checked = manager
                .get_dialog(reply_dialog_id)
                .and_then(|d| d.messages.get(&reply_message_id))
                .map(|m| {
                    m.replied_message_info
                        .get_reply_message_full_id(reply_dialog_id, true)
                })
                .is_some_and(|full_id| full_id == old_message_full_id);
            assert!(
                checked,
                "{} {:?} replied-message info mismatch in update_reply_to_message_id",
                dialog_id.get(),
                message_full_id
            );
            let d = manager.get_dialog_mut(reply_dialog_id).unwrap();
            let m = d.messages.get_mut(&reply_message_id).unwrap();
            m.replied_message_info.set_message_id(new_message_id);
            if !m.message_id.is_any_server() {
                m.input_reply_to.set_message_id(new_message_id, source);
            }
        } else {
            // `set_message_reply(reply_d, replied_m, MessageInputReplyTo(),
            // true)` — the reset; rides the reply plane through the empty
            // input
            let d = manager.get_dialog_mut(reply_dialog_id).unwrap();
            let m = d.messages.get_mut(&reply_message_id).unwrap();
            m.replied_message_info = RepliedMessageInfo::default();
            m.input_reply_to = MessageInputReplyTo::default();
        }
    }
    if have_new_message {
        assert!(new_message_id != MessageId::default());
        assert!(!new_message_id.is_yet_unsent());
        manager.replied_by_yet_unsent_messages.insert(
            MessageFullId::new(dialog_id, new_message_id),
            replies_count as i32,
        );
    } else {
        manager
            .replied_by_yet_unsent_messages
            .remove(&MessageFullId::new(dialog_id, new_message_id));
    }
    manager
        .replied_yet_unsent_messages
        .remove(&old_message_full_id);
}

/// `MessagesManager::send_update_new_message`
/// (MessagesManager.cpp:25706-25713).
pub fn send_update_new_message(
    manager: &mut MessagesManager,
    ctx: &dyn SendMessageContext,
    state: &mut dyn ReadStateContext,
    reactions_ctx: &dyn DialogReactionsContext,
    dialog_id: DialogId,
    m: &mut Message,
) {
    {
        let d = manager
            .get_dialog(dialog_id)
            .expect("send_update_new_message without the dialog");
        assert!(d.is_update_new_chat_sent);
    }
    if let Some(message) = get_message_object(
        manager,
        reactions_ctx,
        ctx,
        dialog_id,
        m,
        "send_update_new_message",
    ) {
        state.send_update(td_api::Object::updateNewMessage(td_api::updateNewMessage {
            message: Some(message),
        }));
    }
}

/// `MessagesManager::send_update_message_send_succeeded`
/// (MessagesManager.cpp:26981-27011).
#[allow(clippy::too_many_arguments)] // the C++ signature has the same shape
pub fn send_update_message_send_succeeded(
    global: &mut crate::global::Global,
    manager: &mut MessagesManager,
    ctx: &dyn SendMessageContext,
    state: &mut dyn ReadStateContext,
    reactions_ctx: &dyn DialogReactionsContext,
    dialog_id: DialogId,
    old_message_id: MessageId,
    m: &mut Message,
    need_update_dialog_pos: &mut bool,
) {
    m.file_upload_ids.clear();
    m.thumbnail_file_upload_ids.clear();
    if m.paid_message_star_count > 0 {
        // the StarManager pending refund seam
    }
    if !ctx.is_bot() {
        manager
            .yet_unsent_message_full_id_to_persistent_message_id
            .insert(MessageFullId::new(dialog_id, old_message_id), m.message_id);

        let deleted = delete_message(
            global,
            manager,
            dialog_id,
            m.message_id,
            false,
            need_update_dialog_pos,
            "send_update_message_send_succeeded",
        );
        if deleted.is_some() {
            send_update_delete_messages(manager, dialog_id, &[m.message_id], false);
        }
    }
    {
        let d = manager.get_dialog(dialog_id).unwrap();
        if old_message_id.is_valid()
            && m.message_id.is_valid()
            && m.message_id < old_message_id
            && !d.had_yet_unsent_message_id_overflow
            && m.message_id.get() != 1
        {
            log_error!(
                "Sent {} to {} as {}",
                DisplayMessageId(old_message_id),
                dialog_id.get(),
                DisplayMessageId(m.message_id)
            );
        }
    }
    if let Some(message) = get_message_object(
        manager,
        reactions_ctx,
        ctx,
        dialog_id,
        m,
        "send_update_message_send_succeeded",
    ) {
        state.send_update(td_api::Object::updateMessageSendSucceeded(
            td_api::updateMessageSendSucceeded {
                message: Some(message),
                old_message_id: old_message_id.get(),
            },
        ));
    }
}

/// `MessagesManager::send_update_delete_messages`
/// (MessagesManager.cpp:27181-27240) — the count-first emission order.
pub fn send_update_delete_messages(
    _manager: &MessagesManager,
    dialog_id: DialogId,
    message_ids: &[MessageId],
    is_permanent: bool,
) {
    // the full C++ sends updateDeleteMessages through the update plane
    // with the pending-updates gate; the direct emission is the ported
    // spine — the Td wiring delivers it
    let _ = (dialog_id, message_ids, is_permanent);
    tracing::info!(
        "send_update_delete_messages: {} messages in {} permanent={}",
        message_ids.len(),
        dialog_id.get(),
        is_permanent
    );
}

/// `MessagesManager::send_update_chat_last_message_impl`
/// (MessagesManager.cpp:27269-27285) — `update_dialog_pos` (the
/// M.10.12 dialog-list order machine) is the recorded seam; the emission
/// itself is the port.
pub fn send_update_chat_last_message(
    manager: &mut MessagesManager,
    ctx: &dyn SendMessageContext,
    state: &mut dyn ReadStateContext,
    reactions_ctx: &dyn DialogReactionsContext,
    dialog_id: DialogId,
    source: &str,
) {
    if ctx.is_bot() {
        return;
    }
    // update_dialog_pos — the M.10.12 seam
    let _ = source;
    let last_message_id = manager.get_dialog(dialog_id).unwrap().last_message_id;
    let message_object = match last_message_id {
        id if !id.is_valid() => None,
        _ => {
            // the scheduled container is not the last-message source
            let mut taken: Option<Box<Message>> = manager
                .get_dialog_mut(dialog_id)
                .unwrap()
                .messages
                .remove(&last_message_id);
            if taken.is_none() {
                log_error!(
                    "Failed to find last {} in {} for updateChatLastMessage",
                    DisplayMessageId(last_message_id),
                    dialog_id.get()
                );
            }
            let object = taken.as_mut().and_then(|m| {
                get_message_object(
                    manager,
                    reactions_ctx,
                    ctx,
                    dialog_id,
                    m,
                    "send_update_chat_last_message_impl",
                )
            });
            if let Some(m) = taken {
                manager
                    .get_dialog_mut(dialog_id)
                    .unwrap()
                    .messages
                    .insert(last_message_id, m);
            }
            object
        }
    };
    state.send_update(td_api::Object::updateChatLastMessage(
        td_api::updateChatLastMessage {
            chat_id: dialog_id.get(),
            last_message: message_object,
            positions: Vec::new(), // the M.10.12 dialog-list positions plane
        },
    ));
}

/// `MessagesManager::on_update_message_id` (MessagesManager.cpp:25635-25664)
/// — the updateMessageID flip.
pub fn on_update_message_id(
    manager: &mut MessagesManager,
    random_id: i64,
    new_message_id: MessageId,
    source: &str,
) -> bool {
    if !new_message_id.is_valid() && !new_message_id.is_valid_scheduled() {
        log_error!(
            "Receive {} in updateMessageID with random_id {} from {}",
            DisplayMessageId(new_message_id),
            random_id,
            source
        );
        return false;
    }
    assert!(new_message_id.is_any_server());

    let Some(message_full_id) = manager.being_sent_messages.get(&random_id).copied() else {
        // update about a new message sent from other device or a service
        // message
        tracing::info!(
            "Receive not sent outgoing {} with random_id = {}",
            DisplayMessageId(new_message_id),
            random_id
        );
        return true;
    };

    let dialog_id = message_full_id.get_dialog_id();
    let old_message_id = message_full_id.get_message_id();

    manager.being_sent_messages.remove(&random_id);

    if !have_message_in_dialog(manager, dialog_id, old_message_id) {
        // `delete_sent_message_on_server` — the net seam
        tracing::info!(
            "delete_sent_message_on_server seam: {}:{} new {}",
            dialog_id.get(),
            DisplayMessageId(old_message_id),
            DisplayMessageId(new_message_id)
        );
        return true;
    }

    tracing::info!(
        "Save correspondence from {} in {} to {}",
        DisplayMessageId(new_message_id),
        dialog_id.get(),
        DisplayMessageId(old_message_id)
    );
    assert!(old_message_id.is_yet_unsent());
    manager
        .update_message_ids
        .insert((dialog_id, new_message_id), old_message_id);
    true
}

/// `MessagesManager::get_message_flags` (MessagesManager.cpp:24198-24244) —
/// the `messages.sendMessage` flag word over the message model.
fn get_message_flags(m: &Message) -> i32 {
    const DISABLE_WEB_PAGE_PREVIEW: i32 = 1 << 1;
    const HAS_REPLY_MARKUP: i32 = 1 << 2;
    const DISABLE_NOTIFICATION: i32 = 1 << 5;
    const FROM_BACKGROUND: i32 = 1 << 6;
    const CLEAR_DRAFT: i32 = 1 << 7;
    const HAS_SCHEDULE_DATE: i32 = 1 << 10;
    const HAS_SCHEDULE_REPEAT_PERIOD: i32 = 1 << 24;
    const UPDATE_STICKER_SETS_ORDER: i32 = 1 << 15;
    const INVERT_MEDIA: i32 = 1 << 16;
    const EFFECT: i32 = 1 << 18;
    const ALLOW_PAID: i32 = 1 << 19;
    const ALLOW_PAID_STARS: i32 = 1 << 21;

    let mut flags = 0;
    if m.disable_web_page_preview {
        flags |= DISABLE_WEB_PAGE_PREVIEW;
    }
    if m.reply_markup.is_some() {
        flags |= HAS_REPLY_MARKUP;
    }
    if m.disable_notification {
        flags |= DISABLE_NOTIFICATION;
    }
    if m.from_background {
        flags |= FROM_BACKGROUND;
    }
    if m.clear_draft {
        flags |= CLEAR_DRAFT;
    }
    if m.message_id.is_scheduled() {
        flags |= HAS_SCHEDULE_DATE;
        if m.schedule_repeat_period != 0 {
            flags |= HAS_SCHEDULE_REPEAT_PERIOD;
        }
    }
    if m.update_stickersets_order {
        flags |= UPDATE_STICKER_SETS_ORDER;
    }
    if m.invert_media {
        flags |= INVERT_MEDIA;
    }
    if m.effect_id.is_valid() {
        flags |= EFFECT;
    }
    if m.allow_paid {
        flags |= ALLOW_PAID;
    }
    if m.paid_message_star_count != 0 {
        flags |= ALLOW_PAID_STARS;
    }
    flags
}

/// The `SendMessageQuery::send` wire payload (MessagesManager.cpp:1207-1249)
/// — the manager-level data prebuilt where the message lives; the
/// dialog-level pieces (the write input peer) resolve in the Td impl of
/// [`SendMessageContext::send_text_message_query`].
pub struct TextMessageQueryParams {
    pub flags: i32,
    pub no_webpage: bool,
    pub silent: bool,
    pub background: bool,
    pub clear_draft: bool,
    pub noforwards: bool,
    pub update_stickersets_order: bool,
    pub invert_media: bool,
    pub allow_paid_floodskip: bool,
    pub dialog_id: DialogId,
    /// `inputReplyToMessage` — the plain reply arm; the
    /// story/ephemeral/quote/topic arms ride their slices (documented in
    /// [`get_input_reply_to_for_send`]).
    pub reply_to_message_id: Option<i32>,
    pub top_msg_id: i32,
    pub message: String,
    pub random_id: i64,
    /// `get_input_reply_markup` — the wire form.
    pub reply_markup: Option<tdmtproto::telegram_api::ReplyMarkup>,
    pub entities: Vec<tdmtproto::telegram_api::MessageEntity>,
    pub schedule_date: i32,
    pub schedule_repeat_period: i32,
    pub effect: i64,
    pub allow_paid_stars: i64,
    pub suggested_post: Option<SuggestedPost>,
}

/// `MessageInputReplyTo::get_input_reply_to` (MessageInputReplyTo.cpp:97-176)
/// — the plain arms the send wire exercises: the empty reply and the
/// ordinary/scheduled message reply. The story arm, the ephemeral arm, the
/// quote plane and the monoforum/saved-input-peer arms keep their
/// documented seams (the walking-skeleton send path is the plain reply).
fn get_input_reply_to_for_send(
    input_reply_to: &MessageInputReplyTo,
) -> Option<(Option<i32>, i32)> {
    if input_reply_to.story_full_id.is_valid() || input_reply_to.ephemeral_message_id.is_valid() {
        tdutils::log_debug!("Reply wire arm stays the story/ephemeral seam — dropped from the send query");
        return None;
    }
    let reply_to_message_id = input_reply_to.message_id;
    if reply_to_message_id == MessageId::default() {
        return None;
    }
    if !reply_to_message_id.is_server() && !reply_to_message_id.is_valid_scheduled() {
        // the C++ rewrites non-server ids through the sent-message
        // correspondence; the yet-unsent reply rides that plane
        tdutils::log_debug!("Reply to a non-server message id stays the sent-correspondence seam");
        return None;
    }
    Some((Some(reply_to_message_id.get() as i32), 0))
}

/// `MessagesManager::on_text_message_ready_to_send` (MessagesManager.cpp:22787-22841)
/// — the text wire send: the secret arm keeps its SecretChats seam, the
/// plain arm registers the random id and hands the query payload to the
/// [`SendMessageContext::send_text_message_query`] net leg.
#[allow(clippy::type_complexity)] // one field-read tuple, mirroring do_send_message
pub fn on_text_message_ready_to_send(
    manager: &mut MessagesManager,
    ctx: &mut dyn SendMessageContext,
    dialog_id: DialogId,
    message_id: MessageId,
) {
    // the C++ `G()->close_flag()` guard is the actor-close race window;
    // the collapsed send runs inside the request turn that just passed the
    // dispatcher's own close checks.
    tracing::info!("Ready to send {:?} to {:?}", message_id, dialog_id);

    if dialog_id.get_type() == DialogType::SecretChat {
        assert!(!message_id.is_scheduled());
        // `send_secret_message` — the SecretChats seam ([blocked: M.9/M.50])
        tdutils::log_debug!("Secret-chat send arm stays the SecretChats seam");
        return;
    }

    // the field-read dance (the `Message` is the C++ pointer view): the
    // content and the query inputs come out, the manager borrow drops
    // before `begin_send_message` mutates the registry.
    let Some((
        content,
        stored_random_id,
        input_reply_to,
        reply_markup,
        is_topic_message,
        top_thread_message_id,
        suggested_post,
        schedule_repeat_period,
        disable_web_page_preview,
        disable_notification,
        from_background,
        clear_draft,
        noforwards,
        update_stickersets_order,
        invert_media,
        allow_paid,
        effect_id,
        paid_message_star_count,
    )) = manager
        .get_dialog(dialog_id)
        .and_then(|d| d.messages.get(&message_id))
        .map(|m| {
            assert!(message_id.is_yet_unsent());
            (
                m.content.clone(),
                m.random_id,
                m.input_reply_to.clone(),
                m.reply_markup.clone(),
                m.is_topic_message,
                m.top_thread_message_id,
                m.suggested_post.clone(),
                m.schedule_repeat_period,
                m.disable_web_page_preview,
                m.disable_notification,
                m.from_background,
                m.clear_draft,
                m.noforwards,
                m.update_stickersets_order,
                m.invert_media,
                m.allow_paid,
                m.effect_id,
                m.paid_message_star_count,
            )
        })
    else {
        return;
    };

    let Some(message_text) =
        crate::message_content::get_message_content_text(
            content.as_ref().expect("a text send carries content"),
        )
            .cloned()
    else {
        panic!("on_text_message_ready_to_send without a text content");
    };

    let probe = Message {
        message_id,
        random_id: stored_random_id,
        ..Message::default()
    };
    let random_id = begin_send_message(manager, dialog_id, &probe);

    // `get_message_flags` + the input-reply/topic tails; the send-as arm
    // (`get_send_message_as_input_peer`) keeps the explicit-sender seam.
    let mut flags = {
        let m = Message {
            message_id,
            reply_markup: reply_markup.clone(),
            schedule_repeat_period,
            disable_web_page_preview,
            disable_notification,
            from_background,
            clear_draft,
            noforwards,
            update_stickersets_order,
            invert_media,
            allow_paid,
            effect_id,
            paid_message_star_count,
            ..Message::default()
        };
        get_message_flags(&m)
    };
    let reply_to = get_input_reply_to_for_send(&input_reply_to);
    let reply_to_message_id = reply_to.as_ref().and_then(|(id, _)| *id);
    if reply_to_message_id.is_some() {
        flags |= SEND_MESSAGE_FLAG_REPLY_TO_MASK;
    }
    // the None-backed pass is the () resolver — no user-manager reads
    // (the custom-emoji entity band rides the UserManager split)
    let entities =
        crate::message_entity::get_input_message_entities::<()>(
            None,
            &message_text.entities,
            "SendMessageQuery",
        );
    if !entities.is_empty() {
        flags |= SEND_MESSAGE_FLAG_HAS_ENTITIES;
    }
    if reply_markup.is_some() {
        flags |= SEND_MESSAGE_FLAG_HAS_REPLY_MARKUP;
    }
    let top_msg_id = if is_topic_message {
        top_thread_message_id.get() as i32
    } else {
        0
    };
    let params = TextMessageQueryParams {
        flags,
        no_webpage: disable_web_page_preview,
        silent: disable_notification,
        background: from_background,
        clear_draft,
        noforwards,
        update_stickersets_order,
        invert_media,
        allow_paid_floodskip: allow_paid,
        dialog_id,
        reply_to_message_id,
        top_msg_id,
        message: message_text.text.clone(),
        random_id,
        reply_markup: reply_markup
            .as_deref()
            .and_then(crate::reply_markup::get_input_reply_markup),
        entities,
        schedule_date: if message_id.is_scheduled() {
            probe_date(manager, dialog_id, message_id)
        } else {
            0
        },
        schedule_repeat_period,
        effect: effect_id.get(),
        allow_paid_stars: paid_message_star_count,
        suggested_post,
    };
    ctx.send_text_message_query(params);
}

/// `get_message_schedule_date` (MessagesManager.cpp:23415-23424) — the
/// edited date else the message date.
fn probe_date(manager: &MessagesManager, dialog_id: DialogId, message_id: MessageId) -> i32 {
    manager
        .get_dialog(dialog_id)
        .and_then(|d| d.messages.get(&message_id))
        .map(|m| {
            if m.edited_schedule_date != 0 {
                m.edited_schedule_date
            } else {
                m.date
            }
        })
        .unwrap_or(0)
}

/// `SendMessageQuery` flag constants (MessagesManager.h:136-150) — the
/// `flags` word rides the generated bool fields for the masked bases, so
/// only the pointer-bearing bits are set here.
const SEND_MESSAGE_FLAG_REPLY_TO_MASK: i32 = 1;
const SEND_MESSAGE_FLAG_HAS_REPLY_MARKUP: i32 = 1 << 2;
const SEND_MESSAGE_FLAG_HAS_ENTITIES: i32 = 1 << 3;

/// `MessagesManager::on_update_sent_text_message` (MessagesManager.cpp:12643-12707)
/// — the `updateShortSentMessage` content swap: the being-sent message
/// gets the server-built text (entities + the web-page media), and the
/// changed-content machinery runs its emissions.
pub fn on_update_sent_text_message(
    _global: &mut crate::global::Global,
    manager: &mut MessagesManager,
    _ctx: &dyn SendMessageContext,
    _state: &mut dyn ReadStateContext,
    random_id: i64,
    message_media: Option<tdmtproto::telegram_api::MessageMedia>,
    entities: Vec<tdmtproto::telegram_api::MessageEntity>,
) {
    let Some(message_full_id) = manager.being_sent_messages.get(&random_id).copied() else {
        // the result has already arrived through getDifference
        return;
    };
    let dialog_id = message_full_id.get_dialog_id();
    let old_message_id = message_full_id.get_message_id();
    let Some(m) = manager
        .get_dialog_mut(dialog_id)
        .and_then(|d| d.messages.get_mut(&old_message_id))
    else {
        // the message has already been deleted
        return;
    };
    assert!(m.message_id.is_yet_unsent());
    if !matches!(
        m.content.as_ref().map(|content| content.get_type()),
        Some(crate::message_content::MessageContentType::Text)
    ) {
        log_error!("Text message content has been already changed");
        return;
    }
    let old_message_text =
        crate::message_content::get_message_content_text(m.content.as_ref().expect("checked above"))
        .expect("a text content carries its text");
    // the C++ rebuilds the FormattedText through get_message_text +
    // get_message_content (the merge/reregister/emit tail rides the
    // M.9 content plane); the plain-text S76 shape carries no user
    // entities, so the None user-manager pass is the documented stand-in.
    let new_message_text =
        crate::message_entity::get_message_text::<()>(
        None,
        old_message_text.text.clone(),
        entities,
        true,
        false,
        m.date,
        m.media_album_id != 0,
        "on_update_sent_text_message",
    );
    let _ = message_media;
    let mut new_content = m.content.clone().expect("checked above");
    if let crate::message_content::MessageContent::Text(ref mut message_text) = new_content {
        message_text.text = new_message_text;
    }
    m.content = Some(new_content);
    m.is_content_secret = m
        .ttl
        .is_secret_message_content(crate::message_content::MessageContentType::Text);
}

/// `MessagesManager::on_send_message_success` (MessagesManager.cpp:
/// 27848-27960) — the send-completion core (the `updateShortSentMessage`
/// / Updates-container ack path).
#[allow(clippy::too_many_arguments)] // the C++ signature has the same shape
pub fn on_send_message_success(
    global: &mut crate::global::Global,
    manager: &mut MessagesManager,
    ctx: &dyn SendMessageContext,
    state: &mut dyn ReadStateContext,
    reactions_ctx: &dyn DialogReactionsContext,
    random_id: i64,
    new_message_id: MessageId,
    date: i32,
    ttl_period: i32,
    source: &'static str,
) -> MessageFullId {
    if !new_message_id.is_valid() {
        log_error!(
            "Receive {} as sent message from {}",
            DisplayMessageId(new_message_id),
            source
        );
        on_send_message_fail(
            global,
            manager,
            ctx,
            state,
            random_id,
            500,
            "Internal Server Error: receive invalid message identifier as sent message identifier",
        );
        return MessageFullId::default();
    }
    if new_message_id.is_yet_unsent() {
        log_error!(
            "Receive {} as sent message from {}",
            DisplayMessageId(new_message_id),
            source
        );
        on_send_message_fail(
            global,
            manager,
            ctx,
            state,
            random_id,
            500,
            "Internal Server Error: receive yet unsent message as sent message",
        );
        return MessageFullId::default();
    }

    let Some(message_full_id) = manager.being_sent_messages.get(&random_id).copied() else {
        log_error!(
            "Result from sendMessage for {} with random_id {} sent at {} comes from {} after updateNewMessageId, but was not discarded by PTS",
            DisplayMessageId(new_message_id),
            random_id,
            date,
            source
        );
        return MessageFullId::default();
    };

    let dialog_id = message_full_id.get_dialog_id();
    let old_message_id = message_full_id.get_message_id();

    if new_message_id.is_local() && dialog_id.get_type() != DialogType::SecretChat {
        log_error!(
            "Receive {} as sent message from {}",
            DisplayMessageId(new_message_id),
            source
        );
        on_send_message_fail(
            global,
            manager,
            ctx,
            state,
            random_id,
            500,
            "Internal Server Error: receive local as sent message",
        );
        return MessageFullId::default();
    }

    manager.being_sent_messages.remove(&random_id);

    // must be called before delete_message
    update_reply_to_message_id(
        manager,
        dialog_id,
        old_message_id,
        new_message_id,
        true,
        "on_send_message_success",
    );

    assert!(manager.get_dialog(dialog_id).is_some());
    let mut need_update_dialog_pos = false;
    manager.being_readded_message_full_id = MessageFullId::new(dialog_id, old_message_id);
    let mut sent_message = match delete_message(
        global,
        manager,
        dialog_id,
        old_message_id,
        false,
        &mut need_update_dialog_pos,
        source,
    ) {
        Some(m) => m,
        None => {
            // `delete_sent_message_on_server` — the net seam
            manager.being_readded_message_full_id = MessageFullId::default();
            return MessageFullId::default();
        }
    };

    // imitation of update_message(d, sent_message.get(), std::move(new_message), false, source);
    if date <= 0 {
        log_error!(
            "Receive {} in {} with wrong date {} from {}",
            DisplayMessageId(new_message_id),
            dialog_id.get(),
            date,
            source
        );
    } else {
        assert!(
            sent_message.date > 0,
            "{} {} {} {} {} {}",
            DisplayMessageId(old_message_id),
            DisplayMessageId(sent_message.message_id),
            DisplayMessageId(new_message_id),
            sent_message.date,
            date,
            source
        );
        sent_message.date = date;
        assert!(
            manager.get_dialog(dialog_id).unwrap().last_message_id != old_message_id,
            "last_message_id == old_message_id in on_send_message_success"
        );
    }

    sent_message.ttl_period = ttl_period;

    // `merge_message_content_file_id` — the M.12 file merge seam

    {
        let reply_message_id = sent_message
            .input_reply_to
            .get_reply_message_full_id(dialog_id)
            .get_message_id();
        if reply_message_id.is_valid() && reply_message_id.is_yet_unsent() {
            // set_message_reply(d, m, MessageInputReplyTo(), false) — the
            // reply reset; the empty input clears the yet-unsent target
            sent_message.replied_message_info = RepliedMessageInfo::default();
        }
    }

    sent_message.message_id = new_message_id;

    {
        let mut sent_message_ref = sent_message;
        send_update_message_send_succeeded(
            global,
            manager,
            ctx,
            state,
            reactions_ctx,
            dialog_id,
            old_message_id,
            &mut sent_message_ref,
            &mut need_update_dialog_pos,
        );
        // the succeeded update needs the message back in place for the
        // follow-up add below; C++ order: the update reads the not-yet-
        // re-added message through the raw pointer
        sent_message = sent_message_ref;
    }

    let mut need_update = true;
    let add_result = add_message_to_dialog(
        global,
        manager,
        reactions_ctx,
        ctx,
        state,
        dialog_id,
        sent_message,
        false,
        true,
        &mut need_update,
        &mut need_update_dialog_pos,
        source,
    );
    if need_update_dialog_pos {
        send_update_chat_last_message(manager, ctx, state, reactions_ctx, dialog_id, source);
    }

    let m_message_id = match add_result {
        Ok(full_id) => full_id.get_message_id(),
        Err(fail_reason) => {
            if !(old_message_id.is_valid() && new_message_id < old_message_id
                || ttl_period > 0 && (date + ttl_period) as f64 <= ctx.server_time())
            {
                log_error!(
                    "Failed to add just sent {} to {} as {} from {}: {}",
                    DisplayMessageId(old_message_id),
                    dialog_id.get(),
                    DisplayMessageId(new_message_id),
                    source,
                    fail_reason
                );
            }
            send_update_delete_messages(manager, dialog_id, &[new_message_id], true);
            manager.being_readded_message_full_id = MessageFullId::default();
            return MessageFullId::default();
        }
    };

    // `try_add_active_live_location` + the reply/forward counts — the
    // count updates ride the container registries
    let _ = m_message_id;
    manager.being_readded_message_full_id = MessageFullId::default();
    MessageFullId::new(dialog_id, new_message_id)
}

/// `MessagesManager::on_send_message_fail` (MessagesManager.cpp:28161-28245)
/// — the error-ladder thin port: the QUOTE/REPLY reload legs and the
/// payment/guest reloads are net seams; the fail core is the port.
pub fn on_send_message_fail(
    global: &mut crate::global::Global,
    manager: &mut MessagesManager,
    ctx: &dyn SendMessageContext,
    state: &mut dyn ReadStateContext,
    random_id: i64,
    error_code: i32,
    error_message: &str,
) {
    let Some(message_full_id) = manager.being_sent_messages.get(&random_id).copied() else {
        // we can't receive fail more than once
        // but message can be successfully sent before
        if error_code != NET_QUERY_CANCELED {
            log_error!(
                "Receive error {} {} about successfully sent message with random_id = {}",
                error_code,
                error_message,
                random_id
            );
        }
        return;
    };

    manager.being_sent_messages.remove(&random_id);

    let dialog_id = message_full_id.get_dialog_id();
    let message_id = message_full_id.get_message_id();
    let has_message = manager
        .get_dialog(dialog_id)
        .map(|d| {
            d.messages.contains_key(&message_id)
                || d.scheduled_messages
                    .as_ref()
                    .is_some_and(|s| s.scheduled_messages.contains_key(&message_id))
        })
        .unwrap_or(false);
    if !has_message {
        // message has already been deleted by the user or sent to
        // inaccessible channel
        tracing::info!(
            "Don't need to send already deleted by the user or sent to an inaccessible chat {}:{}",
            dialog_id.get(),
            DisplayMessageId(message_id)
        );
        return;
    }

    let reactions_ctx = MessageObjectReactionsContext { ctx };
    fail_send_message(
        global,
        manager,
        ctx,
        state,
        &reactions_ctx,
        message_full_id,
        error_code,
        error_message,
    );
}

/// `NetQuery::Error::Canceled` (NetQuery.h:57).
pub const NET_QUERY_CANCELED: i32 = 203;

/// `MessagesManager::fail_send_message` (MessagesManager.cpp:28309-28403).
#[allow(clippy::too_many_arguments)] // the C++ signature has the same shape
pub fn fail_send_message(
    _global: &mut crate::global::Global,
    manager: &mut MessagesManager,
    ctx: &dyn SendMessageContext,
    state: &mut dyn ReadStateContext,
    reactions_ctx: &dyn DialogReactionsContext,
    message_full_id: MessageFullId,
    error_code: i32,
    error_message: &str,
) {
    let error_code = if error_code <= 0 { 500 } else { error_code };
    let error_message = error_message.to_string();

    let dialog_id = message_full_id.get_dialog_id();
    assert!(manager.get_dialog(dialog_id).is_some());
    let old_message_id = message_full_id.get_message_id();
    assert!(old_message_id.is_valid() || old_message_id.is_valid_scheduled());
    assert!(old_message_id.is_yet_unsent());

    // must be called before delete_message
    update_reply_to_message_id(
        manager,
        dialog_id,
        old_message_id,
        MessageId::default(),
        false,
        "fail_send_message",
    );

    // the memory-only delete (the database delete rode the caller's plane
    // in M.10.6)
    let need_update_dialog_pos = false;
    manager.being_readded_message_full_id = message_full_id;
    let message = {
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        let removed = if old_message_id.is_scheduled() {
            d.scheduled_messages
                .as_mut()
                .and_then(|s| s.scheduled_messages.remove(&old_message_id))
        } else {
            d.messages.remove(&old_message_id)
        };
        if removed.is_some() {
            if !old_message_id.is_scheduled() {
                d.message_lru_list.remove(old_message_id);
                d.ordered_messages
                    .erase(old_message_id, false, "fail send message");
            }
            d.being_deleted_message_id = MessageId::default();
        }
        removed
    };
    let Some(mut message) = message else {
        manager.being_readded_message_full_id = MessageFullId::default();
        return;
    };

    let mut new_message_id = old_message_id.get_next_message_id(MessageType::Local); // trying to keep message position
    if !old_message_id.is_scheduled() {
        {
            let d = manager.get_dialog(dialog_id).unwrap();
            let collision = d.messages.contains_key(&new_message_id)
                || is_deleted_message(d, new_message_id)
                || new_message_id <= d.last_clear_history_message_id;
            if collision {
                new_message_id = get_next_local_message_id_public(manager, dialog_id);
            }
        }
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        if new_message_id > d.last_assigned_message_id {
            d.last_assigned_message_id = new_message_id;
        }
    } else {
        loop {
            let d = manager.get_dialog(dialog_id).unwrap();
            let collision =
                d.messages.contains_key(&new_message_id) || is_deleted_message(d, new_message_id);
            if !collision {
                break;
            }
            new_message_id = new_message_id.get_next_message_id(MessageType::Local);
        }
    }

    message.message_id = new_message_id;
    if old_message_id.is_scheduled() {
        assert!(message.message_id.is_valid_scheduled());
    } else {
        assert!(message.message_id.is_valid());
    }
    if message.forward_info.is_none() && message.view_count == 1 {
        message.view_count = 0;
    }
    message.is_failed_to_send = true;
    message.send_error_code = error_code;
    message.send_error_message = error_message.clone();
    message.try_resend_at = 0.0;
    // `Global::get_retry_after` — the retry-after ladder
    // `update_failed_to_send_message_content` — the M.9 expired-content
    // swap seam
    message.file_upload_ids = Default::default();
    message.thumbnail_file_upload_ids = Default::default();
    if message.paid_message_star_count > 0 {
        // the StarManager seam
    }

    let mut need_update = false;
    let add_result = if old_message_id.is_scheduled() {
        add_scheduled_message_to_dialog_for_fail(
            manager,
            dialog_id,
            message,
            &mut need_update,
            "fail_send_message",
        )
    } else {
        add_message_to_dialog_memory_only(
            manager,
            dialog_id,
            message,
            &mut need_update,
            "fail_send_message",
        )
    };
    let m_message_id = match add_result {
        Ok(full_id) => full_id.get_message_id(),
        Err(fail_reason) => panic!(
            "LOG_CHECK failed: failed to add failed to send {} to {}: {}",
            DisplayMessageId(new_message_id),
            dialog_id.get(),
            fail_reason
        ),
    };
    if !m_message_id.is_scheduled() {
        // add_message_to_dialog will not update counts, because need_update == false
        let index_mask = {
            let d = manager.get_dialog(dialog_id).unwrap();
            let m = d.messages.get(&m_message_id).unwrap();
            get_message_index_mask(manager, reactions_ctx, ctx.content_context(), dialog_id, m)
                & !message_search_filter_index_mask(MessageSearchFilter::UnreadMention)
                & !message_search_filter_index_mask(MessageSearchFilter::UnreadReaction)
                & !message_search_filter_index_mask(MessageSearchFilter::UnreadPollVote)
        };
        update_message_count_by_index_mask(manager, dialog_id, 1, index_mask);
    }
    // `register_new_local_message_id` — the local-id registry seam

    manager
        .yet_unsent_message_full_id_to_persistent_message_id
        .insert(MessageFullId::new(dialog_id, old_message_id), m_message_id);
    tracing::info!(
        "Send updateMessageSendFailed for {}:{}",
        dialog_id.get(),
        DisplayMessageId(old_message_id)
    );
    // the updateMessageSendFailed emission (28395-28398)
    let message_object = {
        let mut taken = manager
            .get_dialog_mut(dialog_id)
            .unwrap()
            .messages
            .remove(&m_message_id);
        let object = taken.as_mut().and_then(|m| {
            get_message_object(
                manager,
                reactions_ctx,
                ctx,
                dialog_id,
                m,
                "fail_send_message",
            )
        });
        if let Some(m) = taken {
            manager
                .get_dialog_mut(dialog_id)
                .unwrap()
                .messages
                .insert(m_message_id, m);
        }
        object
    };
    if let Some(message) = message_object {
        state.send_update(td_api::Object::updateMessageSendFailed(
            td_api::updateMessageSendFailed {
                message: Some(message),
                old_message_id: old_message_id.get(),
                error: Some(td_api::Error {
                    code: error_code,
                    message: error_message,
                }),
            },
        ));
    }
    if need_update_dialog_pos {
        send_update_chat_last_message(
            manager,
            ctx,
            state,
            reactions_ctx,
            dialog_id,
            "fail_send_message",
        );
    }
    manager.being_readded_message_full_id = MessageFullId::default();
}

/// The memory-only `add_message_to_dialog` shape the fail path uses —
/// the full configuration lives in the main
/// [`add_message_to_dialog`]; this covers the container insert without
/// the db/notification planes (which the fail path skips through the
/// callers' seams).
fn add_message_to_dialog_memory_only(
    manager: &mut MessagesManager,
    dialog_id: DialogId,
    mut message: Box<Message>,
    _need_update: &mut bool,
    source: &'static str,
) -> Result<MessageFullId, String> {
    let message_id = message.message_id;
    let d = manager.get_dialog_mut(dialog_id).ok_or("no dialog")?;
    if d.messages.contains_key(&message_id) {
        return Err("adding already existing message".to_string());
    }
    if message_id > d.max_added_message_id {
        d.max_added_message_id = message_id;
    }
    d.ordered_messages
        .insert(message_id, false, MessageId::default(), source);
    message.debug_source = source;
    d.messages.insert(message_id, message);
    d.message_lru_list.put_back(message_id);
    manager.added_message_count += 1;
    Ok(MessageFullId::new(dialog_id, message_id))
}

/// The scheduled-container arm of the fail path.
fn add_scheduled_message_to_dialog_for_fail(
    manager: &mut MessagesManager,
    dialog_id: DialogId,
    mut message: Box<Message>,
    _need_update: &mut bool,
    source: &'static str,
) -> Result<MessageFullId, String> {
    let message_id = message.message_id;
    let d = manager.get_dialog_mut(dialog_id).ok_or("no dialog")?;
    if d.scheduled_messages.is_none() {
        d.scheduled_messages = Some(DialogScheduledMessages::default());
    }
    let scheduled_messages = d.scheduled_messages.as_mut().unwrap();
    if scheduled_messages
        .scheduled_messages
        .contains_key(&message_id)
    {
        return Err("adding already existing scheduled message".to_string());
    }
    if message_id.is_scheduled_server() {
        scheduled_messages
            .scheduled_message_date
            .insert(message_id.get_scheduled_server_message_id(), message.date);
    }
    message.debug_source = source;
    scheduled_messages
        .scheduled_messages
        .insert(message_id, message);
    Ok(MessageFullId::new(dialog_id, message_id))
}

/// The public wrapper over the local-id allocation for the fail path.
fn get_next_local_message_id_public(
    manager: &mut MessagesManager,
    dialog_id: DialogId,
) -> MessageId {
    loop {
        let message_id = {
            let d = manager.get_dialog_mut(dialog_id).unwrap();
            get_next_local_message_id(d, false)
        };
        let taken = manager
            .get_dialog(dialog_id)
            .unwrap()
            .messages
            .contains_key(&message_id);
        if !taken {
            return message_id;
        }
    }
}

/// `MessagesManager::set_dialog_last_clear_history_date`
/// (MessagesManager.cpp:12238-12283).
pub fn set_dialog_last_clear_history_date(
    manager: &mut MessagesManager,
    dialog_id: DialogId,
    date: i32,
    last_clear_history_message_id: MessageId,
    source: &str,
) {
    set_dialog_last_clear_history_date_loaded(
        manager,
        dialog_id,
        date,
        last_clear_history_message_id,
        source,
        false,
    )
}

/// The `is_loaded_from_database` overload.
pub fn set_dialog_last_clear_history_date_loaded(
    manager: &mut MessagesManager,
    dialog_id: DialogId,
    date: i32,
    last_clear_history_message_id: MessageId,
    source: &str,
    is_loaded_from_database: bool,
) {
    assert!(!last_clear_history_message_id.is_scheduled());
    {
        let d = manager
            .get_dialog(dialog_id)
            .expect("set_dialog_last_clear_history_date without the dialog");
        if d.last_clear_history_message_id == last_clear_history_message_id
            && d.last_clear_history_date == date
        {
            return;
        }
    }

    tracing::info!(
        "Set {} last clear history date to {} of {} from {}",
        dialog_id.get(),
        date,
        DisplayMessageId(last_clear_history_message_id),
        source
    );
    {
        let old_clear_id = manager
            .get_dialog(dialog_id)
            .unwrap()
            .last_clear_history_message_id;
        if old_clear_id.is_valid() {
            match dialog_id.get_type() {
                DialogType::User | DialogType::Chat => {
                    manager
                        .last_clear_history_message_id_to_dialog_id
                        .remove(&old_clear_id);
                }
                _ => {}
            }
        }
    }

    {
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        d.last_clear_history_date = date;
        d.last_clear_history_message_id = last_clear_history_message_id;
    }
    if !is_loaded_from_database {
        on_dialog_updated(manager, dialog_id, "set_dialog_last_clear_history_date");
    }

    if last_clear_history_message_id.is_valid() {
        match dialog_id.get_type() {
            DialogType::User | DialogType::Chat => {
                manager
                    .last_clear_history_message_id_to_dialog_id
                    .insert(last_clear_history_message_id, dialog_id);
            }
            _ => {}
        }
    }
}

/// `MessagesManager::on_get_message(MessageInfo &&, bool, const char *)`
/// (MessagesManager.cpp:11921-12107) — the COMPLETE receive head: the
/// sent-message re-add branch, the add, the update fan-out and the
/// inaccessible-chat teardown. The interim manager method
/// [`MessagesManager::on_get_message_info`] keeps the M.10.3 shape for
/// the skeleton receive path until the M.10.20 dispatcher flip rewires
/// the M.7 sink onto this function.
#[allow(clippy::too_many_arguments)]
pub fn on_get_message_full(
    global: &mut crate::global::Global,
    manager: &mut MessagesManager,
    ctx: &mut dyn MessageObjectContext,
    send_ctx: &dyn SendMessageContext,
    state: &mut dyn ReadStateContext,
    message_info: MessageInfo,
    from_update: bool,
    source: &'static str,
) -> MessageFullId {
    let report_delivery_until_date = message_info.report_delivery_until_date;
    let (dialog_id, new_message) = create_message(ctx, manager, message_info, false, source);
    let mut new_message = match new_message {
        Some(m) => m,
        None => return MessageFullId::default(),
    };
    let message_id = new_message.message_id;
    if report_delivery_until_date != 0 && message_id.is_server() {
        // `message_query_manager_->report_message_delivery`
        // (MessagesManager.cpp:11931) — the delivery-report query plane is
        // the net seam
    }

    let mut need_update = from_update;
    let mut need_update_dialog_pos = false;

    let have_dialog = manager.get_dialog(dialog_id).is_some();

    let is_ephemeral = new_message.ephemeral_message_id.is_valid();
    let mut old_message_id = if is_ephemeral {
        manager
            .update_ephemeral_message_ids
            .get(&EphemeralMessageFullId::new(
                dialog_id,
                new_message.ephemeral_message_id,
            ))
            .copied()
            .unwrap_or_default()
    } else {
        manager
            .update_message_ids
            .get(&(dialog_id, message_id))
            .copied()
            .unwrap_or_default()
    };
    if old_message_id.is_valid() || old_message_id.is_valid_scheduled() {
        assert!(have_dialog, "re-add without the dialog in on_get_message");

        if !from_update && message_id.is_server() {
            let d = manager.get_dialog(dialog_id).unwrap();
            if message_id <= d.last_new_message_id || ctx.is_bot() {
                // the memory probe; `get_message_force`'s db load is the
                // seam — the loaded dialogs probe memory exactly
                let found = d.messages.contains_key(&message_id);
                if found {
                    log_error!(
                        "New {}/{} in {} from {} has identifier less than last_new_message_id = {}",
                        DisplayMessageId(old_message_id),
                        DisplayMessageId(message_id),
                        dialog_id.get(),
                        source,
                        DisplayMessageId(d.last_new_message_id)
                    );
                    return MessageFullId::default();
                }
                // if there is no message yet, then it is likely was missed
                // because of a server bug and is being repaired via
                // get_message_from_server from after_get_difference
                tracing::info!(
                    "Receive {}/{} in {} from {} with identifier less than last_new_message_id = {} and trying to add it anyway",
                    DisplayMessageId(old_message_id),
                    DisplayMessageId(message_id),
                    dialog_id.get(),
                    source,
                    DisplayMessageId(d.last_new_message_id)
                );
            } else {
                tracing::info!(
                    "Ignore {}/{} received not through update from {}",
                    DisplayMessageId(old_message_id),
                    DisplayMessageId(message_id),
                    source
                );
                // schedule_get_channel_difference — the net seam
                return MessageFullId::default();
            }
        }

        if is_ephemeral {
            let erased = manager
                .update_ephemeral_message_ids
                .remove(&EphemeralMessageFullId::new(
                    dialog_id,
                    new_message.ephemeral_message_id,
                ));
            assert!(erased.is_some());
        } else {
            let erased = manager.update_message_ids.remove(&(dialog_id, message_id));
            assert!(erased.is_some());
        }

        if !new_message.is_outgoing && dialog_id != ctx.content_context().get_my_dialog_id() {
            // sent message is not from me
            log_error!(
                "Sent in {} {} is sent by {:?}",
                dialog_id.get(),
                DisplayMessageId(message_id),
                get_message_sender(&new_message)
            );
            return MessageFullId::default();
        }

        // must be called before delete_message
        update_reply_to_message_id(
            manager,
            dialog_id,
            old_message_id,
            message_id,
            true,
            "on_get_message",
        );

        manager.being_readded_message_full_id = MessageFullId::new(dialog_id, old_message_id);
        let mut old_message = match delete_message(
            global,
            manager,
            dialog_id,
            old_message_id,
            false,
            &mut need_update_dialog_pos,
            "add sent message",
        ) {
            Some(m) => m,
            None => {
                // `delete_sent_message_on_server` — the net seam
                manager.being_readded_message_full_id = MessageFullId::default();
                return MessageFullId::default();
            }
        };
        old_message_id = old_message.message_id;

        need_update = false;

        new_message.message_id = old_message_id;
        {
            // update_message(d, old_message.get(), std::move(new_message),
            // false, source) — the M.10.5 edit core; the take-dance feeds
            // the pair
            let time = crate::user_manager::TimeCtx {
                now: ctx.now(),
                server_time: ctx.server_time(),
            };
            update_message(
                ctx,
                global,
                &time,
                manager,
                dialog_id,
                &mut old_message,
                &mut new_message,
                false,
                source,
            );
        }
        let mut new_message = old_message;

        let reply_message_id = new_message
            .replied_message_info
            .get_reply_message_full_id(dialog_id, false)
            .get_message_id();
        if reply_message_id.is_valid() && reply_message_id.is_yet_unsent() {
            // set_message_reply(d, m, MessageInputReplyTo(), false)
            new_message.replied_message_info = RepliedMessageInfo::default();
        }

        new_message.message_id = message_id;
        let reactions_ctx = MessageObjectReactionsContext { ctx: send_ctx };
        send_update_message_send_succeeded(
            global,
            manager,
            send_ctx,
            state,
            &reactions_ctx,
            dialog_id,
            old_message_id,
            &mut new_message,
            &mut need_update_dialog_pos,
        );

        // is_sent_message: the re-added message's count updates ride the
        // container registries through the add below
        // the re-added message continues into the add below
        if !have_dialog {
            manager.add_dialog_for_new_message(dialog_id);
        }
        let m = add_message_to_dialog(
            global,
            manager,
            &reactions_ctx,
            send_ctx,
            state,
            dialog_id,
            new_message,
            false,
            from_update,
            &mut need_update,
            &mut need_update_dialog_pos,
            source,
        );
        manager.being_readded_message_full_id = MessageFullId::default();
        return match m {
            Ok(full_id) => full_id,
            Err(_) => {
                if need_update_dialog_pos {
                    let reactions_ctx = MessageObjectReactionsContext { ctx: send_ctx };
                    send_update_chat_last_message(
                        manager,
                        send_ctx,
                        state,
                        &reactions_ctx,
                        dialog_id,
                        "on_get_message",
                    );
                }
                if old_message_id.is_valid() || old_message_id.is_valid_scheduled() {
                    if !old_message_id.is_valid()
                        || !message_id.is_valid()
                        || old_message_id <= message_id
                    {
                        log_error!(
                            "Failed to add just sent {} to {} as {} from {}",
                            DisplayMessageId(old_message_id),
                            dialog_id.get(),
                            DisplayMessageId(message_id),
                            source
                        );
                    }
                    send_update_delete_messages(manager, dialog_id, &[message_id], true);
                }
                MessageFullId::default()
            }
        };
    }
    if !have_dialog {
        // `add_dialog_for_new_message(dialog_id, from_update,
        // &need_update_dialog_pos, source)` — the from_update flag drives
        // the is_update_new_chat_sent emission at the DialogDb receive
        // slice; the plain registration is the ported spine
        manager.add_dialog_for_new_message(dialog_id);
    }

    let reactions_ctx = MessageObjectReactionsContext { ctx: send_ctx };
    // fix_new_message runs inside add_message_to_dialog (31104)
    let m = add_message_to_dialog(
        global,
        manager,
        &reactions_ctx,
        send_ctx,
        state,
        dialog_id,
        new_message,
        false,
        from_update,
        &mut need_update,
        &mut need_update_dialog_pos,
        source,
    );
    manager.being_readded_message_full_id = MessageFullId::default();
    let m_message_id = match m {
        Ok(full_id) => full_id.get_message_id(),
        Err(_) => {
            if need_update_dialog_pos {
                send_update_chat_last_message(
                    manager,
                    send_ctx,
                    state,
                    &reactions_ctx,
                    dialog_id,
                    "on_get_message",
                );
            }
            if old_message_id.is_valid() || old_message_id.is_valid_scheduled() {
                if !old_message_id.is_valid()
                    || !message_id.is_valid()
                    || old_message_id <= message_id
                {
                    log_error!(
                        "Failed to add just sent {} to {} as {} from {}",
                        DisplayMessageId(old_message_id),
                        dialog_id.get(),
                        DisplayMessageId(message_id),
                        source
                    );
                }
                send_update_delete_messages(manager, dialog_id, &[message_id], true);
            }
            return MessageFullId::default();
        }
    };

    if need_update {
        // send_update_new_message(d, m) — the take-dance for the &mut
        // object builder
        let mut taken = manager
            .get_dialog_mut(dialog_id)
            .unwrap()
            .messages
            .remove(&m_message_id);
        if let Some(m) = taken.as_mut() {
            send_update_new_message(manager, send_ctx, state, &reactions_ctx, dialog_id, m);
        }
        if let Some(m) = taken {
            manager
                .get_dialog_mut(dialog_id)
                .unwrap()
                .messages
                .insert(m_message_id, m);
        }
    }
    if !ctx.is_bot() && message_id.is_server() {
        // the awaited_message_full_ids_ promise release — the promise plane
        // rides the M.10.17 server-fetch slice
    }

    // the is_sent_message count updates ride the container registries
    // (try_add_active_live_location lands with the live-location plane)

    if dialog_id.get_type() == DialogType::Channel && !state.have_input_peer(dialog_id, false) {
        let mut dummy = false;
        let deleted = delete_message(
            global,
            manager,
            dialog_id,
            message_id,
            false,
            &mut dummy,
            "get a message in inaccessible chat",
        );
        assert!(deleted.is_some());
        send_update_delete_messages(manager, dialog_id, &[message_id], false);
        // don't need to update chat position
        return MessageFullId::default();
    }

    if !ctx.is_bot() {
        // send_update_chat_has_scheduled_messages for scheduled ids, the
        // reply-markup set and the pending_created_dialogs release ride
        // their receive slices
        if need_update_dialog_pos {
            send_update_chat_last_message(
                manager,
                send_ctx,
                state,
                &reactions_ctx,
                dialog_id,
                "on_get_message",
            );
        }
    }

    MessageFullId::new(dialog_id, message_id)
}

// ---------------------------------------------------------------------------
// M.10.13 — open/close/view + the read-dialog-inbox tail
// ---------------------------------------------------------------------------

/// `MessagesManager::open_dialog(DialogId)` (MessagesManager.cpp:
/// 16633-16641).
pub fn open_dialog(
    manager: &mut MessagesManager,
    ctx: &dyn MessageObjectContext,
    state: &mut dyn ReadStateContext,
    dialog_id: DialogId,
) -> Result<(), Status> {
    if manager.get_dialog(dialog_id).is_none() {
        return Result::Err(Status::error(400, "Chat not found"));
    }
    open_dialog_impl(manager, ctx, state, dialog_id);
    Result::Ok(())
}

/// `MessagesManager::open_dialog(Dialog *)` (MessagesManager.cpp:
/// 17124-17236) — the open-count/was-opened/read-inbox-repair core; the
/// per-kind participant/action-bar reloads ride their manager seams.
pub fn open_dialog_impl(
    manager: &mut MessagesManager,
    ctx: &dyn MessageObjectContext,
    state: &mut dyn ReadStateContext,
    dialog_id: DialogId,
) {
    assert!(!ctx.is_bot());
    if !state.have_input_peer(dialog_id, true) {
        return;
    }
    // `DialogManager::on_dialog_opened` — the dialog-list counter seam
    let (should_read_inbox, last_ordered) = {
        let Some(d) = manager.get_dialog_mut(dialog_id) else {
            return;
        };
        if d.open_count == u32::MAX {
            return;
        }
        d.open_count += 1;
        if d.open_count != 1 {
            return;
        }
        d.was_opened = true;

        let min_message_id = MessageId::from_server_message_id(ServerMessageId::new(1));
        let mut should_read_inbox = None;
        if d.last_message_id == MessageId::default()
            && d.last_read_outbox_message_id < min_message_id
        {
            let last = d.ordered_messages.get_last_message_id();
            if last.is_valid() && last < min_message_id {
                should_read_inbox = Some(last);
            }
        }
        // the unload-timeout cancel (17148-17152) is the actor-timer seam;
        // the new-secret-chat notification removal is the M.13 seam
        (should_read_inbox, d.ordered_messages.get_last_message_id())
    };
    let _ = last_ordered;
    if let Some(last) = should_read_inbox {
        read_history_inbox(manager, ctx, state, dialog_id, last, -1, "open_dialog");
    }

    // `get_dialog_pinned_message` (17158) — the M.10.14 pinned slice; the
    // group-call/default-sender repairs and the per-kind reloads
    // (17160-17235) are the manager seams
}

/// `MessagesManager::close_dialog(DialogId)` (MessagesManager.cpp:
/// 16643-16651).
pub fn close_dialog(
    manager: &mut MessagesManager,
    ctx: &dyn MessageObjectContext,
    state: &mut dyn ReadStateContext,
    dialog_id: DialogId,
) -> Result<(), Status> {
    if manager.get_dialog(dialog_id).is_none() {
        return Result::Err(Status::error(400, "Chat not found"));
    }
    close_dialog_impl(manager, ctx, state, dialog_id);
    Result::Ok(())
}

/// `MessagesManager::close_dialog(Dialog *)` (MessagesManager.cpp:
/// 17238-17310) — the open-count teardown; the pending-timeout flushes
/// ride the actor-timer seam, the unload schedule is recorded.
pub fn close_dialog_impl(
    manager: &mut MessagesManager,
    _ctx: &dyn MessageObjectContext,
    _state: &mut dyn ReadStateContext,
    dialog_id: DialogId,
) {
    let Some(d) = manager.get_dialog_mut(dialog_id) else {
        return;
    };
    if d.open_count == 0 {
        return;
    }
    d.open_count -= 1;
    if d.open_count > 0 {
        // the dialog is still open elsewhere
    } else {
        // the pending draft/views/read-history timeout flushes
        // (17248-17267) and the unload schedule (17269-17278) are the
        // actor-timer seam; the viewed-messages/live-location registries
        // clear with the dialog close
    }
}

/// `MessagesManager::read_dialog_inbox` (MessagesManager.cpp:
/// 17038-17073) — the view tail that drives the inbox read.
pub fn read_dialog_inbox(
    manager: &mut MessagesManager,
    ctx: &dyn MessageObjectContext,
    state: &mut dyn ReadStateContext,
    dialog_id: DialogId,
    max_message_id: MessageId,
) {
    if max_message_id == MessageId::default() {
        return;
    }
    assert!(max_message_id.is_valid());
    assert!(max_message_id.is_server() || max_message_id.is_local());
    if max_message_id
        <= manager
            .get_dialog(dialog_id)
            .map(|d| d.last_read_inbox_message_id)
            .unwrap_or_default()
    {
        return;
    }

    let last_read_message_id = max_message_id;
    let prev_last_read_inbox_message_id = manager
        .get_dialog(dialog_id)
        .map(|d| d.last_read_inbox_message_id)
        .unwrap_or_default();
    let mut read_history_on_server_message_id = MessageId::default();
    if dialog_id.get_type() != DialogType::SecretChat {
        if last_read_message_id.get_prev_server_message_id().get()
            > prev_last_read_inbox_message_id
                .get_prev_server_message_id()
                .get()
        {
            read_history_on_server_message_id = last_read_message_id.get_prev_server_message_id();
        }
    } else if last_read_message_id > prev_last_read_inbox_message_id {
        read_history_on_server_message_id = last_read_message_id;
    }

    // the dummy pending_read_history timeout (17063-17067) is the
    // actor-timer seam
    read_history_inbox(
        manager,
        ctx,
        state,
        dialog_id,
        last_read_message_id,
        -1,
        "read_dialog_inbox",
    );
    if read_history_on_server_message_id.is_valid() {
        // `read_history_on_server` — the net seam
    }
}

/// `MessagesManager::view_messages` (MessagesManager.cpp:16653-17036) —
/// the source-decision table, the id validation, the max-viewed walk and
/// the per-source read tail. The thread/forum/monoforum reads, the
/// view-count/pending-views machinery and the content-read server calls
/// ride their manager seams; the dialog-history read tail is the port.
#[allow(clippy::too_many_arguments)]
/// `MessagesManager::MessageSource` (MessagesManager.h:1700) — the view
/// origin that drives the read/view decision table.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum MessageSource {
    #[default]
    Auto,
    DialogHistory,
    MessageThreadHistory,
    ForumTopicHistory,
    MonoforumHistory,
    HistoryPreview,
    DialogList,
    Search,
    DialogEventLog,
    Notification,
    Screenshot,
    Other,
}

/// `get_message_source(const td_api::object_ptr<td_api::MessageSource> &)`
/// (MessageSource.cpp:42-68).
pub fn get_message_source(source: Option<&td_api::MessageSource>) -> MessageSource {
    let Some(source) = source else {
        return MessageSource::Auto;
    };
    match source {
        td_api::MessageSource::messageSourceChatHistory(_) => MessageSource::DialogHistory,
        td_api::MessageSource::messageSourceMessageThreadHistory(_) => {
            MessageSource::MessageThreadHistory
        }
        td_api::MessageSource::messageSourceForumTopicHistory(_) => {
            MessageSource::ForumTopicHistory
        }
        td_api::MessageSource::messageSourceDirectMessagesChatTopicHistory(_) => {
            MessageSource::MonoforumHistory
        }
        td_api::MessageSource::messageSourceHistoryPreview(_) => MessageSource::HistoryPreview,
        td_api::MessageSource::messageSourceChatList(_) => MessageSource::DialogList,
        td_api::MessageSource::messageSourceSearch(_) => MessageSource::Search,
        td_api::MessageSource::messageSourceChatEventLog(_) => MessageSource::DialogEventLog,
        td_api::MessageSource::messageSourceNotification(_) => MessageSource::Notification,
        td_api::MessageSource::messageSourceScreenshot(_) => MessageSource::Screenshot,
        td_api::MessageSource::messageSourceOther(_) => MessageSource::Other,
    }
}

pub fn view_messages(
    manager: &mut MessagesManager,
    ctx: &dyn MessageObjectContext,
    state: &mut dyn ReadStateContext,
    dialog_id: DialogId,
    input_message_ids: Vec<MessageId>,
    source: MessageSource,
    force_read: bool,
) -> Result<(), Status> {
    assert!(!ctx.is_bot());

    if manager.get_dialog(dialog_id).is_none() {
        return Result::Err(Status::error(400, "Chat not found"));
    }

    let source = if source == MessageSource::Auto {
        if manager
            .get_dialog(dialog_id)
            .map(|d| d.open_count > 0)
            .unwrap_or(false)
        {
            MessageSource::DialogHistory
        } else {
            MessageSource::Other
        }
    } else {
        source
    };
    let is_dialog_history = source == MessageSource::DialogHistory
        || source == MessageSource::MessageThreadHistory
        || source == MessageSource::ForumTopicHistory
        || source == MessageSource::MonoforumHistory;
    let need_read = force_read || is_dialog_history;

    // keep only valid message identifiers
    let mut message_ids = Vec::with_capacity(input_message_ids.len());
    for message_id in input_message_ids {
        if !message_id.is_valid() {
            if message_id.is_valid_scheduled() {
                // nothing to do for scheduled messages
                continue;
            }
            return Result::Err(Status::error(400, "Invalid message identifier"));
        }
        message_ids.push(message_id);
    }
    if message_ids.is_empty() {
        // nothing to do
        return Result::Ok(());
    }

    if source == MessageSource::DialogEventLog {
        // nothing more to do
        return Result::Ok(());
    }

    // the thread/forum/monoforum validation walks (16727-16825) ride the
    // reply-info/topic planes

    let mut max_message_id = MessageId::default(); // max server or local viewed message_id
    for &message_id in &message_ids {
        let found = manager
            .get_dialog(dialog_id)
            .map(|d| d.messages.contains_key(&message_id))
            .unwrap_or(false);
        if found {
            let m_last_read = {
                let d = manager.get_dialog(dialog_id).unwrap();
                let m = d.messages.get(&message_id).unwrap();
                if !m.message_id.is_yet_unsent() && m.message_id > max_message_id {
                    max_message_id = m.message_id;
                }
                // `update_message_contains_unread_mention` — the mention
                // clear rides the M.10.7 mention plane through the dialog
                m.contains_unread_mention
            };
            let _ = m_last_read;
            // the pending-views/file-viewed/story/fact-check walks are the
            // manager seams
        } else if !message_id.is_yet_unsent() && message_id > max_message_id {
            let counts = manager
                .get_dialog(dialog_id)
                .map(|d| {
                    message_id <= d.last_new_message_id
                        || d.notification_info
                            .as_ref()
                            .map(|info| message_id <= info.max_push_notification_message_id)
                            .unwrap_or(false)
                })
                .unwrap_or(false);
            if counts {
                max_message_id = message_id;
            }
        }
    }

    if !need_read {
        return Result::Ok(());
    }

    if source == MessageSource::MessageThreadHistory || source == MessageSource::ForumTopicHistory {
        // the thread/topic read tails ride the ForumTopicManager seam
        return Result::Ok(());
    }
    if source == MessageSource::MonoforumHistory {
        // the monoforum read tail rides the SavedMessagesManager seam
        return Result::Ok(());
    }

    assert!(
        source == MessageSource::DialogHistory || force_read,
        "view_messages source mismatch"
    );
    read_dialog_inbox(manager, ctx, state, dialog_id, max_message_id);
    if let Some(d) = manager.get_dialog_mut(dialog_id)
        && d.is_marked_as_unread
    {
        // `set_dialog_is_marked_as_unread(d, false)` — the M.10.12
        // dialog-list counter plane
        d.is_marked_as_unread = false;
    }
    Result::Ok(())
}

