    /// M.10 D1 cross-read, direction C++→Rust: a binlog written by the C++
    /// probe (`conformance/cpp/delete_message_log_event_sample.cpp` over
    /// the real `TlStorerUnsafe`/`MessageFullId` stores + the
    /// `LogEventStorer` version word) parses through the version-prefixed
    /// log-event reader. Regenerate the fixture with the probe when the
    /// C++ layout changes.
    #[test]
    fn d1_delete_message_cpp_binlog_cross_read() {
        let path = format!(
            "{}/src/testdata/d1_delete_message_cpp.binlog",
            env!("CARGO_MANIFEST_DIR")
        );
        let mut binlog = tddb::binlog::Binlog::new();
        let mut events = Vec::new();
        binlog
            .init(
                &path,
                &mut |event: &tddb::binlog::BinlogEvent| {
                    events.push((event.id, event.type_, event.get_data().to_vec()))
                },
                tddb::DbKey::empty(),
                tddb::DbKey::empty(),
            )
            .ensure();
        binlog.close(false).ensure();

        let deletes: Vec<(u64, Vec<u8>)> = events
            .into_iter()
            .filter(|(_, type_, _)| *type_ == tddb::td_db::LOG_EVENT_HANDLER_TYPE_DELETE_MESSAGE)
            .map(|(id, _, data)| (id, data))
            .collect();
        assert_eq!(deletes.len(), 3, "the three probe events");

        // the user-dialog delete with two file ids: the version word, the
        // flag, the raw dialog id 9 and the packed server id 4242 << 20
        let first = DeleteMessageLogEvent::parse_from(&deletes[0].1).unwrap();
        assert_eq!(deletes[0].0, 1);
        assert_eq!(
            first.message_full_id,
            MessageFullId::new(
                DialogId::from_user_id(UserId::new(9)),
                MessageId::from_server_message_id(ServerMessageId::new(4242))
            )
        );
        assert_eq!(first.file_ids.len(), 2);
        assert_eq!(first.file_ids[0].get(), 7);
        assert_eq!(first.file_ids[1].get(), 8);
        // the version word the C++ LogEventStorer writes
        assert_eq!(
            i32::from_le_bytes(deletes[0].1[0..4].try_into().unwrap()),
            crate::store_parse::version::LOG_EVENT_STORE_VERSION
        );

        // the chat-dialog delete with no files: the -77 packing
        let second = DeleteMessageLogEvent::parse_from(&deletes[1].1).unwrap();
        assert_eq!(
            second.message_full_id,
            MessageFullId::new(
                DialogId::from_chat_id(ChatId::new(77)),
                MessageId::from_server_message_id(ServerMessageId::new(17))
            )
        );
        assert!(second.file_ids.is_empty());

        // the default-id delete with one file
        let third = DeleteMessageLogEvent::parse_from(&deletes[2].1).unwrap();
        assert_eq!(
            third.message_full_id,
            MessageFullId::new(DialogId::from_user_id(UserId::new(9)), MessageId::default())
        );
        assert_eq!(third.file_ids.len(), 1);
        assert_eq!(third.file_ids[0].get(), 5);
    }

    #[test]
    #[allow(clippy::field_reassign_with_default)]
    fn index_mask_decision_table() {
        let mut m = Message::default();
        m.message_id = MessageId::from_server_message_id(ServerMessageId::new(1));
        m.content = Some(crate::message_content::MessageContent::Text(
            crate::message_content::MessageText::default(),
        ));

        let manager = MessagesManager::default();

        // yet-unsent messages are never indexed
        m.message_id = MessageId::min(); // a yet-unsent id
        assert_eq!(
            get_message_index_mask(
                &manager,
                &NoDialogReactionsContext,
                &crate::message_content::SharedTestContext::default(),
                DialogId::from_user_id(UserId::new(1)),
                &m
            ),
            0
        );
        // failed-to-send messages carry only the FailedToSend bit
        m.message_id = MessageId::from_server_message_id(ServerMessageId::new(2));
        m.is_failed_to_send = true;
        assert_eq!(
            get_message_index_mask(
                &manager,
                &NoDialogReactionsContext,
                &crate::message_content::SharedTestContext::default(),
                DialogId::from_user_id(UserId::new(1)),
                &m
            ),
            message_search_filter_index_mask(MessageSearchFilter::FailedToSend)
        );
        // pinned + secret content collapses to the pinned bit alone
        m.is_failed_to_send = false;
        m.is_pinned = true;
        m.is_content_secret = true;
        assert_eq!(
            get_message_index_mask(
                &manager,
                &NoDialogReactionsContext,
                &crate::message_content::SharedTestContext::default(),
                DialogId::from_user_id(UserId::new(1)),
                &m
            ),
            message_search_filter_index_mask(MessageSearchFilter::Pinned)
        );
    }

    #[test]
    #[allow(clippy::field_reassign_with_default)]
    fn parse_message_validates_the_expected_id() {
        let time = crate::user_manager::TimeCtx {
            now: 0.0,
            server_time: 0.0,
        };
        let mut m = Message::default();
        m.message_id = MessageId::from_server_message_id(ServerMessageId::new(10));
        m.date = 5;
        m.content = Some(crate::message_content::MessageContent::Text(
            crate::message_content::MessageText::default(),
        ));
        let mut bytes = Vec::new();
        store_message_log_event(&m, &MessageDbStorageBridge, &time, &mut bytes);

        // exact match
        let parsed = parse_message(&time, m.message_id, &bytes, false).unwrap();
        assert_eq!(parsed.message_id, m.message_id);
        // mismatched id is dropped
        assert!(
            parse_message(
                &time,
                MessageId::from_server_message_id(ServerMessageId::new(11)),
                &bytes,
                false
            )
            .is_none()
        );
        // a scheduled expectation over an ordinary id is dropped
        assert!(parse_message(&time, MessageId::default(), &bytes, true).is_none());
        // a corrupt blob is dropped
        assert!(parse_message(&time, m.message_id, &bytes[..bytes.len() - 1], false).is_none());
    }

    #[test]
    fn message_reactions_store_parse_roundtrip() {
        let reactions = MessageReactions {
            reactions: vec![MessageReaction {
                reaction_type: ReactionType::new("👍"),
                choose_count: 5,
                is_chosen: true,
                my_recent_chooser_dialog_id: DialogId::from_user_id(UserId::new(1)),
                recent_chooser_dialog_ids: vec![DialogId::from_user_id(UserId::new(1))],
                recent_chooser_min_channels: Vec::new(),
            }],
            unread_reactions: vec![UnreadMessageReaction {
                reaction_type: ReactionType::new("🔥"),
                sender_dialog_id: DialogId::from_user_id(UserId::new(2)),
                is_big: true,
            }],
            chosen_reaction_order: vec![ReactionType::new("👍")],
            top_reactors: vec![MessageReactor {
                dialog_id: DialogId::from_user_id(UserId::new(3)),
                min_channel: Some(MinChannel {
                    title: "top".to_string(),
                    is_megagroup: false,
                }),
                count: 7,
                is_top: true,
                is_me: false,
                is_anonymous: false,
            }],
            pending_paid_reactions: 0,
            is_min: false,
            need_polling: true,
            can_get_added_reactions: false,
            are_tags: false,
        };
        let mut bytes = Vec::new();
        reactions.store(&mut bytes);
        let mut parser = Parser::new(&bytes);
        assert_eq!(
            MessageReactions::parse_from(&mut parser).unwrap(),
            reactions
        );
        assert!(!reactions.are_empty());
        assert!(MessageReactions::default().are_empty());

        // the my-recent-chooser validity rule: a chooser not in the recent
        // list is an error
        let bad = MessageReaction {
            reaction_type: ReactionType::new("👍"),
            choose_count: 2,
            is_chosen: false,
            my_recent_chooser_dialog_id: DialogId::from_user_id(UserId::new(9)),
            recent_chooser_dialog_ids: vec![DialogId::from_user_id(UserId::new(1))],
            recent_chooser_min_channels: Vec::new(),
        };
        let mut bytes = Vec::new();
        bad.store(&mut bytes);
        let mut parser = Parser::new(&bytes);
        assert!(MessageReaction::parse_from(&mut parser).is_err());
    }

