    /// The M.10.5 Verify pipeline, offline part: a recorded
    /// `updateEditMessage` shape — the re-intake of the full edited message
    /// (MessagesManager.cpp:5853-5858) — followed by the update_message
    /// edit core replaces the content and applies the edit flags.
    #[test]
    fn m10_5_update_edit_message_corpus_edits_the_message() {
        let dialog_id = DialogId::from_user_id(UserId::new(2000));
        let wire = |text: &str, edit_date: i32| {
            telegram_api::Message::message(telegram_api::message {
                id: 400,
                peer_id: Some(telegram_api::Peer::peerUser(telegram_api::peerUser {
                    user_id: 2000,
                })),
                date: 1700000100,
                edit_date,
                message: text.to_string(),
                ..Default::default()
            })
        };
        let mut manager = MessagesManager::default();
        let mut ctx = TestObjectContext::default();
        let (_, mut old_message) = manager
            .on_get_message(&mut ctx, wire("v1", 0), true, false, "updateNewMessage")
            .unwrap();
        // the edited shape re-enters through the same intake; the C++ arm
        // passes from_update = false (MessagesManager.cpp:5854)
        let (_, mut new_message) = manager
            .on_get_message(
                &mut ctx,
                wire("v2", 1700000200),
                false,
                false,
                "updateEditMessage",
            )
            .unwrap();
        let global = crate::global::Global::new();
        let time = crate::user_manager::TimeCtx::from_global(&global);

        let outcome = update_message(
            &mut ctx,
            &global,
            &time,
            &mut manager,
            dialog_id,
            &mut old_message,
            &mut new_message,
            false,
            "updateEditMessage",
        );
        assert!(outcome.is_edited, "the shown edit date has changed");
        assert!(outcome.need_send_update);
        assert_eq!(old_message.edit_date, 1700000200);
        match old_message.content {
            Some(crate::message_content::MessageContent::Text(text)) => {
                assert_eq!(text.text.text, "v2");
            }
            other => panic!("wrong content arm: {other:?}"),
        }
    }

    /// The edit_date rules (MessagesManager.cpp:32287-32301): the date only
    /// moves forward, a zero edit date is dropped, and `is_edited` fires
    /// only on a shown-edit-date change.
    #[test]
    fn m10_5_edit_date_never_moves_backwards() {
        let dialog_id = DialogId::from_user_id(UserId::new(2000));
        let build = |edit_date: i32| {
            let mut new_message = Box::new(Message::default());
            new_message.message_id = MessageId::from_server_message_id(ServerMessageId::new(400));
            new_message.date = 1700000100;
            new_message.edit_date = edit_date;
            new_message.content = Some(crate::message_content::MessageContent::Text(
                crate::message_content::MessageText::default(),
            ));
            new_message
        };
        let mut ctx = TestObjectContext::default();
        let mut manager = MessagesManager::default();
        let global = crate::global::Global::new();
        let time = crate::user_manager::TimeCtx::from_global(&global);

        let mut old_message = build(1700000300);
        let mut new_message = build(1700000200);
        let outcome = update_message(
            &mut ctx,
            &global,
            &time,
            &mut manager,
            dialog_id,
            &mut old_message,
            &mut new_message,
            false,
            "test",
        );
        assert!(!outcome.is_edited);
        assert!(!outcome.need_send_update);
        assert_eq!(old_message.edit_date, 1700000300, "the date stays");

        // a zero edit date is logged and ignored
        let mut new_message = build(0);
        let outcome = update_message(
            &mut ctx,
            &global,
            &time,
            &mut manager,
            dialog_id,
            &mut old_message,
            &mut new_message,
            false,
            "test",
        );
        assert!(!outcome.is_edited);
        assert_eq!(old_message.edit_date, 1700000300);
    }

    /// The content replace through the M.9.10/M.9.11 machinery: a type
    /// change flags `need_update`, replaces the content and resets
    /// `last_edit_pts` (MessagesManager.cpp:32854-32861).
    #[test]
    fn m10_5_content_type_change_resets_last_edit_pts() {
        let dialog_id = DialogId::from_user_id(UserId::new(2000));
        let mut old_message = Box::new(Message::default());
        old_message.message_id = MessageId::from_server_message_id(ServerMessageId::new(400));
        old_message.date = 1700000100;
        old_message.last_edit_pts = 7;
        old_message.content = Some(crate::message_content::MessageContent::Text(
            crate::message_content::MessageText::default(),
        ));
        let mut new_message = Box::new(Message::default());
        new_message.message_id = old_message.message_id;
        new_message.date = 1700000100;
        new_message.content = Some(crate::message_content::MessageContent::Photo(
            crate::message_content::MessagePhoto::default(),
        ));

        let mut ctx = TestObjectContext::default();
        let mut manager = MessagesManager::default();
        let global = crate::global::Global::new();
        let time = crate::user_manager::TimeCtx::from_global(&global);
        let outcome = update_message(
            &mut ctx,
            &global,
            &time,
            &mut manager,
            dialog_id,
            &mut old_message,
            &mut new_message,
            false,
            "test",
        );
        assert!(outcome.need_send_update, "the content update is flagged");
        assert!(
            !outcome.is_content_changed,
            "the type change rides need_update"
        );
        assert!(matches!(
            old_message.content,
            Some(crate::message_content::MessageContent::Photo(_))
        ));
        assert_eq!(old_message.last_edit_pts, 0, "the edit pts are reset");
    }

    /// `need_message_changed_warning` (MessagesManager.cpp:32813-32833).
    #[test]
    fn m10_5_need_message_changed_warning_table() {
        let base = || Message {
            message_id: MessageId::from_server_message_id(ServerMessageId::new(400)),
            content: Some(crate::message_content::MessageContent::Text(
                crate::message_content::MessageText::default(),
            )),
            ..Default::default()
        };
        assert!(need_message_changed_warning(&base()));

        let mut edited = base();
        edited.edit_date = 1700000200;
        assert!(!need_message_changed_warning(&edited), "already edited");

        let mut yet_unsent_forward = base();
        yet_unsent_forward.message_id = MessageId::new(MessageId::TYPE_YET_UNSENT as i64);
        yet_unsent_forward.real_forward_from_dialog_id = DialogId::from_user_id(UserId::new(5));
        assert!(
            !need_message_changed_warning(&yet_unsent_forward),
            "the original may be edited"
        );

        let mut expiring = base();
        expiring.ttl = MessageSelfDestructType::with_ttl(60, false);
        assert!(!need_message_changed_warning(&expiring), "can expire");

        let mut restricted = base();
        restricted.restriction_reasons = vec![crate::restriction_reason::RestrictionReason::new(
            "ios".to_string(),
            " pornography".to_string(),
            "restricted".to_string(),
        )];
        assert!(!need_message_changed_warning(&restricted));
    }

    /// `on_message_edited` (MessagesManager.cpp:5985-6014): the pts and the
    /// dialog marker land, and the bot branch asks for
    /// `updateMessageEdited`.
    #[test]
    fn m10_5_on_message_edited_sets_pts_and_dialog_marker() {
        let dialog_id = DialogId::from_user_id(UserId::new(2000));
        let mut manager = MessagesManager::default();
        manager.add_dialog_for_new_message(dialog_id);
        let mut m = Message {
            message_id: MessageId::from_server_message_id(ServerMessageId::new(400)),
            ..Default::default()
        };

        let send_edited = on_message_edited(&mut manager, dialog_id, &mut m, 77, false, true);
        assert!(send_edited, "the bot branch emits updateMessageEdited");
        assert_eq!(m.last_edit_pts, 77);
        assert_eq!(
            manager
                .get_dialog(dialog_id)
                .unwrap()
                .last_edited_message_id,
            m.message_id
        );

        let send_edited = on_message_edited(&mut manager, dialog_id, &mut m, 78, false, false);
        assert!(!send_edited, "non-bot edits emit via the is_edited flow");
        assert_eq!(m.last_edit_pts, 78);
    }

    /// A one-shot actor that runs a job inside a scheduler context — the
    /// database engines exist only there (the message_db.rs choreography
    /// pattern).
    struct Job<F>(Option<F>);
    impl<F: FnOnce() + Send + 'static> tdactor::Actor for Job<F> {
        fn start_up(&mut self) {
            if let Some(job) = self.0.take() {
                job();
            }
        }
    }

    fn open_delete_run(dir: &str) -> (crate::global::Global, Vec<tddb::binlog::BinlogEvent>) {
        let opened = tddb::td_db::TdDb::open(tddb::td_db::Parameters {
            database_directory: format!("{}{}", dir, std::path::MAIN_SEPARATOR),
            use_message_database: true,
            use_file_database: true,
            ..Default::default()
        })
        .unwrap();
        let messages_manager_events = opened.messages_manager_events;
        let mut global = crate::global::Global::new();
        global.init(opened.database);
        // mark the database authorized: TdDb::open destroys the sqlite file
        // of a never-authorized run
        global.binlog_pmc().set("auth", "ok");
        (global, messages_manager_events)
    }

    fn store_corpus_row(
        global: &mut crate::global::Global,
        manager: &mut MessagesManager,
        dialog_id: DialogId,
        message_full_id: MessageFullId,
    ) {
        let reactions_ctx = NoDialogReactionsContext;
        let time = crate::user_manager::TimeCtx::from_global(global);
        let m = Message {
            message_id: message_full_id.get_message_id(),
            date: 1700000100,
            sender_user_id: dialog_id.get_user_id(),
            content: Some(crate::message_content::MessageContent::Text(
                crate::message_content::MessageText::default(),
            )),
            ..Default::default()
        };
        add_message_to_database(
            global,
            manager,
            &reactions_ctx,
            &crate::message_content::SharedTestContext::default(),
            &time,
            dialog_id,
            &m,
            "updateNewMessage",
        );
    }

    /// The M.10.6 corpus: a recorded `updateDeleteMessages` shape (two
    /// server ids in one dialog) through `delete_messages_from_updates` —
    /// the ids resolve through the unique-id load, the durable deletes land
    /// through the M.10.2 binlog spine, and the async read confirms the rows
    /// are erased.
    #[test]
    fn m10_6_update_delete_messages_corpus_resolves_and_persists() {
        use std::sync::Arc as StdArc;
        use std::sync::atomic::{AtomicUsize, Ordering as AtomicOrdering};

        let base = std::env::temp_dir().join("m10_6_corpus_run");
        let _ = std::fs::remove_dir_all(&base);
        std::fs::create_dir_all(&base).unwrap();
        let dir = base.canonicalize().unwrap().to_string_lossy().into_owned();
        let done = StdArc::new(AtomicUsize::new(0));
        let rows_gone = StdArc::new(AtomicUsize::new(0));
        let dialog_id = DialogId::from_user_id(UserId::new(2000));
        let id400 = MessageFullId::new(
            dialog_id,
            MessageId::from_server_message_id(ServerMessageId::new(400)),
        );
        let id401 = MessageFullId::new(
            dialog_id,
            MessageId::from_server_message_id(ServerMessageId::new(401)),
        );

        let mut sched = ConcurrentScheduler::new(0);

        // job 1: the rows land durably (the close drains the writes)
        sched.create_actor_unsafe(
            0,
            "StoreRows",
            Job(Some({
                let done = done.clone();
                let dir = dir.clone();
                move || {
                    let (mut global, _) = open_delete_run(&dir);
                    let mut manager = MessagesManager::default();
                    manager.add_dialog_for_new_message(dialog_id);
                    store_corpus_row(&mut global, &mut manager, dialog_id, id400);
                    store_corpus_row(&mut global, &mut manager, dialog_id, id401);
                    let stored = done.clone();
                    global
                        .message_db_async()
                        .close(tdutils::promise::PromiseCreator::lambda(move |()| {
                            stored.store(1, AtomicOrdering::SeqCst);
                        }));
                }
            })),
        );
        sched.start();
        while sched.run_main(30.0) && done.load(AtomicOrdering::SeqCst) == 0 {}
        sched.finish();
        assert_eq!(done.load(AtomicOrdering::SeqCst), 1);

        // job 2: the recorded updateDeleteMessages shape, applied — the ids
        // resolve through the unique-id load, the durable deletes land, and
        // the async reads apply the buffered deletes before reading back
        let mut sched = ConcurrentScheduler::new(0);
        sched.create_actor_unsafe(
            0,
            "ApplyDeletes",
            Job(Some({
                let rows_gone = rows_gone.clone();
                let dir = dir.clone();
                move || {
                    let (mut global, _) = open_delete_run(&dir);
                    let mut manager = MessagesManager::default();
                    manager.add_dialog_for_new_message(dialog_id);

                    let deleted = delete_messages_from_updates(
                        &mut global,
                        &mut manager,
                        &[
                            MessageId::from_server_message_id(ServerMessageId::new(400)),
                            MessageId::from_server_message_id(ServerMessageId::new(401)),
                        ],
                        true,
                    );
                    assert_eq!(
                        deleted,
                        vec![(dialog_id, vec![400 << 20, 401 << 20])],
                        "the per-dialog deleted ids carry the raw message ids"
                    );
                    let recorded400 = manager
                        .get_dialog(dialog_id)
                        .unwrap()
                        .deleted_message_ids
                        .contains(&MessageId::from_server_message_id(ServerMessageId::new(
                            400,
                        )));
                    let recorded401 = manager
                        .get_dialog(dialog_id)
                        .unwrap()
                        .deleted_message_ids
                        .contains(&MessageId::from_server_message_id(ServerMessageId::new(
                            401,
                        )));
                    assert!(
                        recorded400 && recorded401,
                        "the durable deletes re-record the ids on the skeleton"
                    );
                    let gone400 = rows_gone.clone();
                    let gone401 = rows_gone.clone();
                    // the async read applies the buffered deletes first, so
                    // both rows must read back as erased (a missing row
                    // settles the promise with the default, id-invalid)
                    global.message_db_async().get_message(
                        id400,
                        tdutils::promise::PromiseCreator::lambda(
                            move |result: crate::message_db::MessageDbDialogMessage| {
                                assert!(
                                    result.message_id == MessageId::default(),
                                    "the resolved row 400 is erased"
                                );
                                let _ = gone400.fetch_or(1, AtomicOrdering::SeqCst);
                            },
                        ),
                    );
                    global.message_db_async().get_message(
                        id401,
                        tdutils::promise::PromiseCreator::lambda(
                            move |result: crate::message_db::MessageDbDialogMessage| {
                                assert!(
                                    result.message_id == MessageId::default(),
                                    "the resolved row 401 is erased"
                                );
                                let _ = gone401.fetch_or(2, AtomicOrdering::SeqCst);
                                Scheduler::instance().finish();
                            },
                        ),
                    );
                }
            })),
        );
        sched.start();
        while sched.run_main(30.0) && rows_gone.load(AtomicOrdering::SeqCst) != 3 {}
        sched.finish();
        assert_eq!(rows_gone.load(AtomicOrdering::SeqCst), 3);
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// The `update_message_ids_` old-id fan-out
    /// (MessagesManager.cpp:32099-32118): deleting a sent-but-unreceived
    /// message id deletes the registered old id through `delete_messages`
    /// and CHECKs the registry erase.
    #[test]
    fn m10_6_delete_fans_out_to_the_update_registry_old_id() {
        let dialog_id = DialogId::from_user_id(UserId::new(2000));
        let server_id = MessageId::from_server_message_id(ServerMessageId::new(500));
        let old_local_id = MessageId::new(MessageId::TYPE_LOCAL as i64);
        let mut global = crate::global::Global::new();
        let mut manager = MessagesManager::default();
        manager.add_dialog_for_new_message(dialog_id);
        manager
            .update_message_ids
            .insert((dialog_id, server_id), old_local_id);

        delete_message_from_database(
            &mut global,
            &mut manager,
            dialog_id,
            server_id,
            None,
            true,
            "test",
        );

        assert!(
            !manager
                .update_message_ids
                .contains_key(&(dialog_id, server_id)),
            "the registry entry is erased"
        );
        assert!(
            manager
                .get_dialog(dialog_id)
                .unwrap()
                .deleted_message_ids
                .contains(&old_local_id),
            "the old id was deleted through the delete_messages fan-out"
        );
    }

    /// The M.10.6 crash-recovery replay: the durable DeleteMessageLogEvent
    /// lands in the binlog before the row erase can complete (the kill
    /// window); the reopened engine replays the durable event through the
    /// ported DeleteMessage replay arm and the row erase is re-applied.
    /// (TdDb::open's replay callback collects the DeleteMessage events into
    /// the `to_messages_manager` vector — the same events the Td init
    /// replays.)
    #[test]
    fn m10_6_delete_survives_a_mid_delete_kill_via_binlog_replay() {
        use std::sync::Arc as StdArc;
        use std::sync::atomic::{AtomicUsize, Ordering as AtomicOrdering};

        let base = std::env::temp_dir().join("m10_6_delete_run");
        let _ = std::fs::remove_dir_all(&base);
        std::fs::create_dir_all(&base).unwrap();
        let dir = base.canonicalize().unwrap().to_string_lossy().into_owned();
        let row_stored = StdArc::new(AtomicUsize::new(0));
        let rows_gone = StdArc::new(AtomicUsize::new(0));
        let ids_recorded = StdArc::new(AtomicUsize::new(0));
        let dialog_id = DialogId::from_user_id(UserId::new(2000));
        let message_full_id = MessageFullId::new(
            dialog_id,
            MessageId::from_server_message_id(ServerMessageId::new(400)),
        );

        // phase A: the message row lands durably; the delete's durable half
        // (the binlog event) is written and the process "dies" before the
        // row erase completes — the crash window
        let mut sched = ConcurrentScheduler::new(0);
        sched.create_actor_unsafe(
            0,
            "KillMidDelete",
            Job(Some({
                let row_stored = row_stored.clone();
                let dir = dir.clone();
                move || {
                    let (mut global, _) = open_delete_run(&dir);
                    let mut manager = MessagesManager::default();
                    manager.add_dialog_for_new_message(dialog_id);
                    store_corpus_row(&mut global, &mut manager, dialog_id, message_full_id);
                    global.flush_all();

                    // the durable half of do_delete_message_log_event: the
                    // event is in the binlog, the row erase has not run
                    let log_event = DeleteMessageLogEvent {
                        id: 0,
                        message_full_id,
                        file_ids: vec![FileId::new(7, 0)],
                    };
                    let mut data = Vec::new();
                    log_event.store(&mut data);
                    global
                        .td_db()
                        .binlog()
                        .add(LOG_EVENT_HANDLER_TYPE_DELETE_MESSAGE, &data);
                    global.td_db().binlog().force_flush();
                    row_stored.store(1, AtomicOrdering::SeqCst);
                }
            })),
        );
        sched.start();
        while sched.run_main(30.0) && row_stored.load(AtomicOrdering::SeqCst) == 0 {}
        sched.finish();
        assert_eq!(row_stored.load(AtomicOrdering::SeqCst), 1);

        // phase B: reopen — TdDb::open's replay callback collects the durable
        // DeleteMessage events into `messages_manager_events` (the
        // `to_messages_manager` vector), and the ported replay arm — the same
        // loop the Td init runs — re-applies the row erase
        let mut sched = ConcurrentScheduler::new(0);
        sched.create_actor_unsafe(
            0,
            "ReplayDeletes",
            Job(Some({
                let rows_gone = rows_gone.clone();
                let ids_recorded = ids_recorded.clone();
                let dir = dir.clone();
                move || {
                    let (mut global, message_events) = open_delete_run(&dir);
                    let mut manager = MessagesManager::default();
                    manager.add_dialog_for_new_message(dialog_id);
                    let mut replay_count = 0;
                    for event in &message_events {
                        if event.type_ == LOG_EVENT_HANDLER_TYPE_DELETE_MESSAGE {
                            replay_count += 1;
                            replay_delete_message_log_event(&mut global, &mut manager, event);
                        }
                    }
                    assert_eq!(replay_count, 1, "the durable delete event replays");
                    assert!(
                        manager
                            .get_dialog(dialog_id)
                            .unwrap()
                            .deleted_message_ids
                            .contains(&MessageId::from_server_message_id(ServerMessageId::new(
                                400
                            ))),
                        "the replay re-records the deleted id"
                    );

                    // the async read applies the buffered deletes first, so
                    // the row must read back as erased (a missing row settles
                    // the promise with the default, id-invalid) — the corpus
                    // test's read-back shape
                    let gone_flag = rows_gone.clone();
                    let recorded_flag = ids_recorded.clone();
                    global.message_db_async().get_message(
                        message_full_id,
                        tdutils::promise::PromiseCreator::lambda(
                            move |result: crate::message_db::MessageDbDialogMessage| {
                                assert!(
                                    result.message_id == MessageId::default(),
                                    "the replayed delete removed the row"
                                );
                                gone_flag.store(1, AtomicOrdering::SeqCst);
                                recorded_flag.store(1, AtomicOrdering::SeqCst);
                                Scheduler::instance().finish();
                            },
                        ),
                    );
                }
            })),
        );
        sched.start();
        while sched.run_main(30.0) && rows_gone.load(AtomicOrdering::SeqCst) == 0 {}
        sched.finish();
        assert_eq!(rows_gone.load(AtomicOrdering::SeqCst), 1);
        assert_eq!(ids_recorded.load(AtomicOrdering::SeqCst), 1);
        let _ = std::fs::remove_dir_all(&dir);
    }

    // -------------------------------------------------------------------
    // M.10.7 — the read counters + mentions tables
    // -------------------------------------------------------------------

    /// The read-state seam capture: the emitted td_api updates, the fake
    /// `DialogList` counter blocks the walk table applies to (the M.10
    /// dialog-list slice owns the real containers), and the M.13 send log.
    struct ReadStateTestContext {
        updates: Vec<td_api::Object>,
        lists: Vec<DialogListUnreadCounters>,
        muted: bool,
        have_input_peer_answer: bool,
        have_filters: bool,
        unread_message_count_updates: usize,
        unread_chat_count_updates: usize,
        dialog_list_updates: Vec<String>,
        flushed: Vec<(bool, i64)>,
        removed_groups: Vec<(i32, i64, i32, bool)>,
        removed_notifications: Vec<(i32, i32)>,
        pinned_removed: Vec<i64>,
        pmc: HashMap<String, String>,
    }

    impl Default for ReadStateTestContext {
        fn default() -> Self {
            ReadStateTestContext {
                updates: Vec::new(),
                lists: Vec::new(),
                muted: false,
                have_input_peer_answer: true,
                have_filters: false,
                unread_message_count_updates: 0,
                unread_chat_count_updates: 0,
                dialog_list_updates: Vec::new(),
                flushed: Vec::new(),
                removed_groups: Vec::new(),
                removed_notifications: Vec::new(),
                pinned_removed: Vec::new(),
                pmc: HashMap::new(),
            }
        }
    }

    impl ReadStateContext for ReadStateTestContext {
        fn send_update(&mut self, update: td_api::Object) {
            self.updates.push(update);
        }

        fn have_input_peer(&self, _dialog_id: DialogId, _allow_secret_chats: bool) -> bool {
            self.have_input_peer_answer
        }

        fn is_dialog_muted(&self, _dialog_id: DialogId) -> bool {
            self.muted
        }

        fn is_dialog_sponsored(&self, _dialog_id: DialogId) -> bool {
            false
        }

        fn on_unread_count_change(
            &mut self,
            _dialog_id: DialogId,
            old_unread_count: i32,
            new_unread_count: i32,
            is_marked_as_unread: bool,
            _force_update: bool,
            _source: &str,
        ) {
            // the per-list table over the fake list — the exact
            // MessagesManager.cpp:9942-9965 arithmetic via the ported
            // per-list block
            for list in &mut self.lists {
                let (send_message_count, send_chat_count) = list.apply_unread_count_change(
                    old_unread_count,
                    new_unread_count,
                    is_marked_as_unread,
                    self.muted,
                );
                if send_message_count {
                    self.unread_message_count_updates += 1;
                }
                if send_chat_count {
                    self.unread_chat_count_updates += 1;
                }
            }
        }

        fn on_is_marked_as_unread_change(
            &mut self,
            _dialog_id: DialogId,
            delta: i32,
            _source: &str,
        ) {
            for list in &mut self.lists {
                if list.apply_is_marked_as_unread_change(delta, self.muted) {
                    self.unread_chat_count_updates += 1;
                }
            }
        }

        fn have_dialog_filters(&self) -> bool {
            self.have_filters
        }

        fn update_dialog_lists(&mut self, _dialog_id: DialogId, source: &str) {
            self.dialog_list_updates.push(source.to_owned());
        }

        fn option_integer(&self, _name: &str, default: i64) -> i64 {
            default
        }

        fn option_boolean(&self, _name: &str, default: bool) -> bool {
            default
        }

        fn binlog_pmc_get(&mut self, key: &str) -> Option<String> {
            self.pmc.get(key).cloned()
        }

        fn binlog_pmc_set(&mut self, key: &str, value: &str) {
            self.pmc.insert(key.to_owned(), value.to_owned());
        }

        fn use_message_database(&self) -> bool {
            true
        }

        fn get_dialog_filter_folder_ids(&self, _filter_id: DialogFilterId) -> Vec<FolderId> {
            Vec::new()
        }

        fn need_dialog_in_filter(
            &self,
            _filter_id: DialogFilterId,
            _info: &DialogFilterDialogInfo,
        ) -> bool {
            false
        }

        fn is_dialog_pinned_in_filter(
            &self,
            _filter_id: DialogFilterId,
            _dialog_id: DialogId,
        ) -> bool {
            false
        }

        fn get_pinned_dialog_ids_in_filter(&self, _filter_id: DialogFilterId) -> Vec<DialogId> {
            Vec::new()
        }

        fn get_scope_disable_mention_notifications(&self) -> bool {
            false
        }

        fn is_bot(&self) -> bool {
            false
        }

        fn close_flag(&self) -> bool {
            false
        }

        fn get_sponsored_chat_source_object(&self) -> Option<td_api::ChatSource> {
            None
        }

        fn is_running_get_difference(&self) -> bool {
            false
        }

        fn is_running_get_channel_difference(&self, _dialog_id: DialogId) -> bool {
            false
        }

        fn has_channel_difference_to_log_event(&self, _dialog_id: DialogId) -> bool {
            false
        }

        fn remove_notification_group(
            &mut self,
            group_id: NotificationGroupId,
            max_notification_message_id: MessageId,
            total_count: i32,
            force: bool,
            _source: &str,
        ) {
            self.removed_groups.push((
                group_id.get(),
                max_notification_message_id.get(),
                total_count,
                force,
            ));
        }

        fn remove_notification(
            &mut self,
            group_id: NotificationGroupId,
            notification_id: NotificationId,
            _is_permanent: bool,
            _force_update: bool,
        ) {
            self.removed_notifications
                .push((group_id.get(), notification_id.get()));
        }

        fn flush_pending_new_message_notifications(
            &mut self,
            _dialog_id: DialogId,
            from_mentions: bool,
            settings_dialog_id: DialogId,
        ) {
            self.flushed.push((from_mentions, settings_dialog_id.get()));
        }

        fn remove_dialog_pinned_message_notification(
            &mut self,
            dialog_id: DialogId,
            _source: &str,
        ) {
            self.pinned_removed.push(dialog_id.get());
        }
    }

    /// A plain incoming server message (counted as unread by
    /// `get_is_counted_as_unread` for the Server type).
    fn m10_7_incoming_message(server_id: i32) -> Message {
        Message {
            message_id: MessageId::from_server_message_id(ServerMessageId::new(server_id)),
            date: 1700000000,
            content: Some(crate::message_content::MessageContent::Text(
                crate::message_content::MessageText::default(),
            )),
            ..Default::default()
        }
    }

    fn m10_7_server_id(server_id: i32) -> MessageId {
        MessageId::from_server_message_id(ServerMessageId::new(server_id))
    }

    /// `OrderedMessage.cpp:447-534` — the calc trio over descending
    /// `(id, is_counted)` slices: missing endpoints, hint acceptance, the
    /// distance-based selection and the negative-result fallback.
    #[test]
    fn m10_7_calc_trio_tables() {
        // descending: 10(counted) 8(counted) 5(not) 2(counted)
        let slice = vec![
            (m10_7_server_id(10), true),
            (m10_7_server_id(8), true),
            (m10_7_server_id(5), false),
            (m10_7_server_id(2), true),
        ];

        // from_last_unread: the counted messages in (2, 10] are 10 and 8 →
        // 5 - 2 = 3 (the uncounted 5 walks through untouched)
        assert_eq!(
            calc_new_unread_count_from_last_unread(
                &slice,
                m10_7_server_id(10),
                m10_7_server_id(2),
                5
            ),
            3
        );
        // a missing max node is -1
        assert_eq!(
            calc_new_unread_count_from_last_unread(
                &slice,
                m10_7_server_id(9),
                m10_7_server_id(2),
                5
            ),
            -1
        );
        // a missing last_read node is -1
        assert_eq!(
            calc_new_unread_count_from_last_unread(
                &slice,
                m10_7_server_id(10),
                m10_7_server_id(7),
                5
            ),
            -1
        );
        // counted messages beyond the old count propagate a negative result
        assert_eq!(
            calc_new_unread_count_from_last_unread(
                &slice,
                m10_7_server_id(10),
                m10_7_server_id(2),
                1
            ),
            -1
        );

        // from_the_end: two counted above 5; exact count (last_message valid,
        // walk stopped on a node)
        assert_eq!(
            calc_new_unread_count_from_the_end(&slice, m10_7_server_id(5), m10_7_server_id(20), -1),
            2
        );
        // exact ⇒ hint accepted only when equal
        assert_eq!(
            calc_new_unread_count_from_the_end(&slice, m10_7_server_id(5), m10_7_server_id(20), 2),
            2
        );
        assert_eq!(
            calc_new_unread_count_from_the_end(&slice, m10_7_server_id(5), m10_7_server_id(20), 3),
            2
        );
        // inexact (last_message invalid) ⇒ hint accepted when >= the count
        assert_eq!(
            calc_new_unread_count_from_the_end(&slice, m10_7_server_id(5), MessageId::default(), 5),
            5
        );
        assert_eq!(
            calc_new_unread_count_from_the_end(&slice, m10_7_server_id(5), MessageId::default(), 1),
            -1
        );
        // inexact without a usable hint is -1
        assert_eq!(
            calc_new_unread_count_from_the_end(
                &slice,
                m10_7_server_id(5),
                MessageId::default(),
                -1
            ),
            -1
        );

        // dispatcher: last_read(2) is closer to max(10) than last_message(20)
        // (20-10 > 10-2) ⇒ from_last_unread first (3), no fallback needed
        assert_eq!(
            calc_new_unread_count(
                &slice,
                m10_7_server_id(10),
                m10_7_server_id(2),
                5,
                m10_7_server_id(20),
                2
            ),
            3
        );
        // dispatcher: max(5) is closer to last_message(20) than to
        // last_read(2)? No (20-5 > 5-2) ⇒ still from_last_unread first —
        // the node 5 walk is uncounted, so 5
        assert_eq!(
            calc_new_unread_count(
                &slice,
                m10_7_server_id(5),
                m10_7_server_id(2),
                5,
                m10_7_server_id(20),
                -1
            ),
            5
        );
        // dispatcher: max(9) closer to last_message(11) (11-9 <= 9-2) ⇒
        // from_the_end first: one counted message above 9
        assert_eq!(
            calc_new_unread_count(
                &slice,
                m10_7_server_id(9),
                m10_7_server_id(2),
                5,
                m10_7_server_id(11),
                -1
            ),
            1
        );
        // dispatcher: invalid last_message ⇒ from_last_unread first; its -1
        // (missing max node) falls back to from_the_end, which is -1 too
        // (inexact, no hint)
        assert_eq!(
            calc_new_unread_count(
                &slice,
                m10_7_server_id(9),
                m10_7_server_id(2),
                5,
                MessageId::default(),
                -1
            ),
            -1
        );
        // dispatcher: negative from_last_unread propagates into the
        // from_the_end fallback (exact ⇒ 0 — nothing above 10)
        assert_eq!(
            calc_new_unread_count(
                &slice,
                m10_7_server_id(10),
                m10_7_server_id(2),
                1,
                m10_7_server_id(20),
                -1
            ),
            0
        );
        // dispatcher: invalid last_read ⇒ from_the_end only, no fallback
        assert_eq!(
            calc_new_unread_count(
                &slice,
                m10_7_server_id(5),
                MessageId::default(),
                9,
                m10_7_server_id(20),
                -1
            ),
            2
        );

        // need_unread_counter (MessagesManager.cpp:9672-9674)
        assert!(!need_unread_counter(DEFAULT_ORDER));
        assert!(need_unread_counter(0));
        assert!(need_unread_counter(5));
    }

    /// The `read_history_inbox` gate ladder (MessagesManager.cpp:9522-9613):
    /// the invalid-id rejection, the `MessageId()` zero sentinel, the
    /// stale-id re-arm behind the consumed
    /// `need_repair_channel_server_unread_count` flag (counters-only
    /// `MessageId::min()`), the yet-unsent rejection, the unknown-unread
    /// clamp and the marked-as-unread clear.
    #[test]
    fn m10_7_inbox_gate_table() {
        let ctx = TestObjectContext::default();
        let mut state = ReadStateTestContext::default();
        let mut manager = MessagesManager::new();
        let dialog_id = DialogId::from_user_id(UserId::new(3000));

        // (a) a non-zero invalid id is rejected without any state change
        // (`MessageId::new(3)`: non-scheduled, type bits 3 → invalid)
        manager.add_dialog_for_new_message(dialog_id);
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        d.server_unread_count = 4;
        read_history_inbox(
            &mut manager,
            &ctx,
            &mut state,
            dialog_id,
            MessageId::new(3),
            4,
            "test",
        );
        let d = manager.get_dialog(dialog_id).unwrap();
        assert_eq!(d.server_unread_count, 4);
        assert!(!d.is_last_read_inbox_message_id_inited);
        assert!(state.updates.is_empty());

        // (b) a yet-unsent id is rejected (the C++ `MessageId::min()` shape)
        read_history_inbox(
            &mut manager,
            &ctx,
            &mut state,
            dialog_id,
            MessageId::min(),
            0,
            "test",
        );
        let d = manager.get_dialog(dialog_id).unwrap();
        assert!(!d.is_last_read_inbox_message_id_inited);
        assert!(state.updates.is_empty());

        // (c) the MessageId() zero sentinel passes ("read up to 0")
        read_history_inbox(
            &mut manager,
            &ctx,
            &mut state,
            dialog_id,
            MessageId::default(),
            4,
            "test",
        );
        let d = manager.get_dialog(dialog_id).unwrap();
        assert_eq!(d.last_read_inbox_message_id, MessageId::default());
        assert!(d.is_last_read_inbox_message_id_inited);
        assert_eq!(
            d.server_unread_count, 4,
            "the unknown-unread hint wins over the empty slice"
        );
        match state.updates.remove(0) {
            td_api::Object::updateChatReadInbox(update) => {
                assert_eq!(update.last_read_inbox_message_id, 0);
                assert_eq!(update.unread_count, 4);
            }
            other => panic!("expected updateChatReadInbox, got {other:?}"),
        }
        assert!(state.updates.is_empty());

        // (d) the stale equal-id re-arm: the consumed
        // need_repair_channel_server_unread_count flag arms a counters-only
        // `MessageId::min()` setter call
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        d.last_read_inbox_message_id = m10_7_server_id(10);
        d.need_repair_channel_server_unread_count = true;
        read_history_inbox(
            &mut manager,
            &ctx,
            &mut state,
            dialog_id,
            m10_7_server_id(10),
            5,
            "test",
        );
        let d = manager.get_dialog(dialog_id).unwrap();
        assert_eq!(
            d.last_read_inbox_message_id,
            m10_7_server_id(10),
            "the id is not rewritten"
        );
        assert!(d.is_last_read_inbox_message_id_inited);
        assert_eq!(d.server_unread_count, 5, "only the counters move");
        assert!(
            !d.need_repair_channel_server_unread_count,
            "the flag is consumed once"
        );
        match state.updates.remove(0) {
            td_api::Object::updateChatReadInbox(update) => assert_eq!(update.unread_count, 5),
            other => panic!("expected updateChatReadInbox, got {other:?}"),
        }
        assert!(state.updates.is_empty());

        // (e) a stale smaller id without the re-arm arm is a plain return
        read_history_inbox(
            &mut manager,
            &ctx,
            &mut state,
            dialog_id,
            m10_7_server_id(8),
            7,
            "test",
        );
        let d = manager.get_dialog(dialog_id).unwrap();
        assert_eq!(d.server_unread_count, 5);
        assert!(state.updates.is_empty());

        // (f) the unknown-unread clamp: an invalid last_new_message_id with a
        // positive hint clamps the hint to 0
        read_history_inbox(
            &mut manager,
            &ctx,
            &mut state,
            dialog_id,
            m10_7_server_id(15),
            7,
            "test",
        );
        let d = manager.get_dialog(dialog_id).unwrap();
        assert_eq!(
            d.server_unread_count, 0,
            "the clamp zeroed the unknown hint"
        );
        assert_eq!(d.last_read_inbox_message_id, m10_7_server_id(15));
        let _ = state.updates.remove(0);

        // (g) reading history clears the marked-as-unread flag
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        d.is_marked_as_unread = true;
        d.is_last_read_inbox_message_id_inited = false; // re-open the stale gate
        read_history_inbox(
            &mut manager,
            &ctx,
            &mut state,
            dialog_id,
            m10_7_server_id(16),
            0,
            "test",
        );
        let d = manager.get_dialog(dialog_id).unwrap();
        assert!(!d.is_marked_as_unread);
        match state.updates.remove(0) {
            td_api::Object::updateChatReadInbox(update) => assert_eq!(update.unread_count, 0),
            other => panic!("expected updateChatReadInbox, got {other:?}"),
        }
        match state.updates.remove(0) {
            td_api::Object::updateChatIsMarkedAsUnread(update) => {
                assert!(!update.is_marked_as_unread)
            }
            other => panic!("expected updateChatIsMarkedAsUnread, got {other:?}"),
        }
        assert!(state.updates.is_empty());
    }

    /// The `read_history_inbox` recount over a populated ordered slice: the
    /// clamp + recount override and the from-the-end selection with the
    /// exact-count win over a stale hint.
    #[test]
    fn m10_7_read_inbox_recount_tables() {
        let ctx = TestObjectContext::default();
        let mut state = ReadStateTestContext::default();
        let mut manager = MessagesManager::new();
        let dialog_id = DialogId::from_user_id(UserId::new(8000));
        manager.add_dialog_for_new_message(dialog_id);
        {
            let d = manager.get_dialog_mut(dialog_id).unwrap();
            for server_id in 11..=15 {
                let m = m10_7_incoming_message(server_id);
                d.messages.insert(m.message_id, Box::new(m));
            }
            d.last_new_message_id = m10_7_server_id(15);
            d.last_message_id = m10_7_server_id(15);
            d.last_database_message_id = m10_7_server_id(15);
            d.server_unread_count = 4;
        }

        // max == last_new with an unknown hint → the clamp keeps the old
        // server count, then the exact recount finds all five messages read
        // and lands on 0
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        d.last_read_inbox_message_id = m10_7_server_id(10);
        d.is_last_read_inbox_message_id_inited = true;
        read_history_inbox(
            &mut manager,
            &ctx,
            &mut state,
            dialog_id,
            m10_7_server_id(15),
            3,
            "test",
        );
        let d = manager.get_dialog(dialog_id).unwrap();
        assert_eq!(
            d.server_unread_count, 0,
            "4 - 5 counted between 10 and 15 clamps at the exact recount"
        );
        assert_eq!(d.last_read_inbox_message_id, m10_7_server_id(15));

        // a mid-history max: from-the-end runs first (max 13 is closer to
        // last_read 10 than to last_message 15) and its exact count of the
        // two messages above (14, 15) beats the stale zero hint
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        d.last_read_inbox_message_id = m10_7_server_id(10);
        d.server_unread_count = 4;
        read_history_inbox(
            &mut manager,
            &ctx,
            &mut state,
            dialog_id,
            m10_7_server_id(13),
            0,
            "test",
        );
        let d = manager.get_dialog(dialog_id).unwrap();
        assert_eq!(
            d.server_unread_count, 2,
            "two counted messages (14, 15) above 13"
        );
        assert_eq!(d.last_read_inbox_message_id, m10_7_server_id(13));
    }

    /// The `read_history_outbox` gate ladder (MessagesManager.cpp:9630-9670):
    /// the invalid rejection (the zero id included — no sentinel here), the
    /// unguarded monotonic gate, the yet-unsent rejection and the setter +
    /// `updateChatReadOutbox` emission.
    #[test]
    fn m10_7_outbox_gate_table() {
        let ctx = TestObjectContext::default();
        let mut state = ReadStateTestContext::default();
        let mut manager = MessagesManager::new();
        let dialog_id = DialogId::from_user_id(UserId::new(7000));
        manager.add_dialog_for_new_message(dialog_id);
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        d.last_new_message_id = m10_7_server_id(12);
        d.last_message_id = m10_7_server_id(12);

        // the zero id is invalid for the outbox (no sentinel arm)
        read_history_outbox(
            &mut manager,
            &ctx,
            &mut state,
            dialog_id,
            MessageId::default(),
            0,
        );
        let d = manager.get_dialog(dialog_id).unwrap();
        assert!(!d.is_last_read_outbox_message_id_inited);
        assert!(state.updates.is_empty());

        // the yet-unsent id is rejected
        read_history_outbox(
            &mut manager,
            &ctx,
            &mut state,
            dialog_id,
            MessageId::min(),
            0,
        );
        assert!(state.updates.is_empty());

        // a stale id returns without the is_*_inited arm
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        d.last_read_outbox_message_id = m10_7_server_id(10);
        read_history_outbox(
            &mut manager,
            &ctx,
            &mut state,
            dialog_id,
            m10_7_server_id(9),
            0,
        );
        let d = manager.get_dialog(dialog_id).unwrap();
        assert_eq!(d.last_read_outbox_message_id, m10_7_server_id(10));
        assert!(state.updates.is_empty());

        // success: the monotonic move + the emitter
        read_history_outbox(
            &mut manager,
            &ctx,
            &mut state,
            dialog_id,
            m10_7_server_id(12),
            1700000000,
        );
        let d = manager.get_dialog(dialog_id).unwrap();
        assert_eq!(d.last_read_outbox_message_id, m10_7_server_id(12));
        assert!(d.is_last_read_outbox_message_id_inited);
        match state.updates.remove(0) {
            td_api::Object::updateChatReadOutbox(update) => {
                assert_eq!(
                    update.last_read_outbox_message_id,
                    m10_7_server_id(12).get()
                );
            }
            other => panic!("expected updateChatReadOutbox, got {other:?}"),
        }
        assert!(state.updates.is_empty());
    }

    /// The `set_dialog_last_read_inbox_message_id` list-counter decision
    /// table (MessagesManager.cpp:9942-9965) over a fake list: the delta
    /// arithmetic, the 0↔nonzero crossing, the marked-as-unread sign flip,
    /// the muted sub-counters, the *_inited guards, the
    /// `need_unread_counter` gate and the counters-only `MessageId::min()`.
    #[test]
    fn m10_7_setter_counter_table() {
        let ctx = TestObjectContext::default();
        let mut state = ReadStateTestContext {
            muted: true,
            lists: vec![
                DialogListUnreadCounters {
                    unread_message_total_count: 100,
                    unread_message_muted_count: 40,
                    unread_dialog_total_count: 10,
                    unread_dialog_marked_count: 2,
                    unread_dialog_muted_count: 6,
                    unread_dialog_muted_marked_count: 1,
                    is_message_unread_count_inited: true,
                    is_dialog_unread_count_inited: true,
                },
                DialogListUnreadCounters::default(), // nothing inited — a dead list
            ],
            ..Default::default()
        };
        let mut manager = MessagesManager::new();
        let dialog_id = DialogId::from_user_id(UserId::new(5000));
        manager.add_dialog_for_new_message(dialog_id);
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        d.order = 5; // need_unread_counter true
        d.server_unread_count = 3;
        d.local_unread_count = 1;

        // non-crossing: 4 → 1 moves only the message counters (delta -3 on
        // the muted list; the dialog count 1→1 has zero delta)
        set_dialog_last_read_inbox_message_id(
            &mut manager,
            &ctx,
            &mut state,
            dialog_id,
            m10_7_server_id(20),
            1,
            0,
            false,
            "test",
        );
        {
            let list = state.lists[0];
            assert_eq!(list.unread_message_total_count, 97);
            assert_eq!(
                list.unread_message_muted_count, 37,
                "the muted sub-counter moves too"
            );
            assert_eq!(
                list.unread_dialog_total_count, 10,
                "no crossing — the dialog count holds"
            );
            assert_eq!(list.unread_dialog_marked_count, 2);
        }
        assert_eq!(
            state.lists[1],
            DialogListUnreadCounters::default(),
            "the dead list is untouched"
        );
        assert_eq!(state.unread_message_count_updates, 1);
        assert_eq!(state.unread_chat_count_updates, 0);
        let d = manager.get_dialog(dialog_id).unwrap();
        assert_eq!(d.last_read_inbox_message_id, m10_7_server_id(20));
        assert!(d.is_last_read_inbox_message_id_inited);
        match state.updates.remove(0) {
            td_api::Object::updateChatReadInbox(update) => assert_eq!(update.unread_count, 1),
            other => panic!("expected updateChatReadInbox, got {other:?}"),
        }

        // crossing to zero on an unmarked dialog: delta -1 lands on
        // total + muted (the sign flip trap lives in the marked arm below)
        set_dialog_last_read_inbox_message_id(
            &mut manager,
            &ctx,
            &mut state,
            dialog_id,
            m10_7_server_id(21),
            0,
            0,
            false,
            "test",
        );
        {
            let list = state.lists[0];
            assert_eq!(list.unread_message_total_count, 96, "1 → 0 is delta -1");
            assert_eq!(list.unread_message_muted_count, 36);
            assert_eq!(list.unread_dialog_total_count, 9);
            assert_eq!(list.unread_dialog_muted_count, 5);
            assert_eq!(
                list.unread_dialog_marked_count, 2,
                "the marked count is untouched for an unmarked dialog"
            );
        }
        assert_eq!(state.unread_chat_count_updates, 1);
        let _ = state.updates.remove(0);

        // the marked sign flip: refilling to 2 marked dialogs routes the
        // +delta into unread_dialog_marked_count_ (decrement of a negative
        // delta) and into the muted-marked sub-counter
        let d = manager.get_dialog_mut(dialog_id).unwrap();
        d.is_marked_as_unread = true;
        set_dialog_last_read_inbox_message_id(
            &mut manager,
            &ctx,
            &mut state,
            dialog_id,
            m10_7_server_id(22),
            1,
            1,
            false,
            "test",
        );
        {
            let list = state.lists[0];
            assert_eq!(list.unread_message_total_count, 98, "0 → 2 is delta +2");
            assert_eq!(
                list.unread_dialog_marked_count, 1,
                "marked -= delta (2 - (+1))"
            );
            assert_eq!(
                list.unread_dialog_muted_marked_count, 0,
                "muted-marked -= delta (1 - (+1))"
            );
            assert_eq!(
                list.unread_dialog_total_count, 9,
                "the total is untouched for a marked dialog"
            );
        }
        assert_eq!(state.unread_chat_count_updates, 2);
        let _ = state.updates.remove(0);

        // the counters-only MessageId::min(): the id halves are skipped, the
        // counter table still runs
        set_dialog_last_read_inbox_message_id(
            &mut manager,
            &ctx,
            &mut state,
            dialog_id,
            MessageId::min(),
            3,
            1,
            false,
            "test",
        );
        let d = manager.get_dialog(dialog_id).unwrap();
        assert_eq!(
            d.last_read_inbox_message_id,
            m10_7_server_id(22),
            "min() never writes the id"
        );
        assert_eq!(d.server_unread_count, 3);
        assert_eq!(d.local_unread_count, 1);
        {
            let list = state.lists[0];
            assert_eq!(list.unread_message_total_count, 100, "2 → 4 is delta +2");
            assert_eq!(
                list.unread_dialog_marked_count, 1,
                "no crossing — the marked count holds"
            );
        }

        // the need_unread_counter gate: a DEFAULT_ORDER dialog skips the
        // whole table
        let mut state2 = ReadStateTestContext {
            lists: vec![DialogListUnreadCounters {
                is_message_unread_count_inited: true,
                is_dialog_unread_count_inited: true,
                ..DialogListUnreadCounters::default()
            }],
            ..Default::default()
        };
        let mut manager2 = MessagesManager::new();
        let dialog_id2 = DialogId::from_user_id(UserId::new(5001));
        manager2.add_dialog_for_new_message(dialog_id2);
        let d = manager2.get_dialog_mut(dialog_id2).unwrap();
        assert_eq!(d.order, DEFAULT_ORDER);
        set_dialog_last_read_inbox_message_id(
            &mut manager2,
            &ctx,
            &mut state2,
            dialog_id2,
            m10_7_server_id(20),
            1,
            0,
            false,
            "test",
        );
        assert_eq!(state2.unread_message_count_updates, 0);
        assert_eq!(state2.unread_chat_count_updates, 0);
        assert_eq!(
            state2.lists[0],
            DialogListUnreadCounters {
                is_message_unread_count_inited: true,
                is_dialog_unread_count_inited: true,
                ..DialogListUnreadCounters::default()
            }
        );
        assert!(state2.dialog_list_updates.is_empty());
    }

    /// `read_all_dialog_mentions` (MessagesManager.cpp:9134-9188): the
    /// per-message clear (the notification removal strictly before the flag,
    /// per the C++ comment), the emitter degradation for not-yet-sent
    /// messages, the counter reset and the last_read_all_mentions bump.
    #[test]
    fn m10_7_mentions_clear_ordering() {
        let ctx = TestObjectContext::default();
        let mut state = ReadStateTestContext::default();
        let global = crate::global::Global::new();
        let time = crate::user_manager::TimeCtx::from_global(&global);
        let mut manager = MessagesManager::new();
        let dialog_id = DialogId::from_user_id(UserId::new(6000));
        manager.add_dialog_for_new_message(dialog_id);
        {
            let d = manager.get_dialog_mut(dialog_id).unwrap();
            for server_id in 11..=13 {
                let mut m = m10_7_incoming_message(server_id);
                m.contains_mention = true;
                m.contains_unread_mention = true;
                d.messages.insert(m.message_id, Box::new(m));
            }
            d.last_new_message_id = m10_7_server_id(13);
            d.last_message_id = m10_7_server_id(13);
            d.unread_mention_count = 3;
            d.message_count_by_index
                [message_search_filter_index(MessageSearchFilter::UnreadMention) as usize] = 3;
        }

        read_all_dialog_mentions(
            &global,
            &mut manager,
            &ctx,
            &mut state,
            &time,
            dialog_id,
            ForumTopicId::default(),
        )
        .unwrap();

        let d = manager.get_dialog(dialog_id).unwrap();
        assert!(d.messages.values().all(|m| !m.contains_unread_mention));
        assert!(
            d.messages
                .values()
                .all(|m| m.removed_notification_id == NotificationId::default())
        );
        assert_eq!(d.unread_mention_count, 0);
        assert_eq!(
            d.message_count_by_index
                [message_search_filter_index(MessageSearchFilter::UnreadMention) as usize],
            0
        );
        assert_eq!(
            d.last_read_all_mentions_message_id,
            m10_7_server_id(13),
            "bumped to last_new_message_id"
        );
        // every not-yet-sent message degrades updateMessageMentionRead to the
        // chat-level update, one per message, then the tail skips the chat
        // update because an update was already sent
        assert_eq!(
            state.updates.len(),
            3,
            "one updateChatUnreadMentionCount per mention"
        );
        for update in &state.updates {
            match update {
                td_api::Object::updateChatUnreadMentionCount(update) => {
                    assert_eq!(update.unread_mention_count, 0)
                }
                other => panic!("expected updateChatUnreadMentionCount, got {other:?}"),
            }
        }

        // the sent-message arm emits updateMessageMentionRead per message
        let mut state2 = ReadStateTestContext::default();
        let dialog_id2 = DialogId::from_user_id(UserId::new(6001));
        manager.add_dialog_for_new_message(dialog_id2);
        {
            let d = manager.get_dialog_mut(dialog_id2).unwrap();
            let mut m = m10_7_incoming_message(21);
            m.contains_mention = true;
            m.contains_unread_mention = true;
            m.is_update_sent = true;
            d.messages.insert(m.message_id, Box::new(m));
            d.last_new_message_id = m10_7_server_id(21);
            d.last_message_id = m10_7_server_id(21);
            d.unread_mention_count = 1;
        }
        read_all_dialog_mentions(
            &global,
            &mut manager,
            &ctx,
            &mut state2,
            &time,
            dialog_id2,
            ForumTopicId::default(),
        )
        .unwrap();
        assert_eq!(state2.updates.len(), 1);
        match state2.updates.remove(0) {
            td_api::Object::updateMessageMentionRead(update) => {
                assert_eq!(update.message_id, m10_7_server_id(21).get());
                assert_eq!(update.unread_mention_count, 0);
            }
            other => panic!("expected updateMessageMentionRead, got {other:?}"),
        }

        // a valid topic id on a non-forum chat is a 400 before any state move
        let err = read_all_dialog_mentions(
            &global,
            &mut manager,
            &ctx,
            &mut state2,
            &time,
            dialog_id,
            ForumTopicId(7),
        )
        .unwrap_err();
        assert_eq!(err.code(), 400);
        assert_eq!(err.message(), "Chat doesn't have topics");
    }

